        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

        function playSfx(type, isPositive) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const osc = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();
            osc.connect(gainNode);
            gainNode.connect(audioCtx.destination);
            
            const now = audioCtx.currentTime;
            
            if (type === 'xp') {
                osc.type = 'sine';
                if (isPositive) {
                    osc.frequency.setValueAtTime(400, now);
                    osc.frequency.exponentialRampToValueAtTime(800, now + 0.1);
                    gainNode.gain.setValueAtTime(0.3, now);
                    gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.2);
                    osc.start(now);
                    osc.stop(now + 0.2);
                } else {
                    osc.frequency.setValueAtTime(300, now);
                    osc.frequency.exponentialRampToValueAtTime(150, now + 0.15);
                    gainNode.gain.setValueAtTime(0.3, now);
                    gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.2);
                    osc.start(now);
                    osc.stop(now + 0.2);
                }
            } else if (type === 'bong') {
                if (isPositive) {
                    osc.type = 'square';
                    osc.frequency.setValueAtTime(600, now);
                    osc.frequency.setValueAtTime(900, now + 0.05);
                    gainNode.gain.setValueAtTime(0.1, now);
                    gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.15);
                    osc.start(now);
                    osc.stop(now + 0.15);
                } else {
                    osc.type = 'sawtooth';
                    osc.frequency.setValueAtTime(150, now);
                    gainNode.gain.setValueAtTime(0.2, now);
                    gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.2);
                    osc.start(now);
                    osc.stop(now + 0.2);
                }
            }
        }

        /** 학습 온도계: 값 높이에 맞는 짧은 음(0=440Hz, 위=고음, 아래=저음) */
        function playLearningThermometerSfx(value) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const v = Math.round(Number(value) || 0);
            const freq = 440 * Math.pow(2, v / 24);
            const now = audioCtx.currentTime;
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.connect(gain);
            gain.connect(audioCtx.destination);

            if (v < 0) {
                // 저음은 sine보다 잘 들리도록 파형·볼륨·길이를 키움
                osc.type = 'triangle';
                const depth = Math.min(1, Math.abs(v) / 20);
                const gainPeak = 0.22 + depth * 0.28;
                const duration = 0.1 + depth * 0.08;
                osc.frequency.setValueAtTime(freq, now);
                gain.gain.setValueAtTime(gainPeak, now);
                gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
                osc.start(now);
                osc.stop(now + duration + 0.02);
            } else {
                osc.type = 'sine';
                const gainPeak = v > 0 ? 0.14 : 0.15;
                const duration = 0.09;
                osc.frequency.setValueAtTime(freq, now);
                gain.gain.setValueAtTime(gainPeak, now);
                gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
                osc.start(now);
                osc.stop(now + duration + 0.01);
            }
        }

