        /** 공통: 새 학급 Firestore 워크스페이스 생성 */
        async function createClassWorkspace({ displayName, schoolYear, grade, homeroom, teacherName, studentCount, teacherPin, copySettingsFromCurrent, schoolName, seasonLabel, seasonTheme, applyDefaultTemplate, raidPassword }) {
            if (!db) throw new Error('no_db');
            const inviteCode = await generateUniqueInviteCode().catch(() => generateInviteCode());
            let newClassId = buildClassIdFromMeta({ schoolYear, grade, homeroom });
            // 충돌 시 접미사 재생성
            for (let i = 0; i < 5; i++) {
                const existing = await getDoc(doc(db, 'classes', newClassId));
                if (!existing.exists()) break;
                newClassId = buildClassIdFromMeta({ schoolYear, grade, homeroom, suffix: Math.random().toString(36).slice(2, 6) });
            }
            const newMeta = buildBlankClassMeta(newClassId, {
                displayName,
                schoolYear,
                grade,
                homeroom,
                teacherName,
                studentCount,
                inviteCode,
                schoolName,
                masterDisplayName: teacherName,
            });
            await setDoc(doc(db, 'classes', newClassId), {
                ...newMeta,
                createdAt: serverTimestamp(),
                updatedAt: serverTimestamp(),
            }, { merge: true });
            await registerInviteCode(inviteCode, newClassId, { displayName });

            // 기본 운영 설정 (현재 학급 복사 또는 최소 기본값)
            if (copySettingsFromCurrent) {
                const globalSnap = await getDoc(doc(db, 'artifacts', appId, 'public', 'data', 'settings', 'global'));
                if (globalSnap.exists()) {
                    const src = globalSnap.data();
                    const { announcement, lastAutoXpTime, lastSalaryWeek, researchJournal, ...copySettings } = src;
                    await setDoc(doc(db, 'artifacts', newClassId, 'public', 'data', 'settings', 'global'), {
                        ...copySettings,
                        worldSettings: {
                            ...(copySettings.worldSettings || {}),
                            worldName: deriveWorldNameFromSchool(schoolName) || displayName || 'MATE',
                            worldNameEn: deriveWorldNameFromSchool(schoolName) || displayName || 'MATE',
                            footerCredit: `${deriveWorldNameFromSchool(schoolName) || displayName || 'MATE'} · ${teacherName || '담임 선생님'}`,
                        },
                    }, { merge: true });
                }
            } else {
                const raidPw = String(raidPassword || '').trim() || createRandomRaidPassword();
                const derivedWorld = deriveWorldNameFromSchool(schoolName) || displayName || 'MATE';
                await setDoc(doc(db, 'artifacts', newClassId, 'public', 'data', 'settings', 'global'), {
                    raidPassword: raidPw,
                    raidPasswordNeedsSetup: !String(raidPassword || '').trim(),
                    shieldStock: 10,
                    weekendRaidRewardXp: 40,
                    weekendRaidRewardBong: 20,
                    curriculumTags: DEFAULT_CURRICULUM_TAGS,
                    curriculumMapping: DEFAULT_CURRICULUM_MAPPING,
                    worldSettings: {
                        worldName: derivedWorld,
                        worldNameEn: derivedWorld,
                        navBadge: 'S1',
                        seasonNumber: 1,
                        seasonLabel: String(seasonLabel || '시즌 1').trim().slice(0, 30) || '시즌 1',
                        seasonTheme: String(seasonTheme || '우리 반 모험').trim().slice(0, 60) || '우리 반 모험',
                        academicYear: schoolYear,
                        footerCredit: `${derivedWorld} · ${teacherName || '담임 선생님'}`,
                    },
                    applyDefaultTemplatePending: !!applyDefaultTemplate,
                }, { merge: true });
            }

            if (teacherPin) {
                const pin = String(teacherPin).trim();
                if (/^\d{4}$/.test(pin)) {
                    await setDoc(doc(db, 'artifacts', newClassId, 'public', 'data', 'students', 'student_gm'), {
                        pin,
                        xp: 0,
                        bong: 0,
                        quests: {},
                        unlockedQuests: {},
                        jobs: [],
                        inventory: [],
                        questHistory: [],
                    }, { merge: true });
                }
            }

            rememberRecentClass(newClassId, displayName, inviteCode);
            return { newClassId, inviteCode, newMeta };
        }

        window.createClassFromLogin = async function() {
            if (!db) return window.customAlert('서버 연결 중입니다. 잠시 후 다시 시도해 주세요.');
            const displayName = String(document.getElementById('createClassDisplayName')?.value || '').trim();
            const schoolName = String(document.getElementById('createClassSchoolName')?.value || '').trim();
            const schoolYear = Number(document.getElementById('createClassYear')?.value) || new Date().getFullYear();
            const gradeRaw = document.getElementById('createClassGrade')?.value;
            const grade = gradeRaw === '' || gradeRaw == null ? 6 : Number(gradeRaw);
            const homeroom = Number(document.getElementById('createClassHomeroom')?.value) || 1;
            const teacherName = String(document.getElementById('createClassTeacherName')?.value || '').trim() || '담임 선생님';
            const seasonLabel = String(document.getElementById('createClassSeasonName')?.value || '').trim() || '시즌 1';
            const seasonTheme = String(document.getElementById('createClassSeasonTheme')?.value || '').trim() || '우리 반 모험';
            const studentCount = Number(document.getElementById('createClassStudentCount')?.value) || 25;
            const teacherPin = String(document.getElementById('createClassTeacherPin')?.value || '').trim();
            const applyDefaultTemplate = !!(document.getElementById('createClassApplyTemplate')?.checked);
            if (!displayName) {
                return window.customAlert('학급명은 필수입니다.');
            }
            if (!/^\d{4}$/.test(teacherPin)) {
                return window.customAlert('마스터 PIN은 숫자 4자리로 설정해 주세요.');
            }
            const ok = await window.customConfirm(
                `새 학급을 만듭니다.\n\n` +
                `학급명: ${displayName}\n` +
                (schoolName ? `학교: ${schoolName}\n` : '') +
                `${schoolYear}학년도 ${grade}학년 ${homeroom}반\n` +
                `시즌: ${seasonLabel} / ${seasonTheme}\n` +
                `마스터: ${teacherName}\n` +
                `기본 템플릿: ${applyDefaultTemplate ? '적용' : '나중에'}\n\n` +
                `생성 후 이 학급으로 이동하며, 초대 코드가 발급됩니다.`
            );
            if (!ok) return;
            try {
                window.showGlobalLoading('잠시만 기다려 주세요…');
                const authOk = await ensureAnonAuthReady();
                if (!authOk) throw new Error('인증에 실패했습니다. 네트워크를 확인한 뒤 다시 시도해 주세요.');
                const { newClassId, inviteCode } = await createClassWorkspace({
                    displayName,
                    schoolName,
                    schoolYear,
                    grade,
                    homeroom,
                    teacherName,
                    studentCount,
                    teacherPin,
                    seasonLabel,
                    seasonTheme,
                    applyDefaultTemplate,
                    copySettingsFromCurrent: false,
                });
                localStorage.setItem('sambong_student_id', 'gm');
                localStorage.setItem('sambong_student_pin', teacherPin);
                localStorage.setItem('sambong_show_onboarding', '1');
                localStorage.setItem('sambong_onboarding_invite', inviteCode);
                window.hideGlobalLoading();
                const share = getClassShareUrl(newClassId, inviteCode);
                await window.customAlert(
                    `✅ 학급이 준비되었습니다!\n\n` +
                    `초대 코드: ${inviteCode}\n` +
                    `접속 링크:\n${share}\n\n` +
                    `학생에게 코드 또는 링크를 공유하세요.`
                );
                window.switchClass(newClassId);
            } catch (e) {
                console.error('createClassFromLogin', e);
                window.hideGlobalLoading();
                await window.customAlert('학급 생성 실패: ' + (e && e.message ? e.message : String(e)));
            } finally {
                window.hideGlobalLoading();
            }
        };

        window.renderClassAdminPanel = function() {
            const panel = document.getElementById('classAdminPanel');
            if (!panel || !window.playerState?.isGM) return;
            const meta = window.classMeta || (appId === SEED_CLASS_ID ? buildDefaultClassMeta(appId) : buildBlankClassMeta(appId));
            const rosterRows = (meta.roster || []).map((r, idx) => `
                <tr class="border-b border-slate-700/80">
                    <td class="p-1"><input type="text" data-roster-idx="${idx}" data-roster-field="id" value="${r.id || ''}" class="w-10 bg-slate-900 border border-slate-700 rounded px-1 py-0.5 text-[10px] text-white"></td>
                    <td class="p-1"><input type="text" data-roster-idx="${idx}" data-roster-field="name" value="${r.name || ''}" class="w-full bg-slate-900 border border-slate-700 rounded px-1 py-0.5 text-[10px] text-white"></td>
                    <td class="p-1">
                        <select data-roster-idx="${idx}" data-roster-field="gender" class="bg-slate-900 border border-slate-700 rounded px-1 py-0.5 text-[10px] text-white">
                            <option value="M" ${r.gender !== 'F' ? 'selected' : ''}>남</option>
                            <option value="F" ${r.gender === 'F' ? 'selected' : ''}>여</option>
                        </select>
                    </td>
                    <td class="p-1"><input type="text" data-roster-idx="${idx}" data-roster-field="label" value="${r.label || ''}" placeholder="별칭" class="w-full bg-slate-900 border border-slate-700 rounded px-1 py-0.5 text-[10px] text-white"></td>
                    <td class="p-1 text-center"><input type="checkbox" data-roster-idx="${idx}" data-roster-field="active" ${r.active !== false ? 'checked' : ''}></td>
                </tr>`).join('');
            panel.innerHTML = `
                <div class="grid sm:grid-cols-2 gap-3 mb-3">
                    <label class="text-[10px] text-slate-300">학급 표시 이름
                        <input id="classMetaDisplayName" type="text" value="${meta.displayName || ''}" class="mt-1 w-full bg-slate-900 border border-slate-700 rounded px-2 py-1 text-xs text-white">
                    </label>
                    <label class="text-[10px] text-slate-300">학급 ID (데이터 경로)
                        <input type="text" value="${appId}" readonly class="mt-1 w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-xs text-slate-400">
                    </label>
                    <label class="text-[10px] text-slate-300">학년도
                        <input id="classMetaSchoolYear" type="number" min="2020" max="2100" value="${meta.schoolYear || 2026}" class="mt-1 w-full bg-slate-900 border border-slate-700 rounded px-2 py-1 text-xs text-white">
                    </label>
                    <label class="text-[10px] text-slate-300">학년 · 반
                        <div class="mt-1 flex gap-2">
                            <input id="classMetaGrade" type="number" min="1" max="6" value="${meta.grade || 6}" class="w-16 bg-slate-900 border border-slate-700 rounded px-2 py-1 text-xs text-white">
                            <input id="classMetaHomeroom" type="number" min="1" max="20" value="${meta.homeroom || 1}" class="w-16 bg-slate-900 border border-slate-700 rounded px-2 py-1 text-xs text-white">
                        </div>
                    </label>
                </div>
                <p class="text-[9px] text-slate-500 mb-2">
                    초대 코드: <span class="text-emerald-300 font-bold tracking-widest">${meta.inviteCode || '(저장 후 생성)'}</span>
                    <button type="button" onclick="window.copyTeacherInviteCode()" class="ml-1 text-[9px] text-sky-300 underline">복사</button>
                    · GMA 편집 학번: ${meta.gmaEditStudentId || '1'}
                </p>
                <p class="text-[9px] text-slate-500 mb-2 break-all">공유 링크: <span class="text-sky-300/90">${getClassShareUrl(appId)}</span>
                    <button type="button" onclick="window.copyTeacherClassLink()" class="ml-1 text-[9px] text-sky-300 underline">복사</button>
                </p>
                <div class="overflow-x-auto max-h-[240px] overflow-y-auto rounded border border-slate-700 mb-3">
                    <table class="w-full text-[10px]">
                        <thead><tr class="text-slate-400 border-b border-slate-700"><th class="p-1">번호</th><th class="p-1">이름</th><th class="p-1">성별</th><th class="p-1">별칭</th><th class="p-1">활성</th></tr></thead>
                        <tbody id="classRosterEditorBody">${rosterRows}</tbody>
                    </table>
                </div>
                <div class="flex flex-wrap gap-2 mb-3">
                    <button type="button" onclick="window.addClassRosterRow()" class="bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-bold py-2 px-3 rounded border border-slate-600">+ 학생 추가</button>
                    <button type="button" onclick="window.saveClassMeta()" class="bg-emerald-700 hover:bg-emerald-600 text-white text-[10px] font-bold py-2 px-4 rounded">명단 저장</button>
                </div>
                <div class="border-t border-slate-700 pt-3 mt-1">
                    <h4 class="text-white font-bold text-xs mb-2"><i class="fa-solid fa-plus-circle text-sky-400"></i> 새 학급 만들기 (내년·다른 반)</h4>
                    <div class="grid sm:grid-cols-2 gap-2 mb-2">
                        <input id="newClassDisplayName" type="text" placeholder="예: 2027학년도 6학년 1반" class="bg-slate-900 border border-slate-700 rounded px-2 py-1.5 text-xs text-white">
                        <input id="newClassSchoolYear" type="number" placeholder="학년도 (2027)" class="bg-slate-900 border border-slate-700 rounded px-2 py-1.5 text-xs text-white">
                        <input id="newClassGrade" type="number" min="1" max="6" placeholder="학년" class="bg-slate-900 border border-slate-700 rounded px-2 py-1.5 text-xs text-white">
                        <input id="newClassHomeroom" type="number" min="1" max="20" placeholder="반" class="bg-slate-900 border border-slate-700 rounded px-2 py-1.5 text-xs text-white">
                    </div>
                    <button type="button" onclick="window.createNewClass()" class="bg-sky-700 hover:bg-sky-600 text-white text-[10px] font-bold py-2 px-4 rounded">새 학급 생성 후 이동</button>
                    <p class="text-[9px] text-slate-500 mt-2">새 학급은 별도 데이터 공간(artifacts)을 사용합니다. 작년 반 데이터는 그대로 보존됩니다.</p>
                </div>`;
        };

        window.addClassRosterRow = function() {
            if (!window.playerState?.isGM) return;
            const meta = window.classMeta || buildDefaultClassMeta(appId);
            const roster = Array.isArray(meta.roster) ? [...meta.roster] : [];
            const nextNum = roster.reduce((max, r) => Math.max(max, Number(r.id) || 0), 0) + 1;
            roster.push({ id: String(nextNum), name: '새 학생', gender: 'M', label: '', active: true });
            window.classMeta = { ...meta, roster };
            window.renderClassAdminPanel();
        };

        function readRosterFromEditor() {
            const tbody = document.getElementById('classRosterEditorBody');
            if (!tbody) return window.classMeta?.roster || [];
            const rows = tbody.querySelectorAll('tr');
            const roster = [];
            rows.forEach((tr) => {
                const idEl = tr.querySelector('[data-roster-field="id"]');
                const nameEl = tr.querySelector('[data-roster-field="name"]');
                const genderEl = tr.querySelector('[data-roster-field="gender"]');
                const labelEl = tr.querySelector('[data-roster-field="label"]');
                const activeEl = tr.querySelector('[data-roster-field="active"]');
                const id = idEl ? String(idEl.value || '').trim() : '';
                const name = nameEl ? String(nameEl.value || '').trim() : '';
                if (!id || !name) return;
                roster.push({
                    id,
                    name,
                    gender: genderEl && genderEl.value === 'F' ? 'F' : 'M',
                    label: labelEl ? String(labelEl.value || '').trim() : '',
                    active: activeEl ? !!activeEl.checked : true,
                });
            });
            return roster;
        }

        window.saveClassMeta = async function() {
            if (!window.playerState?.isGM || !db) return;
            const roster = readRosterFromEditor();
            if (!roster.length) return window.customAlert('최소 1명의 학생이 필요합니다.');
            const displayName = document.getElementById('classMetaDisplayName')?.value?.trim() || window.classMeta?.displayName || '우리 반';
            const schoolYear = Number(document.getElementById('classMetaSchoolYear')?.value) || window.classMeta?.schoolYear || 2026;
            const grade = Number(document.getElementById('classMetaGrade')?.value) || window.classMeta?.grade || 6;
            const homeroom = Number(document.getElementById('classMetaHomeroom')?.value) || window.classMeta?.homeroom || 1;
            const inviteCode = window.classMeta?.inviteCode || await generateUniqueInviteCode().catch(() => generateInviteCode());
            const payload = {
                classId: appId,
                displayName,
                schoolYear,
                grade,
                homeroom,
                inviteCode,
                gmaEditStudentId: window.classMeta?.gmaEditStudentId || getGmaEditStudentId() || '1',
                isActive: true,
                roster,
                staff: window.classMeta?.staff || DEFAULT_CLASS_STAFF,
                updatedAt: serverTimestamp(),
            };
            await setDoc(doc(db, 'classes', appId), payload, { merge: true });
            try {
                await registerInviteCode(inviteCode, appId, { displayName });
            } catch (e) {
                if (String(e.message) === 'invite_code_taken') {
                    return window.customAlert('초대 코드 충돌이 감지되었습니다. 페이지를 새로고침한 뒤 다시 저장해 주세요.');
                }
                console.warn('registerInviteCode(save)', e);
            }
            window.classMeta = { ...window.classMeta, ...payload, roster, staff: payload.staff };
            syncNameGenderMaps();
            populateLoginSelect();
            updateClassDisplayLabels();
            window.renderClassAdminPanel();
            window.renderPlaza(window.allStudentsData || [], window.gmData, window.gmaData);
            await window.customAlert('✅ 학급 명단이 저장되었습니다.');
        };

        window.createNewClass = async function() {
            if (!window.playerState?.isGM || !db) return;
            const displayName = document.getElementById('newClassDisplayName')?.value?.trim();
            const schoolYear = Number(document.getElementById('newClassSchoolYear')?.value);
            const grade = Number(document.getElementById('newClassGrade')?.value);
            const homeroom = Number(document.getElementById('newClassHomeroom')?.value);
            if (!displayName || !schoolYear || !grade || !homeroom) {
                return window.customAlert('학급 이름, 학년도, 학년, 반을 모두 입력해 주세요.');
            }
            const ok = await window.customConfirm(`새 학급을 만듭니다.\n\n이름: ${displayName}\n${schoolYear}학년도 ${grade}학년 ${homeroom}반\n\n빈 명단으로 시작하고, 고유 학급 ID·초대 코드가 발급됩니다.`);
            if (!ok) return;
            try {
                window.showGlobalLoading('학급 생성 중…');
                const teacherName = getStaffMember('gm')?.name || '담임 선생님';
                const authOk = await ensureAnonAuthReady();
                if (!authOk) throw new Error('인증에 실패했습니다.');
                const { newClassId, inviteCode } = await createClassWorkspace({
                    displayName,
                    schoolYear,
                    grade,
                    homeroom,
                    teacherName,
                    studentCount: 25,
                    teacherPin: '',
                    copySettingsFromCurrent: true,
                });
                window.hideGlobalLoading();
                await window.customAlert(`✅ 새 학급이 생성되었습니다!\n\n초대 코드: ${inviteCode}\n학급 ID: ${newClassId}\n\n명단을 수정한 뒤 학생에게 초대 코드를 알려 주세요.`);
                window.switchClass(newClassId);
            } catch (e) {
                console.error('createNewClass', e);
                window.hideGlobalLoading();
                await window.customAlert('생성 실패: ' + (e && e.message ? e.message : String(e)));
            } finally {
                window.hideGlobalLoading();
            }
        };

        function renderTeacherClassHub() {
            const hub = document.getElementById('teacherClassHub');
            if (!hub) return;
            const show = !!(window.playerState && window.playerState.isGM && window.classMeta);
            hub.classList.toggle('hidden', !show);
            if (!show) return;
            const meta = window.classMeta;
            const nameEl = document.getElementById('teacherHubClassName');
            const idEl = document.getElementById('teacherHubClassId');
            const codeEl = document.getElementById('teacherHubInviteCode');
            if (nameEl) nameEl.textContent = meta.displayName || appId;
            if (idEl) idEl.textContent = appId;
            if (codeEl) codeEl.textContent = meta.inviteCode || '—';
            if (typeof window.renderTeacherOnboarding === 'function') window.renderTeacherOnboarding();
            // 설문 버튼 (학생용)
            const surveyBtn = document.getElementById('studentSurveyBtn');
            if (surveyBtn) {
                const url = String(window.globalSettings?.researchSurveyUrl || '').trim();
                surveyBtn.classList.toggle('hidden', !url || !!window.playerState.isAdmin);
            }
        }

        window.copyTeacherInviteCode = async function() {
            const code = window.classMeta?.inviteCode || '';
            if (!code) return window.customAlert('초대 코드가 없습니다. 명단을 한 번 저장해 주세요.');
            try {
                await navigator.clipboard.writeText(code);
                window.showToast('복사되었습니다!');
            } catch (_) {
                await window.customAlert(`초대 코드: ${code}`);
            }
        };

        window.copyTeacherClassLink = async function() {
            const link = getClassShareUrl(appId);
            try {
                await navigator.clipboard.writeText(link);
                window.showToast('복사되었습니다!');
            } catch (_) {
                await window.customAlert(link);
            }
        };

        window.toggleNavClassMenu = function(forceOpen) {
            const menu = document.getElementById('navClassMenu');
            if (!menu) return;
            const currentlyHidden = menu.classList.contains('hidden');
            // forceOpen=true면 무조건 열기, 아니면 토글
            const shouldOpen = forceOpen === true ? true : (forceOpen === false ? false : currentlyHidden);
            if (!shouldOpen) {
                menu.classList.add('hidden');
                return;
            }
            const recent = getRecentClasses();
            const rows = recent.length
                ? recent.map((r) => {
                    const cur = r.classId === appId ? ' · 현재' : '';
                    const safeId = String(r.classId).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
                    return `<button type="button" class="w-full text-left px-2 py-1.5 rounded-lg hover:bg-slate-800 text-slate-200" onclick="event.stopPropagation(); window.switchClass('${safeId}')">
                        <div class="font-bold truncate">${r.displayName || r.classId}${cur}</div>
                        <div class="text-slate-500 truncate">${r.inviteCode || r.classId}</div>
                    </button>`;
                }).join('')
                : '<div class="text-slate-500 px-2 py-2">최근 학급이 없습니다. 아래에서 코드로 이동하세요.</div>';
            menu.innerHTML = `
                <div class="text-[9px] text-slate-500 font-bold px-1 mb-1">학급 전환</div>
                ${rows}
                <div class="border-t border-slate-700 mt-1 pt-2 space-y-1.5">
                    <input id="navSwitchClassCode" type="text" placeholder="초대 코드 또는 학급 ID" class="w-full bg-slate-950 border border-slate-600 rounded-lg px-2 py-1.5 text-[10px] text-white font-bold" onclick="event.stopPropagation()">
                    <button type="button" class="w-full bg-emerald-700 hover:bg-emerald-600 text-white font-bold py-1.5 rounded-lg" onclick="event.stopPropagation(); void window.applyNavClassSwitch()">이 학급으로 이동</button>
                    <button type="button" class="w-full text-left px-2 py-1.5 rounded-lg hover:bg-slate-800 text-amber-200 font-bold" onclick="event.stopPropagation(); void window.leaveCurrentClass()">이 기기에서 학급 나가기</button>
                    <button type="button" class="w-full text-left px-2 py-1.5 rounded-lg hover:bg-slate-800 text-sky-300 font-bold" onclick="event.stopPropagation(); void window.logout()">다른 계정으로 다시 로그인</button>
                </div>`;
            menu.classList.remove('hidden');
            // 같은 클릭 이벤트로 바로 닫히지 않도록 한 틱 무시
            window._navClassMenuIgnoreUntil = Date.now() + 300;
        };

        window.applyNavClassSwitch = async function() {
            const raw = String(document.getElementById('navSwitchClassCode')?.value || '').trim();
            if (!raw) return window.customAlert('초대 코드 또는 학급 ID를 입력해 주세요.');
            const studentInput = document.getElementById('loginClassCode');
            if (studentInput) studentInput.value = raw;
            // 로그인 화면 없이도 전환
            try {
                window.showGlobalLoading('학급을 찾는 중…');
                const classId = await resolveClassIdFromInviteOrRaw(raw);
                window.hideGlobalLoading();
                window.switchClass(classId);
            } catch (e) {
                window.hideGlobalLoading();
                if (String(e.message) === 'invite_not_found') {
                    return window.customAlert('초대 코드를 다시 확인해 주세요. 대소문자를 구분합니다.');
                }
                if (String(e.message) === 'class_archived') {
                    return window.customAlert('이 학급은 보관(비활성) 상태라 입장할 수 없습니다.');
                }
                return window.customAlert('학급을 열 수 없습니다: ' + (e && e.message ? e.message : String(e)));
            }
        };

        /** 허브 버튼용: 드롭다운이 클릭과 동시에 닫히는 문제 없이 전환 패널 표시 */
        window.openClassSwitchPanel = function() {
            window.toggleNavClassMenu(true);
            // 모바일에서도 보이도록 메뉴를 화면 중앙 모달처럼 보정
            const menu = document.getElementById('navClassMenu');
            if (menu) {
                menu.classList.add('fixed', 'left-1/2', 'top-20', '-translate-x-1/2', 'z-[430]');
                menu.classList.remove('absolute', 'left-0', 'top-full', 'mt-1');
            }
        };

        document.addEventListener('click', (e) => {
            if (Date.now() < (window._navClassMenuIgnoreUntil || 0)) return;
            const wrap = document.getElementById('navClassSwitcherWrap');
            const menu = document.getElementById('navClassMenu');
            if (!menu || menu.classList.contains('hidden')) return;
            // 메뉴 자체 클릭은 유지
            if (menu.contains(e.target)) return;
            if (wrap && wrap.contains(e.target)) return;
            menu.classList.add('hidden');
            menu.classList.remove('fixed', 'left-1/2', 'top-20', '-translate-x-1/2', 'z-[430]');
            menu.classList.add('absolute', 'left-0', 'top-full', 'mt-1');
        });

        /** 유니코드 주사위 면(⚀~⚅) — 미스테리 박스 UI용 */
        const DICE_UNICODE_FACES = ['\u2680','\u2681','\u2682','\u2683','\u2684','\u2685'];

        /** 석서영(학번 13) 부동산 복구용 자리 인덱스(0부터). 8번 자리 = 인덱스 7. — 시드 학급·기본 4×4 전용 */
        const ESTATE_RESTORE_SEOK_SEAT_INDEX = 7;
        /** 황훈태(학번 12) 부동산 복구용 자리 인덱스(0부터). 2번 자리 = 인덱스 1. — 시드 학급·기본 4×4 전용 */
        const ESTATE_RESTORE_HHWANG_SEAT_INDEX = 1;

        /** 기본 4×4에서 사용 안 함으로 시작하는 자리(표시 번호 1·13·16 → 인덱스 0·12·15) */
        const ESTATE_DEFAULT_HIDDEN_SEAT_IDS = [0, 12, 15];
        /** @deprecated 레거시 별칭 — 새 코드는 ESTATE_DEFAULT_HIDDEN_SEAT_IDS / seat.hidden 사용 */
        const ESTATE_HIDDEN_SEAT_IDS = ESTATE_DEFAULT_HIDDEN_SEAT_IDS;

        const ESTATE_LAYOUT_MIN = 1;
        const ESTATE_LAYOUT_MAX = 12;
        const ESTATE_DEFAULT_PRICE = 500;

        function clampEstateDim(n, fallback) {
            const v = Math.floor(Number(n));
            if (!Number.isFinite(v)) return fallback;
            return Math.max(ESTATE_LAYOUT_MIN, Math.min(ESTATE_LAYOUT_MAX, v));
        }

        /** 부동산 격자 크기 (rows × cols). 없으면 좌석 수로 추론 */
        function getEstateLayout(state = window.estateState) {
            const layout = state && state.layout;
            let rows = clampEstateDim(layout && layout.rows, 0);
            let cols = clampEstateDim(layout && layout.cols, 0);
            if (rows >= 1 && cols >= 1) return { rows, cols };
            const n = Array.isArray(state && state.seats) ? state.seats.length : 16;
            if (n === 16) return { rows: 4, cols: 4 };
            cols = Math.min(8, Math.max(2, Math.ceil(Math.sqrt(n))));
            rows = Math.max(1, Math.ceil(n / cols));
            return { rows, cols };
        }

        /** 사용하지 않는(비활성) 자리인지 */
        function isEstateSeatDisabled(seat) {
            if (!seat) return true;
            if (seat.hidden === true) return true;
            return false;
        }

        /** 부동산 자리 배열 생성 */
        function buildEstateSeatsFromLayout(rows, cols, opts = {}) {
            const r = clampEstateDim(rows, 4);
            const c = clampEstateDim(cols, 4);
            const total = r * c;
            const price = Math.max(0, Math.floor(Number(opts.defaultPrice) || ESTATE_DEFAULT_PRICE));
            const hiddenSet = new Set(
                Array.isArray(opts.hiddenIds)
                    ? opts.hiddenIds.map((x) => Number(x)).filter((x) => Number.isFinite(x) && x >= 0 && x < total)
                    : []
            );
            const prevById = new Map();
            if (opts.keepExisting && Array.isArray(opts.previousSeats)) {
                opts.previousSeats.forEach((s) => {
                    if (s && Number.isFinite(Number(s.id))) prevById.set(Number(s.id), s);
                });
            }
            const seats = [];
            for (let i = 0; i < total; i++) {
                const hide = hiddenSet.has(i);
                const prev = prevById.get(i);
                if (prev && opts.keepExisting) {
                    seats.push({
                        id: i,
                        owner: hide ? null : (prev.owner || null),
                        assignee: hide ? null : (prev.assignee || null),
                        price: Math.max(0, Math.floor(Number(prev.price) || price)),
                        locked: hide ? true : !!prev.locked,
                        hidden: hide,
                        noAutoRestore: !!prev.noAutoRestore,
                    });
                } else {
                    seats.push({
                        id: i,
                        owner: null,
                        assignee: null,
                        price,
                        locked: hide,
                        hidden: hide,
                    });
                }
            }
            return { seats, layout: { rows: r, cols: c } };
        }

        /** 부동산 초기 16칸 (1·13·16번 자리는 사용 안 함) — 하위 호환 */
        function buildInitialEstateSeats() {
            return buildEstateSeatsFromLayout(4, 4, {
                defaultPrice: ESTATE_DEFAULT_PRICE,
                hiddenIds: ESTATE_DEFAULT_HIDDEN_SEAT_IDS,
            }).seats;
        }

        /** Firestore/메모리 estateState 정규화 (layout·hidden 마이그레이션) */
        function normalizeEstateState(raw) {
            const state = raw && typeof raw === 'object' ? { ...raw } : {};
            if (!Array.isArray(state.seats)) state.seats = buildInitialEstateSeats();
            if (!Array.isArray(state.purchaseHistory)) state.purchaseHistory = [];
            const layout = getEstateLayout(state);
            state.layout = { rows: layout.rows, cols: layout.cols };
            const expected = layout.rows * layout.cols;
            // 좌석 수가 layout과 다르면 layout을 좌석 수에 맞춤(구데이터)
            if (state.seats.length !== expected) {
                const n = state.seats.length;
                if (n === 16) state.layout = { rows: 4, cols: 4 };
                else {
                    const cols = Math.min(8, Math.max(2, Math.ceil(Math.sqrt(n))));
                    state.layout = { rows: Math.max(1, Math.ceil(n / cols)), cols };
                }
            }
            const isLegacyDefault = state.seats.length === 16
                && state.layout.rows === 4
                && state.layout.cols === 4;
            state.seats = state.seats.map((s, i) => {
                const seat = s && typeof s === 'object' ? { ...s } : {};
                seat.id = Number.isFinite(Number(seat.id)) ? Number(seat.id) : i;
                if (seat.assignee === undefined) seat.assignee = null;
                if (seat.owner === undefined) seat.owner = null;
                if (seat.price == null) seat.price = ESTATE_DEFAULT_PRICE;
                if (seat.hidden === undefined) {
                    seat.hidden = isLegacyDefault && ESTATE_DEFAULT_HIDDEN_SEAT_IDS.includes(seat.id);
                }
                if (seat.hidden) {
                    seat.locked = true;
                    seat.assignee = null;
                }
                return seat;
            });
            return state;
        }

        window.playerState = { 
            xp: 0, xpChangeLog: [], bong: 0.0, quests: {}, unlockedQuests: {}, jobs: [], 
            ownedSkins: {}, equippedSkins: {}, baseFaceId: '', hasShield: false, shieldHP: 0, 
            condition: null, dragonBalls: [], dragonBallWeekendKey: '', inventory: [], equippedWeapon: null, lunchBid: {date: '', amount: 0}, lastLunchDeductDate: '', questHistory: [], usedRaidPasswords: [],
            bankRegularSavings: 0, bankTermDeposits: [], bankDailyBonusLastDate: '', dailyAllClearBonusDate: '',
            shopDailyPurchase: { date: '', item_random: 0, item_mystery_dice: 0 },
            conveniencePurchases: [],
            lottoTickets: [],
            isGuest: false, isGM: false, isGMA: false, isAdmin: false 
        };
        
        window.allStudentsData = []; 
        window.gmData = null; 
        window.gmaData = null; 
                window.globalSettings = { raidPassword: '', raidPasswordNeedsSetup: true, shieldStock: 10, lastAutoXpTime: '', morningActivityNotice: '', customShopItems: [], convenienceItems: [], deletedQuestIds: [], customQuests: [], deletedJobIds: [], customJobs: [], jobOverrides: {}, constitutionItems: [], weekendRaidRewardXp: 40, weekendRaidRewardBong: 20, birthdayCelebrations: [], lotto: null, worldCupBet: null, musicTimeQueue: [], learningThermometer: null, classTimetable: null, classElection: null, worldSettings: { ...DEFAULT_WORLD_SETTINGS } };
        applyWorldBranding();
        /** 공동구매 풀 스냅샷: shopId → { contributions: { 학번: B } } */
        window.shopGroupBuyPools = {};
        /** 편의점 주문 목록 스냅샷: 최신순 배열 */
        window.convenienceOrders = [];
        /** 삼봉 편의점 장바구니: itemId → 수량 */
        window.convenienceCart = {};
        /** true 이후에는 오래된 Firestore 로컬 캐시 스냅샷으로 모금 UI를 덮지 않음 */
        window._shopGroupBuyPoolGotServer = false;
        /** 초기화 직전 저장된 학생별 백업 (studentId → { savedAt, data }) */
        window.studentBackupMap = {};
        
        let db, auth, currentStudentDocRef = null, unsubscribeGlobal = null, unsubscribeSettings = null, unsubscribeRaid = null, unsubscribeDragonBall = null;
        let unsubscribeGoldenBell = null;
        let unsubscribeMasterQuiz = null;
        let unsubscribeShopGroupBuy = null;
        let unsubscribeConvenienceOrders = null;
        let unsubscribeStudentBackups = null;
        /** Firestore artifacts 세그먼트 — URL ?class=, localStorage, window.__app_id 순으로 결정 */
        const appId = resolveClassId();

        /**
         * Firestore 규칙이 request.auth != null 일 때, 로그인 직후 토큰이 아직 안 붙은 채로 쓰기하면 permission-denied가 날 수 있음.
         * authStateReady + 익명 로그인 후 getIdToken()으로 토큰을 확실히 받은 뒤에만 true.
         */
        async function ensureAnonAuthReady() {
            if (!auth) return false;
            const tryOnce = async () => {
                await auth.authStateReady();
                if (!auth.currentUser) await signInAnonymously(auth);
                const u = auth.currentUser;
                if (!u) return false;
                await u.getIdToken();
                return true;
            };
            try {
                return await withRetry(tryOnce, {
                    retries: 2,
                    baseDelayMs: 450,
                    onRetry: (n, err) => console.warn(`ensureAnonAuthReady 재시도 ${n}`, err),
                });
            } catch (e) {
                console.warn('ensureAnonAuthReady 최종 실패', e);
                return false;
            }
        }

        /** 전역 로딩 스피너 / 에러 표시 */
        window.showGlobalLoading = function(msg) {
            const overlay = document.getElementById('globalLoadingOverlay');
            const text = document.getElementById('globalLoadingText');
            const err = document.getElementById('globalLoadingError');
            if (text) text.textContent = msg || '잠시만 기다려 주세요…';
            if (err) {
                err.textContent = '';
                err.classList.add('hidden');
            }
            if (overlay) overlay.classList.remove('hidden');
        };
        window.hideGlobalLoading = function() {
            const overlay = document.getElementById('globalLoadingOverlay');
            const retryBtn = document.getElementById('globalLoadingRetryBtn');
            if (retryBtn) retryBtn.classList.add('hidden');
            if (overlay) overlay.classList.add('hidden');
        };
        window.showGlobalLoadingError = function(msg) {
            const overlay = document.getElementById('globalLoadingOverlay');
            const err = document.getElementById('globalLoadingError');
            const retryBtn = document.getElementById('globalLoadingRetryBtn');
            if (err) {
                err.textContent = msg || '연결이 불안정합니다. 자동으로 다시 시도합니다.';
                err.classList.remove('hidden');
            }
            if (retryBtn) retryBtn.classList.remove('hidden');
            if (overlay) overlay.classList.remove('hidden');
        };

        /** 짧은 토스트 (복사 성공 등) */
        window.showToast = function(message, ms = 2200) {
            let el = document.getElementById('appToast');
            if (!el) {
                el = document.createElement('div');
                el.id = 'appToast';
                el.className = 'fixed bottom-20 left-1/2 -translate-x-1/2 z-[450] max-w-[90vw] px-4 py-2.5 rounded-xl bg-emerald-700 text-white text-sm font-bold shadow-xl opacity-0 transition-opacity duration-200 pointer-events-none';
                document.body.appendChild(el);
            }
            el.textContent = message || '';
            el.classList.remove('opacity-0');
            el.classList.add('opacity-100');
            clearTimeout(window._toastTimer);
            window._toastTimer = setTimeout(() => {
                el.classList.add('opacity-0');
                el.classList.remove('opacity-100');
            }, ms);
        };

        function updateOfflineBanner() {
            const banner = document.getElementById('offlineBanner');
            if (!banner) return;
            const offline = typeof navigator !== 'undefined' && navigator.onLine === false;
            banner.classList.toggle('hidden', !offline);
        }
        window.addEventListener('online', () => {
            updateOfflineBanner();
            void window.retryPendingNetworkActions();
        });
        window.addEventListener('offline', updateOfflineBanner);
        updateOfflineBanner();

        window._networkRetryQueue = window._networkRetryQueue || [];
        window.retryPendingNetworkActions = async function() {
            if (typeof navigator !== 'undefined' && navigator.onLine === false) {
                return window.customAlert('아직 오프라인입니다. 연결 후 다시 시도해 주세요.');
            }
            const queue = window._networkRetryQueue.splice(0, window._networkRetryQueue.length);
            if (!queue.length) {
                try {
                    await ensureAnonAuthReady();
                    if (typeof refreshStudentsCacheFromServer === 'function') await refreshStudentsCacheFromServer();
                } catch (e) {
                    console.warn('retryPendingNetworkActions', e);
                }
                return;
            }
            window.showGlobalLoading('재시도 중…');
            try {
                for (const fn of queue) {
                    try { await fn(); } catch (e) { console.warn('queued retry failed', e); }
                }
            } finally {
                window.hideGlobalLoading();
            }
        };

        /** Firestore 등 네트워크 작업을 재시도하며 실행 */
        async function runWithNetworkRetry(fn, label) {
            let keepErrorOverlay = false;
            try {
                return await withRetry(fn, {
                    retries: 2,
                    baseDelayMs: 600,
                    onRetry: (n, err) => {
                        console.warn(`${label || 'network'} 재시도 ${n}`, err);
                        window.showGlobalLoading(`${label || '작업'} 재시도 중… (${n})`);
                    },
                });
            } catch (e) {
                if (isLikelyNetworkError(e)) {
                    window._networkRetryQueue.push(fn);
                    keepErrorOverlay = true;
                    window.showGlobalLoadingError((label || '작업') + ' 실패: 네트워크를 확인한 뒤 「지금 재시도」를 눌러 주세요.');
                }
                throw e;
            } finally {
                if (!keepErrorOverlay) window.hideGlobalLoading();
            }
        }
        window.runWithNetworkRetry = runWithNetworkRetry;

        /** 서버 스냅샷으로 XP가 올라온 경우 안내(수업 자동 XP 등) — 직전 저장과 구분 */
        let _prevXpFromSnapshot = null;

        /** 마스터가 추가한 사용자 정의 상점 아이템 목록 */
        function getCustomShopItems() {
            const items = window.globalSettings && Array.isArray(window.globalSettings.customShopItems)
                ? window.globalSettings.customShopItems
                : [];
            return items.filter((item) => item && item.id && item.name);
        }

        /** 편의점 구역에 표시할 물품 목록 (마스터가 globalSettings.convenienceItems에 저장) */
        function getConvenienceItems() {
            const items = window.globalSettings && Array.isArray(window.globalSettings.convenienceItems)
                ? window.globalSettings.convenienceItems
                : [];
            return items
                .filter((item) => item && item.id && item.name && item.hidden !== true)
                .map((item) => ({
                    id: String(item.id),
                    name: String(item.name || '').trim(),
                    desc: String(item.desc || '').trim(),
                    price: normalizeBongValue(Math.max(0, Number(item.price) || 0)),
                    createdAt: Number(item.createdAt) || 0,
                }))
                .filter((item) => item.name);
        }

        function getConvenienceItemById(itemId) {
            return getConvenienceItems().find((item) => String(item.id) === String(itemId));
        }

        function getGlobalSettingsDocRef() {
            return doc(db, 'artifacts', appId, 'public', 'data', 'settings', 'global');
        }

        /** 마스터가 Firestore에 저장하기 전까지 적용되는 기본 배달비 */
        const DEFAULT_CONVENIENCE_DELIVERY_FEE = 1;

        /** Firestore settings.global에 저장된 배달비를 0 이상 정수(버림)로 정규화 */
        function normalizeConvenienceDeliveryFee(raw) {
            const fee = raw != null ? Number(raw) : 0;
            return normalizeBongValue(Math.max(0, Number.isFinite(fee) ? fee : 0));
        }

        function hasConfiguredConvenienceDeliveryFee(source) {
            return !!(source && Object.prototype.hasOwnProperty.call(source, 'convenienceDeliveryFee'));
        }

        /** Firestore/로컬 settings 객체에서 실제 적용할 배달비를 계산 (미설정 시 기본 1B) */
        function readConvenienceDeliveryFeeFromSettingsData(settingsData) {
            if (!hasConfiguredConvenienceDeliveryFee(settingsData)) {
                return DEFAULT_CONVENIENCE_DELIVERY_FEE;
            }
            return normalizeConvenienceDeliveryFee(settingsData.convenienceDeliveryFee);
        }

        /** 편의점 배달 선택 시 추가되는 배달비 */
        function getConvenienceDeliveryFee() {
            return readConvenienceDeliveryFeeFromSettingsData(window.globalSettings || {});
        }

        /** globalSettings에 서버 배달비 상태를 반영하고 실제 적용값을 반환 */
        function applyConvenienceDeliveryFeeFromSettingsData(settingsData) {
            if (!window.globalSettings) window.globalSettings = {};
            if (hasConfiguredConvenienceDeliveryFee(settingsData)) {
                window.globalSettings.convenienceDeliveryFee = normalizeConvenienceDeliveryFee(settingsData.convenienceDeliveryFee);
            } else {
                delete window.globalSettings.convenienceDeliveryFee;
            }
            return readConvenienceDeliveryFeeFromSettingsData(settingsData || {});
        }

        function formatConvenienceDeliveryFeeLabel(fee) {
            const normalized = normalizeConvenienceDeliveryFee(fee);
            return normalized > 0 ? `+${formatBongAmount(normalized)}` : '무료';
        }

        /** 주문·결제 직전 Firestore 서버 기준 최신 배달비를 읽어 반영 */
        async function refreshConvenienceDeliveryFeeFromServer() {
            if (!db) return getConvenienceDeliveryFee();
            try {
                const snap = await getDocFromServer(getGlobalSettingsDocRef());
                if (snap.exists()) {
                    return applyConvenienceDeliveryFeeFromSettingsData(snap.data() || {});
                }
            } catch (e) {
                try {
                    const snap = await getDoc(getGlobalSettingsDocRef());
                    if (snap.exists()) {
                        return applyConvenienceDeliveryFeeFromSettingsData(snap.data() || {});
                    }
                } catch (e2) {
                    console.warn('refreshConvenienceDeliveryFeeFromServer', e2);
                }
            }
            return getConvenienceDeliveryFee();
        }

        /** 학생 jobs 배열 항목에서 직업 이름 추출 (문자열/객체 모두 지원) */
        function getStudentJobName(job) {
            if (!job) return '';
            if (typeof job === 'string') return job.trim();
            if (typeof job === 'object' && job.name != null) return String(job.name).trim();
            return String(job).trim();
        }

        /** 편의점 매니저 뱃지(직업)를 표시 중인지 확인 */
        function hasConvenienceManagerJob(jobs) {
            const list = Array.isArray(jobs) ? jobs : [];
            return list.some((job) => getStudentJobName(job) === '편의점 매니저');
        }

        /** 마스터 또는 직업에 '편의점 매니저'가 있는 학생은 주문을 확인·처리할 수 있음 */
        function isConvenienceManager() {
            if (!window.playerState || window.playerState.isGuest) return false;
            if (window.playerState.isAdmin) return true;
            return hasConvenienceManagerJob(window.playerState.jobs);
        }

        /** 배달비 수령 대상: 편의점 매니저 뱃지를 단 1명만 (학번 오름차순 우선) */
        function getConvenienceManagerStudents() {
            const rows = Array.isArray(window.allStudentsData) ? window.allStudentsData : [];
            return rows
                .filter((stu) => {
                    const sid = String(stu && stu.id || '');
                    if (!sid || sid === 'gm' || sid === 'gm_a') return false;
                    return hasConvenienceManagerJob(stu.jobs);
                })
                .map((stu) => ({
                    id: String(stu.id),
                    name: STUDENT_NAMES[String(stu.id)] || stu.name || String(stu.id),
                }))
                .sort((a, b) => Number(a.id) - Number(b.id));
        }

        /** 배달비는 뱃지를 단 1명에게 전액 지급 */
        function getConvenienceDeliveryPayee() {
            const managers = getConvenienceManagerStudents();
            return managers.length ? managers[0] : null;
        }

        function getDeletedQuestIds() {
            return new Set(
                window.globalSettings && Array.isArray(window.globalSettings.deletedQuestIds)
                    ? window.globalSettings.deletedQuestIds.map((id) => String(id))
                    : []
            );
        }

        function getCustomQuests() {
            const qs = window.globalSettings && Array.isArray(window.globalSettings.customQuests)
                ? window.globalSettings.customQuests
                : [];
            return qs
                .filter((q) => q && q.id && q.name)
                .map((q) => ({
                    id: String(q.id),
                    type: ['daily', 'weekly', 'locked'].includes(q.type) ? q.type : 'daily',
                    name: String(q.name),
                    desc: String(q.desc || ''),
                    xp: Math.min(CUSTOM_QUEST_XP_MAX, Math.max(0, Math.floor(Number(q.xp) || 0))),
                    bong: normalizeQuestBongReward(Number(q.bong) || 0),
                    icon: q.icon || 'fa-star',
                    color: q.color || 'text-emerald-300',
                    custom: true,
                }));
        }

        function getQuestCatalog() {
            const deleted = getDeletedQuestIds();
            return [...QUEST_DATA, ...getCustomQuests()]
                .filter((q) => !deleted.has(String(q.id)))
                .map((q) => ({ ...q, bong: normalizeQuestBongReward(q.bong) }));
        }

        function getDeletedJobIds() {
            return new Set(
                window.globalSettings && Array.isArray(window.globalSettings.deletedJobIds)
                    ? window.globalSettings.deletedJobIds.map((id) => String(id))
                    : []
            );
        }

        function sanitizeJobItem(job, fallbackId) {
            const id = String(job && job.id ? job.id : fallbackId || `job_${Date.now().toString(36)}`);
            const name = String(job && job.name ? job.name : '').trim();
            return {
                id,
                name,
                sub: String(job && job.sub ? job.sub : '').trim(),
                icon: String(job && job.icon ? job.icon : 'fa-star'),
                color: String(job && job.color ? job.color : 'text-blue-400'),
                pay: Math.max(0, Math.floor(Number(job && job.pay) || 0)),
                desc: String(job && job.desc ? job.desc : '').trim(),
                custom: !!(job && job.custom),
            };
        }

        function getCustomJobs() {
            const jobs = window.globalSettings && Array.isArray(window.globalSettings.customJobs)
                ? window.globalSettings.customJobs
                : [];
            return jobs.map((j) => sanitizeJobItem({ ...j, custom: true })).filter((j) => j.id && j.name);
        }

        function getJobOverrides() {
            return window.globalSettings && window.globalSettings.jobOverrides && typeof window.globalSettings.jobOverrides === 'object'
                ? window.globalSettings.jobOverrides
                : {};
        }

        function getJobCatalog() {
            const deleted = getDeletedJobIds();
            const overrides = getJobOverrides();
            const baseJobs = JOB_DATA.map((job) => sanitizeJobItem({ ...job, ...(overrides[job.id] || {}) }, job.id));
            return [...baseJobs, ...getCustomJobs()].filter((job) => !deleted.has(String(job.id)));
        }

        /** 기본 상점 아이템 + 마스터 추가 아이템 */
        function getAllShopItems() {
            return [...SHOP_DATA, ...getCustomShopItems()];
        }

        function getShopItemById(shopId) {
            return getAllShopItems().find((x) => String(x.id) === String(shopId));
        }

        function isCustomShopItem(item) {
            return !!(item && item.custom === true);
        }

        /** 학급 상점(s1 등) ID */
        function isClassShopId(id) {
            const item = getShopItemById(id);
            return !!(item && !item.isConsumable);
        }

        /**
         * 공동구매 현황 정렬: 단체 구매 필요가 높은 학급 활동(자유시간·체육 등)을 앞에,
         * 같은 그룹 안에서는 목표 금액이 큰 순.
         */
        function sortShopsForGroupBuyOverview(shops) {
            return [...(shops || [])].sort((a, b) => {
                const aClass = isClassShopId(a.id) ? 0 : 1;
                const bClass = isClassShopId(b.id) ? 0 : 1;
                if (aClass !== bClass) return aClass - bClass;
                const priceDiff = getEffectiveShopPrice(b.id) - getEffectiveShopPrice(a.id);
                if (priceDiff !== 0) return priceDiff;
                return String(a.name || '').localeCompare(String(b.name || ''), 'ko');
            });
        }

        // ==========================================
        // ★ 뮤직 타임 신청곡 큐 (학급 공용) ★
        // ==========================================
        const MUSIC_TIME_SHOP_ID = 's1';
        const MUSIC_TIME_SONG_MAX_LEN = 80;
        const MUSIC_TIME_QUEUE_MAX = 50;

        function sanitizeMusicTimeQueue(raw) {
            if (!Array.isArray(raw)) return [];
            return raw
                .filter((row) => row && typeof row === 'object' && String(row.song || '').trim())
                .map((row, idx) => ({
                    id: String(row.id || `mt_legacy_${idx}_${Number(row.at) || 0}`),
                    studentId: String(row.studentId || ''),
                    studentName: String(row.studentName || row.studentId || '?'),
                    song: String(row.song || '').trim().slice(0, MUSIC_TIME_SONG_MAX_LEN),
                    at: Number(row.at) || Date.now(),
                }))
                .slice(-MUSIC_TIME_QUEUE_MAX);
        }

        function getMusicTimeQueue() {
            return sanitizeMusicTimeQueue(window.globalSettings && window.globalSettings.musicTimeQueue);
        }

        function formatMusicTimeAt(ms) {
            if (!ms) return '';
            const d = new Date(Number(ms));
            if (isNaN(d.getTime())) return '';
            return `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
        }

        async function appendMusicTimeRequest({ studentId, studentName, song }) {
            if (!db) throw new Error('no_db');
            const authOk = await ensureAnonAuthReady();
            if (!authOk) throw new Error('auth');
            const songText = String(song || '').trim().slice(0, MUSIC_TIME_SONG_MAX_LEN);
            if (!songText) throw new Error('empty_song');
            const entry = {
                id: `mt_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
                studentId: String(studentId || ''),
                studentName: String(studentName || studentId || '?'),
                song: songText,
                at: Date.now(),
            };
            await runTransaction(db, async (transaction) => {
                const ref = getGlobalSettingsDocRef();
                const snap = await transaction.get(ref);
                const data = snap.exists() ? snap.data() || {} : {};
                const queue = sanitizeMusicTimeQueue(data.musicTimeQueue);
                queue.push(entry);
                transaction.set(ref, { musicTimeQueue: queue.slice(-MUSIC_TIME_QUEUE_MAX) }, { merge: true });
            });
            if (!window.globalSettings) window.globalSettings = {};
            const localQueue = sanitizeMusicTimeQueue(window.globalSettings.musicTimeQueue);
            localQueue.push(entry);
            window.globalSettings.musicTimeQueue = localQueue.slice(-MUSIC_TIME_QUEUE_MAX);
            // 신청 직후 재생 URL을 미리 찾아 두면 재생 버튼이 빨라짐
            void searchYoutubeVideoIdFast(songText);
            return entry;
        }

        function renderMusicTimeQueueBar() {
            const el = document.getElementById('musicTimeQueueBar');
            if (!el) return;
            const queue = getMusicTimeQueue();
            const count = queue.length;
            el.innerHTML = `
                <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
                    <div class="text-[9px] text-slate-500">
                        <i class="fa-solid fa-music text-pink-400 mr-1"></i>
                        뮤직 타임 신청곡은 구매 시 입력되며, 아래에서 대기 목록을 볼 수 있어요.
                    </div>
                    <button type="button" onclick="window.openMusicTimeQueuePanel()"
                        class="shrink-0 bg-pink-900/70 hover:bg-pink-800 text-pink-100 font-bold py-2 px-3 rounded-xl text-[10px] border border-pink-500/50">
                        <i class="fa-solid fa-list-music"></i> 신청곡 리스트 보기
                        ${count > 0 ? `<span class="ml-1 bg-pink-500 text-white px-1.5 py-0.5 rounded-full text-[9px]">${count}</span>` : ''}
                    </button>
                </div>`;
        }

        function ensureMusicTimeQueueModal() {
            let modal = document.getElementById('musicTimeQueueModal');
            if (modal) return modal;
            modal = document.createElement('div');
            modal.id = 'musicTimeQueueModal';
            modal.className = 'hidden fixed inset-0 z-[270] bg-black/80 backdrop-blur-sm flex items-center justify-center px-3 py-6';
            modal.innerHTML = `
                <div class="w-full max-w-md bg-slate-900 border border-pink-500/50 rounded-2xl shadow-2xl p-4 max-h-[85vh] flex flex-col">
                    <div class="flex items-center justify-between gap-3 mb-3 border-b border-slate-700 pb-3 shrink-0">
                        <h3 class="text-lg font-display text-pink-100"><i class="fa-solid fa-music text-pink-300"></i> 뮤직 타임 신청곡</h3>
                        <button type="button" onclick="window.closeMusicTimeQueuePanel()" class="text-slate-400 hover:text-white text-xs font-bold">닫기</button>
                    </div>
                    <div class="shrink-0 mb-3">
                        <a href="https://music.youtube.com/" target="_blank" rel="noopener noreferrer"
                            class="flex items-center justify-center gap-2 w-full bg-red-900/60 hover:bg-red-800 text-red-100 font-bold py-2.5 px-3 rounded-xl text-[10px] border border-red-500/50 transition">
                            <i class="fa-brands fa-youtube text-red-300"></i> 유튜브 뮤직 바로가기 ↗
                        </a>
                    </div>
                    <div id="musicTimeQueueModalBody" class="overflow-y-auto scrollbar-hide pr-1 flex-1"></div>
                </div>`;
            document.body.appendChild(modal);
            return modal;
        }

        function getYoutubeDataApiKey() {
            // Firebase 웹 API 키와 동일(이미 클라이언트에 노출됨). YouTube Data API 검색용.
            return 'AIzaSyAsih-sfnIZ_gX_1l7SAVZHCAhk3KzmiP8';
        }

        const MUSIC_TIME_PLAY_CACHE_KEY = 'sambong_ytm_play_cache_v1';
        const MUSIC_TIME_PLAY_CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000;
        const _musicTimePlayCacheMem = new Map();
        const _musicTimeResolveInflight = new Map();

        function normalizeMusicTimeSongKey(songTitle) {
            return String(songTitle || '').trim().replace(/\s+/g, ' ').toLowerCase();
        }

        function loadMusicTimePlayCache() {
            try {
                const raw = localStorage.getItem(MUSIC_TIME_PLAY_CACHE_KEY);
                const obj = raw ? JSON.parse(raw) : {};
                return obj && typeof obj === 'object' ? obj : {};
            } catch (e) {
                return {};
            }
        }

        function saveMusicTimePlayCache(map) {
            try {
                localStorage.setItem(MUSIC_TIME_PLAY_CACHE_KEY, JSON.stringify(map));
            } catch (e) { /* ignore quota */ }
        }

        function getCachedMusicTimeVideoId(songTitle) {
            const key = normalizeMusicTimeSongKey(songTitle);
            if (!key) return '';
            if (_musicTimePlayCacheMem.has(key)) return _musicTimePlayCacheMem.get(key) || '';
            const store = loadMusicTimePlayCache();
            const row = store[key];
            if (!row || !row.videoId) return '';
            if (Date.now() - Number(row.at || 0) > MUSIC_TIME_PLAY_CACHE_TTL_MS) {
                delete store[key];
                saveMusicTimePlayCache(store);
                return '';
            }
            _musicTimePlayCacheMem.set(key, String(row.videoId));
            return String(row.videoId);
        }

        function setCachedMusicTimeVideoId(songTitle, videoId) {
            const key = normalizeMusicTimeSongKey(songTitle);
            const id = String(videoId || '').trim();
            if (!key || !id) return;
            _musicTimePlayCacheMem.set(key, id);
            const store = loadMusicTimePlayCache();
            store[key] = { videoId: id, at: Date.now() };
            // 캐시 과다 방지
            const keys = Object.keys(store);
            if (keys.length > 80) {
                keys
                    .map((k) => ({ k, at: Number(store[k] && store[k].at) || 0 }))
                    .sort((a, b) => a.at - b.at)
                    .slice(0, keys.length - 80)
                    .forEach((row) => { delete store[row.k]; });
            }
            saveMusicTimePlayCache(store);
        }

        function buildYoutubeMusicWatchUrl(videoId) {
            const id = encodeURIComponent(String(videoId || ''));
            return `https://music.youtube.com/watch?v=${id}`;
        }

        function buildYoutubeMusicSearchUrl(songTitle) {
            return `https://music.youtube.com/search?q=${encodeURIComponent(String(songTitle || '').trim())}`;
        }

        /**
         * 유튜브 뮤직은 COOP로 window 핸들이 끊김.
         * → 항상 우리 사이트(ytm-bridge.html)를 같은 창 이름으로 연 뒤, 브리지가 music으로 이동.
         *    다음 곡도 브리지(동일 출처)로 기존 창을 다시 잡아 재사용한다.
         */
        const MUSIC_TIME_YTM_WINDOW_NAME = 'sambongYtmPlayer';

        function getYtmBridgeBaseUrl() {
            try {
                const base = (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.BASE_URL)
                    ? String(import.meta.env.BASE_URL)
                    : '/2026sambong6/';
                return base.endsWith('/') ? base : `${base}/`;
            } catch (e) {
                return '/2026sambong6/';
            }
        }

        function buildYtmBridgeUrl(musicUrl, { wait = false } = {}) {
            const base = getYtmBridgeBaseUrl();
            if (wait) return `${base}ytm-bridge.html?wait=1`;
            const u = encodeURIComponent(String(musicUrl || 'https://music.youtube.com/'));
            return `${base}ytm-bridge.html?u=${u}`;
        }

        function openOrReuseYtmWindow(musicUrl) {
            const bridgeUrl = buildYtmBridgeUrl(musicUrl);
            // 고정 이름 + 우리 도메인 URL → 이미 연 창이 있어도 그 창을 브리지로 덮어씀
            let win = null;
            try {
                win = window.open(bridgeUrl, MUSIC_TIME_YTM_WINDOW_NAME);
            } catch (e) {
                win = null;
            }
            if (win) {
                window._sambongYtmWin = win;
                try { win.focus(); } catch (e) { /* ignore */ }
            }
            return win;
        }

        /** 클릭 직후: 같은 이름 창을 우리 브리지(wait)로 확보 — 이후 location 교체 가능 */
        function claimYtmBridgeWindow() {
            const waitUrl = buildYtmBridgeUrl('', { wait: true });
            let win = null;
            try {
                win = window.open(waitUrl, MUSIC_TIME_YTM_WINDOW_NAME);
            } catch (e) {
                win = null;
            }
            if (win) {
                window._sambongYtmWin = win;
                try { win.focus(); } catch (e) { /* ignore */ }
            }
            return win;
        }

        /** wait 브리지(동일 출처) → 최종 music URL 브리지로 교체 */
        function navigateYtmBridgeWindow(win, musicUrl) {
            const bridgeUrl = buildYtmBridgeUrl(musicUrl);
            if (win) {
                try {
                    if (!win.closed) {
                        win.location.replace(bridgeUrl);
                        try { win.focus(); } catch (e) { /* ignore */ }
                        window._sambongYtmWin = win;
                        return win;
                    }
                } catch (e) {
                    // 접근 불가면 이름 창으로 다시 브리지 open
                }
            }
            return openOrReuseYtmWindow(musicUrl);
        }

        function extractVideoIdFromPipedItem(item) {
            if (!item) return '';
            let videoId = item.videoId || item.id || '';
            if (!videoId && item.url) {
                const m = String(item.url).match(/(?:v=|\/watch\/|youtu\.be\/)([A-Za-z0-9_-]{6,})/);
                if (m) videoId = m[1];
                else if (String(item.url).startsWith('/watch?v=')) videoId = String(item.url).slice(9);
            }
            return String(videoId || '').trim();
        }

        async function fetchWithTimeout(url, ms = 1800) {
            const ctrl = new AbortController();
            const timer = setTimeout(() => ctrl.abort(), ms);
            try {
                return await fetch(url, { signal: ctrl.signal });
            } finally {
                clearTimeout(timer);
            }
        }

        async function searchYoutubeVideoIdFast(songTitle) {
            const q = String(songTitle || '').trim();
            if (!q) return '';

            const cached = getCachedMusicTimeVideoId(q);
            if (cached) return cached;

            const key = normalizeMusicTimeSongKey(q);
            if (_musicTimeResolveInflight.has(key)) return _musicTimeResolveInflight.get(key);

            const task = (async () => {
                const ytKey = getYoutubeDataApiKey();
                // videoCategoryId 없이 검색(더 빠르고 결과 누락 적음) + Piped 병렬 레이스
                const ytUrl =
                    'https://www.googleapis.com/youtube/v3/search' +
                    `?part=snippet&type=video&maxResults=1&q=${encodeURIComponent(q)}&key=${encodeURIComponent(ytKey)}`;
                const pipedUrls = [
                    `https://pipedapi.kavin.rocks/search?q=${encodeURIComponent(q)}&filter=music_songs`,
                    `https://pipedapi.adminforge.de/search?q=${encodeURIComponent(q)}&filter=music_songs`,
                ];

                const tryYoutube = (async () => {
                    const res = await fetchWithTimeout(ytUrl, 1600);
                    if (!res.ok) return '';
                    const data = await res.json();
                    return (data && data.items && data.items[0] && data.items[0].id && data.items[0].id.videoId) || '';
                })().catch(() => '');

                const tryPiped = (url) => (async () => {
                    const res = await fetchWithTimeout(url, 1600);
                    if (!res.ok) return '';
                    const data = await res.json();
                    const items = Array.isArray(data && data.items) ? data.items : (Array.isArray(data) ? data : []);
                    return extractVideoIdFromPipedItem(items.find((it) => it && (it.url || it.id || it.videoId)));
                })().catch(() => '');

                const racers = [tryYoutube, ...pipedUrls.map(tryPiped)];
                const videoId = await Promise.any(
                    racers.map((p) => p.then((id) => {
                        if (!id) throw new Error('empty');
                        return String(id);
                    }))
                ).catch(() => '');

                if (videoId) setCachedMusicTimeVideoId(q, videoId);
                return videoId;
            })();

            _musicTimeResolveInflight.set(key, task);
            try {
                return await task;
            } finally {
                _musicTimeResolveInflight.delete(key);
            }
        }

        /** 신청곡명으로 유튜브 뮤직 재생 URL 생성(가능하면 첫 검색 결과 바로 재생) */
        async function resolveYoutubeMusicPlayUrl(songTitle) {
            const q = String(songTitle || '').trim();
            if (!q) return { url: 'https://music.youtube.com/', mode: 'home' };
            const searchUrl = buildYoutubeMusicSearchUrl(q);
            const videoId = await searchYoutubeVideoIdFast(q);
            if (videoId) {
                return { url: buildYoutubeMusicWatchUrl(videoId), mode: 'play', videoId };
            }
            return { url: searchUrl, mode: 'search' };
        }

        function prefetchMusicTimePlayUrls(songs) {
            const list = Array.isArray(songs) ? songs : [];
            list.slice(0, 40).forEach((song) => {
                const q = String(song || '').trim();
                if (!q) return;
                if (getCachedMusicTimeVideoId(q)) return;
                void searchYoutubeVideoIdFast(q);
            });
        }

        window.playMusicTimeRequest = async function(requestId) {
            const rid = String(requestId || '');
            const target = getMusicTimeQueue().find((row) => String(row.id) === rid);
            if (!target) return await window.customAlert('이미 처리되었거나 신청곡을 찾을 수 없습니다.');
            const song = String(target.song || '').trim();
            if (!song) return await window.customAlert('곡명이 비어 있습니다.');

            const btn = document.querySelector(`button[data-music-play-id="${CSS.escape(rid)}"]`);
            const prevLabel = btn ? btn.innerHTML : '';
            if (btn) {
                btn.disabled = true;
                btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> 재생';
            }

            // 클릭 제스처에서 고정 이름 창을 우리 브리지로 확보(이미 떠 있으면 그 창을 재사용)
            const claimed = claimYtmBridgeWindow();
            if (!claimed) {
                if (btn) {
                    btn.disabled = false;
                    btn.innerHTML = prevLabel || '<i class="fa-solid fa-play"></i> 재생';
                }
                return await window.customAlert(
                    '팝업이 차단되어 유튜브 뮤직을 열 수 없습니다.\n브라우저에서 팝업을 허용한 뒤 다시 눌러 주세요.'
                );
            }

            try {
                const cachedId = getCachedMusicTimeVideoId(song);
                let videoId = cachedId;
                if (!videoId) videoId = await searchYoutubeVideoIdFast(song);

                const finalUrl = videoId
                    ? buildYoutubeMusicWatchUrl(videoId)
                    : buildYoutubeMusicSearchUrl(song);

                // wait 브리지 → 최종 URL 브리지(같은 창). music으로의 이동은 브리지가 담당
                navigateYtmBridgeWindow(claimed, finalUrl);

                if (!videoId) {
                    await window.customAlert(
                        `검색 결과를 열었습니다.\n\n🎵 ${song}\n\n첫 곡을 눌러 재생해 주세요.`
                    );
                }
            } catch (e) {
                console.error('playMusicTimeRequest', e);
            } finally {
                if (btn) {
                    btn.disabled = false;
                    btn.innerHTML = prevLabel || '<i class="fa-solid fa-play"></i> 재생';
                }
            }
        };

        function renderMusicTimeQueueModalBody() {
            const body = document.getElementById('musicTimeQueueModalBody');
            if (!body) return;
            const queue = getMusicTimeQueue().slice().sort((a, b) => (Number(a.at) || 0) - (Number(b.at) || 0));
            const isGM = !!(window.playerState && window.playerState.isGM);
            if (!queue.length) {
                body.innerHTML = '<div class="text-[10px] text-slate-500 text-center py-10 border border-dashed border-slate-700 rounded-xl">대기 중인 신청곡이 없습니다.</div>';
                return;
            }
            prefetchMusicTimePlayUrls(queue.map((row) => row.song));
            body.innerHTML = `
                <div class="text-[9px] text-slate-400 mb-3">총 ${queue.length}곡 · 「재생」은 같은 유튜브 뮤직 창에서 이어서 열립니다.</div>
                <div class="space-y-2">
                    ${queue.map((row, idx) => `
                        <div class="rounded-xl border border-slate-700/80 bg-slate-950/60 px-3 py-2">
                            <div class="flex items-start justify-between gap-2">
                                <div class="min-w-0 flex-1">
                                    <div class="text-[9px] text-pink-300/80 font-bold mb-0.5">#${idx + 1} · ${escapeConvenienceHtml(row.studentName)} <span class="text-slate-500 font-normal">(${escapeConvenienceHtml(row.studentId)}번)</span></div>
                                    <div class="text-sm text-white font-bold break-words">🎵 ${escapeConvenienceHtml(row.song)}</div>
                                    <div class="text-[9px] text-slate-500 mt-1">${formatMusicTimeAt(row.at)}</div>
                                </div>
                                <div class="shrink-0 flex flex-col gap-1">
                                    <button type="button" data-music-play-id="${escapeHtmlAttr(row.id)}" onclick="window.playMusicTimeRequest('${escapeHtmlAttr(row.id)}')" class="bg-pink-800 hover:bg-pink-700 text-white text-[9px] font-bold py-1.5 px-2 rounded-lg border border-pink-500/70">
                                        <i class="fa-solid fa-play"></i> 재생
                                    </button>
                                    ${isGM ? `<button type="button" onclick="window.completeMusicTimeRequestAdmin('${escapeHtmlAttr(row.id)}')" class="bg-emerald-800 hover:bg-emerald-700 text-white text-[9px] font-bold py-1.5 px-2 rounded-lg border border-emerald-600">재생완료</button>` : ''}
                                </div>
                            </div>
                        </div>`).join('')}
                </div>
                <p class="text-[9px] text-slate-500 mt-3 leading-relaxed">「재생」을 누르면 유튜브 뮤직에서 첫 검색 곡을 같은 창에 이어서 재생합니다.${isGM ? ` ${getMasterDisplayName()}만 「재생완료」로 목록에서 제거할 수 있습니다.` : ''}</p>`;
        }

        window.openMusicTimeQueuePanel = function() {
            const modal = ensureMusicTimeQueueModal();
            renderMusicTimeQueueModalBody();
            modal.classList.remove('hidden');
        };

        window.closeMusicTimeQueuePanel = function() {
            const modal = document.getElementById('musicTimeQueueModal');
            if (modal) modal.classList.add('hidden');
        };

        window.completeMusicTimeRequestAdmin = async function(requestId) {
            if (!window.playerState || !window.playerState.isGM) {
                return await window.customAlert(`${getMasterDisplayName()}만 재생 완료 처리할 수 있습니다.`);
            }
            if (!db) return await window.customAlert('데이터베이스에 연결되지 않았습니다.');
            const rid = String(requestId || '');
            const target = getMusicTimeQueue().find((row) => String(row.id) === rid);
            if (!target) return await window.customAlert('이미 처리되었거나 신청곡을 찾을 수 없습니다.');
            const ok = await window.customConfirm(
                `재생 완료 처리할까요?\n\n` +
                `- 신청: ${target.studentName}\n` +
                `- 곡: ${target.song}\n\n` +
                '목록에서 삭제됩니다.'
            );
            if (!ok) return;
            try {
                const authOk = await ensureAnonAuthReady();
                if (!authOk) return await window.customAlert('인증에 실패했습니다.');
                await runTransaction(db, async (transaction) => {
                    const ref = getGlobalSettingsDocRef();
                    const snap = await transaction.get(ref);
                    const data = snap.exists() ? snap.data() || {} : {};
                    const queue = sanitizeMusicTimeQueue(data.musicTimeQueue).filter((row) => String(row.id) !== rid);
                    transaction.set(ref, { musicTimeQueue: queue }, { merge: true });
                });
                if (!window.globalSettings) window.globalSettings = {};
                window.globalSettings.musicTimeQueue = sanitizeMusicTimeQueue(
                    (window.globalSettings.musicTimeQueue || []).filter((row) => String(row.id) !== rid)
                );
                renderMusicTimeQueueBar();
                renderMusicTimeQueueModalBody();
            } catch (e) {
                console.error('completeMusicTimeRequestAdmin', e);
                await window.customAlert('처리 실패: ' + (e && e.message ? e.message : String(e)));
            }
        };

        const MUSIC_TIME_SEEN_STORAGE_KEY = 'sambong_seen_music_time_requests';

        function getSeenMusicTimeRequestIds() {
            try {
                const raw = localStorage.getItem(MUSIC_TIME_SEEN_STORAGE_KEY) || '[]';
                const arr = JSON.parse(raw);
                return new Set(Array.isArray(arr) ? arr.map(String) : []);
            } catch (e) {
                return new Set();
            }
        }

        function markSeenMusicTimeRequestIds(ids) {
            const seen = getSeenMusicTimeRequestIds();
            ids.forEach((id) => seen.add(String(id)));
            localStorage.setItem(MUSIC_TIME_SEEN_STORAGE_KEY, JSON.stringify(Array.from(seen).slice(-MUSIC_TIME_QUEUE_MAX)));
        }

        /** 신청곡 큐에 새 항목이 들어오면 마스터에게 곡(id)당 최초 1회 팝업 */
        function maybeShowMusicTimeRequestPopup({ fromCache = false } = {}) {
            if (fromCache) return;
            if (!window.playerState || window.playerState.isGuest || !window.playerState.isAdmin) return;
            const queue = getMusicTimeQueue();
            if (!queue.length) return;
            const seen = getSeenMusicTimeRequestIds();
            const fresh = queue.filter((row) => !seen.has(String(row.id)));
            if (!fresh.length) return;
            markSeenMusicTimeRequestIds(fresh.map((row) => row.id));
            if (fresh.length === 1) {
                const row = fresh[0];
                void window.customAlert(
                    `🎵 뮤직 타임 신청곡\n\n` +
                    `- 신청: ${row.studentName} (${row.studentId}번)\n` +
                    `- 곡: ${row.song}\n\n` +
                    `상점 「신청곡 리스트 보기」에서 확인할 수 있어요.`
                );
                return;
            }
            const lines = fresh
                .slice()
                .sort((a, b) => (Number(a.at) || 0) - (Number(b.at) || 0))
                .map((row, idx) => `${idx + 1}. ${row.studentName} · ${row.song}`)
                .join('\n');
            void window.customAlert(
                `🎵 뮤직 타임 신청곡 ${fresh.length}건\n\n${lines}\n\n상점 「신청곡 리스트 보기」에서 확인할 수 있어요.`
            );
        }

        // ★ 주간 시간표 (마스터 탭 · Firestore globalSettings.classTimetable) ★
        const CLASS_TIMETABLE_DAYS = [
            { key: 'mon', label: '월' },
            { key: 'tue', label: '화' },
            { key: 'wed', label: '수' },
            { key: 'thu', label: '목' },
            { key: 'fri', label: '금' },
        ];
        const CLASS_TIMETABLE_PERIODS = [
            { id: 1, label: '1교시', start: '09:00', end: '09:40' },
            { id: 2, label: '2교시', start: '09:50', end: '10:30' },
            { id: 3, label: '3교시', start: '10:40', end: '11:20' },
            { id: 4, label: '4교시', start: '11:30', end: '12:10' },
            { id: 5, label: '5교시', start: '13:10', end: '13:50' },
            { id: 6, label: '6교시', start: '14:00', end: '14:40' },
        ];
        const CLASS_TIMETABLE_LUNCH = { label: '점심', start: '12:10', end: '13:10' };

        function sanitizeClassTimetable(raw) {
            const emptyDays = {};
            CLASS_TIMETABLE_DAYS.forEach((d) => {
                emptyDays[d.key] = {};
                for (let p = 1; p <= 6; p++) emptyDays[d.key][p] = '';
            });
            if (!raw || typeof raw !== 'object') return { days: emptyDays };
            const days = {};
            CLASS_TIMETABLE_DAYS.forEach((d) => {
                const src = raw.days && raw.days[d.key] && typeof raw.days[d.key] === 'object' ? raw.days[d.key] : {};
                days[d.key] = {};
                for (let p = 1; p <= 6; p++) {
                    const v = src[p] != null ? src[p] : src[String(p)];
                    days[d.key][p] = String(v || '').trim().slice(0, 30);
                }
            });
            return { days };
        }

        function getClassTimetable() {
            return sanitizeClassTimetable(window.globalSettings && window.globalSettings.classTimetable);
        }

        function getClassTimetableDayKeyFromDate(now = new Date()) {
            return ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'][now.getDay()];
        }

        function parseClassTimetableTimeToMinutes(hhmm) {
            const parts = String(hhmm || '').split(':');
            const h = parseInt(parts[0], 10);
            const m = parseInt(parts[1], 10);
            if (!Number.isFinite(h) || !Number.isFinite(m)) return null;
            return h * 60 + m;
        }

        function isClassTimetablePanelEditing() {
            const panel = document.getElementById('classTimetablePanel');
            if (!panel) return false;
            const active = document.activeElement;
            return !!(active && panel.contains(active) && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA'));
        }

        window.renderClassTimetableAdminPanel = function() {
            const grid = document.getElementById('classTimetableGrid');
            if (!grid) return;
            if (!window.playerState || !window.playerState.isAdmin) {
                grid.innerHTML = '<div class="text-slate-500 text-[9px] text-center py-4">마스터만 편집할 수 있습니다.</div>';
                return;
            }
            const tt = getClassTimetable();
            const headerCells = CLASS_TIMETABLE_DAYS.map((d) =>
                `<th class="p-1.5 text-center text-violet-200 min-w-[72px]">${d.label}</th>`
            ).join('');
            const periodRows = CLASS_TIMETABLE_PERIODS.map((period) => {
                const cells = CLASS_TIMETABLE_DAYS.map((d) => {
                    const val = tt.days[d.key][period.id] || '';
                    return `<td class="p-1">
                        <input type="text" data-tt-day="${d.key}" data-tt-period="${period.id}" value="${escapeHtmlAttr(val)}" maxlength="30"
                            class="w-full min-w-[64px] bg-slate-950 border border-slate-700 text-white px-1.5 py-1 rounded text-[10px] font-bold focus:outline-none focus:border-violet-500"
                            placeholder="과목" />
                    </td>`;
                }).join('');
                return `<tr class="border-b border-slate-800">
                    <td class="p-1.5 text-[9px] text-slate-400 whitespace-nowrap font-bold">${period.label}<br><span class="text-[8px] text-slate-500">${period.start}~${period.end}</span></td>
                    ${cells}
                </tr>`;
            }).join('');
            const lunchRow = `<tr class="border-b border-slate-800 bg-slate-950/40">
                <td class="p-1.5 text-[9px] text-amber-400/90 whitespace-nowrap font-bold">${CLASS_TIMETABLE_LUNCH.label}<br><span class="text-[8px] text-slate-500">${CLASS_TIMETABLE_LUNCH.start}~${CLASS_TIMETABLE_LUNCH.end}</span></td>
                ${CLASS_TIMETABLE_DAYS.map(() => '<td class="p-1 text-center text-[8px] text-slate-600">—</td>').join('')}
            </tr>`;
            grid.innerHTML = `
                <table class="w-full text-left min-w-[480px] border border-slate-700/80 rounded-lg overflow-hidden">
                    <thead class="bg-slate-800 text-slate-400 text-[9px]">
                        <tr><th class="p-1.5 w-20">교시</th>${headerCells}</tr>
                    </thead>
                    <tbody>${periodRows}${lunchRow}</tbody>
                </table>`;
        };

        window.saveClassTimetableFromAdmin = async function() {
            if (!window.playerState || !window.playerState.isAdmin) return;
            if (!db) return window.customAlert('데이터베이스에 연결되지 않았습니다.');
            const grid = document.getElementById('classTimetableGrid');
            if (!grid) return;
            const inputs = grid.querySelectorAll('input[data-tt-day][data-tt-period]');
            const days = {};
            CLASS_TIMETABLE_DAYS.forEach((d) => { days[d.key] = {}; });
            inputs.forEach((inp) => {
                const day = inp.getAttribute('data-tt-day');
                const period = parseInt(inp.getAttribute('data-tt-period'), 10);
                if (!day || !Number.isFinite(period)) return;
                if (!days[day]) days[day] = {};
                days[day][period] = String(inp.value || '').trim().slice(0, 30);
            });
            const payload = { classTimetable: { days } };
            const statusEl = document.getElementById('classTimetableStatus');
            try {
                await setDoc(doc(db, 'artifacts', appId, 'public', 'data', 'settings', 'global'), payload, { merge: true });
                if (!window.globalSettings) window.globalSettings = {};
                window.globalSettings.classTimetable = payload.classTimetable;
                if (statusEl) statusEl.textContent = '✅ 시간표가 저장되었습니다.';
                await window.customAlert('✅ 주간 시간표가 저장되었습니다.');
            } catch (e) {
                console.error('saveClassTimetableFromAdmin', e);
                if (statusEl) statusEl.textContent = '저장 실패';
                await window.customAlert('저장 실패: ' + (e && e.message ? e.message : String(e)));
            }
        };

        function checkClassStartReminders(now = new Date()) {
            if (!window.playerState || !window.playerState.isAdmin) return;
            const dayKey = getClassTimetableDayKeyFromDate(now);
            if (!CLASS_TIMETABLE_DAYS.some((d) => d.key === dayKey)) return;
            const tt = getClassTimetable();
            const today = tt.days[dayKey] || {};
            const nowMin = now.getHours() * 60 + now.getMinutes();
            const dateKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
            for (const period of CLASS_TIMETABLE_PERIODS) {
                const startMin = parseClassTimetableTimeToMinutes(period.start);
                if (startMin == null) continue;
                if (nowMin < startMin || nowMin >= startMin + 2) continue;
                const alertKey = `sambong_class_prep_${dateKey}_${period.id}`;
                if (localStorage.getItem(alertKey) === '1') continue;
                localStorage.setItem(alertKey, '1');
                const subject = String(today[period.id] || '').trim();
                const subjectLine = subject ? `과목: ${subject}` : '과목: (시간표 미입력)';
                // 등록된 생일 축하(해당 교시·날짜)면 생일 파티 알림
                const bdayHit = getBirthdayCelebrationForPeriod(period.id, now);
                if (bdayHit) {
                    void showBirthdayClassStartAlert({ period, subjectLine, celebration: bdayHit });
                    continue;
                }
                void window.customAlert(
                    `🔔 수업 준비 알림\n\n` +
                    `${period.label} (${period.start}~${period.end})\n` +
                    `${subjectLine}\n\n` +
                    `수업 시작 시간입니다. 준비해 주세요!`
                );
            }
        }

        // ==========================================
        // ★ 생일 축하 파티 (이름·날짜 설정 가능) ★
        // ==========================================
        const DEFAULT_SEED_BIRTHDAY_CELEBRATIONS = [
            { id: 'bday_seok', name: '석서영', nickname: '서영', month: 7, day: 10, periodId: 6, enabled: true },
        ];

        function sanitizeBirthdayCelebrations(raw) {
            const list = Array.isArray(raw) ? raw : [];
            const out = [];
            const seen = new Set();
            list.forEach((row, idx) => {
                if (!row || typeof row !== 'object') return;
                const name = String(row.name || '').trim().slice(0, 20);
                if (!name) return;
                const month = Math.max(1, Math.min(12, Math.floor(Number(row.month) || 0)));
                const day = Math.max(1, Math.min(31, Math.floor(Number(row.day) || 0)));
                if (!month || !day) return;
                let id = String(row.id || '').trim().slice(0, 40);
                if (!id) id = `bday_${Date.now()}_${idx}`;
                if (seen.has(id)) id = `${id}_${idx}`;
                seen.add(id);
                const nickname = String(row.nickname || name).trim().slice(0, 20) || name;
                const periodId = Math.max(1, Math.min(6, Math.floor(Number(row.periodId) || 6)));
                const enabled = row.enabled !== false;
                out.push({ id, name, nickname, month, day, periodId, enabled });
            });
            return out.slice(0, 40);
        }

        function getBirthdayCelebrations() {
            const fromSettings = window.globalSettings && window.globalSettings.birthdayCelebrations;
            if (Array.isArray(fromSettings)) {
                return sanitizeBirthdayCelebrations(fromSettings);
            }
            // 시드 학급만 기존 석서영 일정을 기본값으로 제공 (다른 학급은 빈 목록)
            if (isSeedDemoClass()) return sanitizeBirthdayCelebrations(DEFAULT_SEED_BIRTHDAY_CELEBRATIONS);
            return [];
        }

        function getBirthdayCelebrationsForToday(now = new Date()) {
            const m = now.getMonth() + 1;
            const d = now.getDate();
            return getBirthdayCelebrations().filter((c) => c.enabled && c.month === m && c.day === d);
        }

        function getBirthdayCelebrationForPeriod(periodId, now = new Date()) {
            const pid = Number(periodId);
            return getBirthdayCelebrationsForToday(now).find((c) => Number(c.periodId) === pid) || null;
        }

        function scheduleTone({ freq, start, duration, type = 'sine', gain = 0.18, detune = 0 }) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const osc = audioCtx.createOscillator();
            const g = audioCtx.createGain();
            osc.type = type;
            osc.frequency.setValueAtTime(freq, start);
            if (detune) osc.detune.setValueAtTime(detune, start);
            g.gain.setValueAtTime(0.0001, start);
            g.gain.exponentialRampToValueAtTime(gain, start + 0.02);
            g.gain.exponentialRampToValueAtTime(0.0001, start + Math.max(0.05, duration - 0.02));
            osc.connect(g);
            g.connect(audioCtx.destination);
            osc.start(start);
            osc.stop(start + duration + 0.05);
        }

        function playBirthdayFanfare() {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const t0 = audioCtx.currentTime + 0.05;
            const notes = [523.25, 659.25, 783.99, 1046.5, 1318.5];
            notes.forEach((f, i) => {
                scheduleTone({ freq: f, start: t0 + i * 0.09, duration: 0.28, type: 'square', gain: 0.38 });
                scheduleTone({ freq: f, start: t0 + i * 0.09, duration: 0.26, type: 'triangle', gain: 0.32 });
                scheduleTone({ freq: f * 2, start: t0 + i * 0.09, duration: 0.22, type: 'sine', gain: 0.2 });
            });
            [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => {
                scheduleTone({ freq: f, start: t0 + 0.55, duration: 0.65, type: 'square', gain: 0.28 - i * 0.02 });
                scheduleTone({ freq: f, start: t0 + 0.55, duration: 0.65, type: 'triangle', gain: 0.24 - i * 0.02 });
            });
        }

        /** Happy Birthday 멜로디 + 가사 타임라인 (초) — nickname 삽입 */
        function getBirthdaySongTimeline(nickname) {
            const nick = String(nickname || '생일').trim() || '생일';
            const N = {
                C4: 261.63, D4: 293.66, E4: 329.63, F4: 349.23,
                G4: 392.00, A4: 440.00, Bb4: 466.16, C5: 523.25,
            };
            const melody = [
                [N.C4, 0.00, 0.28], [N.C4, 0.30, 0.22], [N.D4, 0.55, 0.45], [N.C4, 1.05, 0.45], [N.F4, 1.55, 0.45], [N.E4, 2.05, 0.70],
                [N.C4, 2.90, 0.28], [N.C4, 3.20, 0.22], [N.D4, 3.45, 0.45], [N.C4, 3.95, 0.45], [N.G4, 4.45, 0.45], [N.F4, 4.95, 0.70],
                [N.C4, 5.80, 0.28], [N.C4, 6.10, 0.22], [N.C5, 6.35, 0.45], [N.A4, 6.85, 0.45], [N.F4, 7.35, 0.40], [N.E4, 7.80, 0.40], [N.D4, 8.25, 0.70],
                [N.Bb4, 9.10, 0.28], [N.Bb4, 9.40, 0.22], [N.A4, 9.65, 0.45], [N.F4, 10.15, 0.45], [N.G4, 10.65, 0.45], [N.F4, 11.15, 0.85],
            ];
            const lyrics = [
                { at: 0.00, text: '생일 축하합니다~' },
                { at: 2.90, text: '생일 축하합니다~' },
                { at: 5.80, text: `사랑하는 ${nick}~` },
                { at: 9.10, text: '생일 축하합니다!' },
                { at: 12.10, text: '🍦 아이스크림 케이크 파티 GO!' },
            ];
            return { melody, lyrics, durationSec: 13.2 };
        }

        function playCountdownBeep(freq = 880) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const t0 = audioCtx.currentTime;
            scheduleTone({ freq, start: t0, duration: 0.18, type: 'square', gain: 0.28 });
            scheduleTone({ freq: freq * 2, start: t0, duration: 0.14, type: 'sine', gain: 0.12 });
        }

        function playCountdownStartChord() {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const t0 = audioCtx.currentTime;
            [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => {
                scheduleTone({ freq: f, start: t0, duration: 0.45, type: 'triangle', gain: 0.22 - i * 0.02 });
                scheduleTone({ freq: f, start: t0, duration: 0.4, type: 'square', gain: 0.14 - i * 0.015 });
            });
        }

        function scheduleChord({ root, start, duration, gain = 0.28 }) {
            const third = root * Math.pow(2, 4 / 12);
            const fifth = root * Math.pow(2, 7 / 12);
            const octave = root * 2;
            scheduleTone({ freq: root, start, duration, type: 'triangle', gain: gain * 0.95 });
            scheduleTone({ freq: root, start, duration, type: 'square', gain: gain * 0.55 });
            scheduleTone({ freq: third, start, duration: duration * 0.95, type: 'triangle', gain: gain * 0.55 });
            scheduleTone({ freq: fifth, start, duration: duration * 0.95, type: 'sine', gain: gain * 0.5 });
            scheduleTone({ freq: octave, start, duration: duration * 0.9, type: 'sine', gain: gain * 0.35 });
            scheduleTone({ freq: root / 2, start, duration, type: 'triangle', gain: gain * 0.32 });
            scheduleTone({ freq: fifth / 2, start: start + 0.03, duration: duration * 0.9, type: 'sine', gain: gain * 0.18 });
        }

        function playBirthdaySong(nickname) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const { melody } = getBirthdaySongTimeline(nickname);
            const t0 = audioCtx.currentTime + 0.05;
            melody.forEach(([freq, start, dur]) => {
                scheduleChord({ root: freq * 2, start: t0 + start, duration: dur, gain: 0.34 });
            });
            return t0;
        }

        function spawnBirthdayConfetti(root, count = 55) {
            const colors = ['#f472b6', '#fbbf24', '#34d399', '#60a5fa', '#c084fc', '#fb7185', '#fde68a'];
            for (let i = 0; i < count; i++) {
                const p = document.createElement('span');
                p.className = 'seok-bday-confetti';
                p.style.left = `${Math.random() * 100}%`;
                p.style.background = colors[i % colors.length];
                p.style.animationDelay = `${Math.random() * 0.8}s`;
                p.style.animationDuration = `${2.2 + Math.random() * 2.2}s`;
                p.style.transform = `rotate(${Math.random() * 360}deg)`;
                root.appendChild(p);
            }
        }

        function ensureBirthdayPartyStyles() {
            let style = document.getElementById('birthdayPartyStyles');
            if (!style) {
                style = document.createElement('style');
                style.id = 'birthdayPartyStyles';
                document.head.appendChild(style);
            }
            style.textContent = `
                @keyframes seokBdayPop { 0%{transform:scale(.72);opacity:0} 60%{transform:scale(1.04);opacity:1} 100%{transform:scale(1)} }
                @keyframes seokBdayShine { 0%,100%{filter:drop-shadow(0 0 10px rgba(251,191,36,.45))} 50%{filter:drop-shadow(0 0 28px rgba(244,114,182,.9))} }
                @keyframes seokBdayConfettiFall { 0%{transform:translateY(-10vh) rotate(0deg);opacity:1} 100%{transform:translateY(110vh) rotate(720deg);opacity:0} }
                @keyframes seokBdayCakeBounce { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-14px)} }
                @keyframes seokBdayLyricIn { 0%{opacity:0;transform:translateY(14px) scale(.92)} 100%{opacity:1;transform:translateY(0) scale(1)} }
                .seok-bday-overlay{position:fixed;inset:0;z-index:420;display:flex;align-items:center;justify-content:center;padding:.75rem;
                    background:radial-gradient(circle at 50% 18%,rgba(251,191,36,.42),transparent 42%),
                    linear-gradient(160deg,#831843 0%,#4c1d95 45%,#0f172a 100%);overflow:hidden}
                .seok-bday-card{position:relative;z-index:2;max-width:56rem;width:min(96vw,56rem);text-align:center;border-radius:2rem;
                    border:3px solid rgba(251,191,36,.65);background:rgba(15,23,42,.88);backdrop-filter:blur(12px);
                    padding:2rem 1.75rem 1.5rem;box-shadow:0 0 80px rgba(244,114,182,.45);animation:seokBdayPop .55s ease-out}
                .seok-bday-eyebrow{font-family:'Jua',sans-serif;font-size:clamp(1rem,2.4vw,1.35rem);letter-spacing:.28em;color:#f9a8d4;margin-bottom:.35rem}
                .seok-bday-title{font-family:'Jua',sans-serif;font-size:clamp(2.4rem,6.5vw,4.2rem);line-height:1.2;font-weight:400;color:#fde68a;animation:seokBdayShine 1.6s ease-in-out infinite}
                .seok-bday-cake{font-size:clamp(4rem,10vw,6.5rem);line-height:1;animation:seokBdayCakeBounce 1.1s ease-in-out infinite;margin:.5rem 0 .75rem}
                .seok-bday-msg{font-family:'Gaegu',cursive;font-size:clamp(1.45rem,3.6vw,2.15rem);line-height:1.45;color:#fce7f3;font-weight:700;margin-bottom:1rem}
                .seok-bday-msg .hi{color:#fde68a}
                .seok-bday-lyric{font-family:'Jua',sans-serif;min-height:4.2rem;display:flex;align-items:center;justify-content:center;
                    font-size:clamp(1.9rem,5.2vw,3.1rem);font-weight:400;color:#fff;line-height:1.25;
                    text-shadow:0 0 22px rgba(244,114,182,.95);animation:seokBdayLyricIn .35s ease-out}
                .seok-bday-lyric.is-countdown{font-size:clamp(2.6rem,8vw,4.8rem);color:#fde68a;text-shadow:0 0 28px rgba(251,191,36,.95)}
                .seok-bday-hint{font-family:'Gaegu',cursive;font-size:clamp(1.1rem,2.5vw,1.45rem);color:#cbd5e1;margin:.85rem 0 1rem}
                .seok-bday-close{font-family:'Jua',sans-serif;font-size:clamp(1.05rem,2.4vw,1.35rem)!important;padding:1rem 1.25rem!important}
                .seok-bday-confetti{position:absolute;top:-12px;width:12px;height:16px;border-radius:2px;z-index:1;
                    animation-name:seokBdayConfettiFall;animation-timing-function:linear;animation-fill-mode:forwards;pointer-events:none}
                @media (max-width:640px){
                    .seok-bday-card{padding:1.35rem 1rem 1.1rem;border-radius:1.5rem}
                }
            `;
        }

        function showBirthdayClassStartAlert({ period, subjectLine, celebration }) {
            const name = celebration?.name || '친구';
            const nick = celebration?.nickname || name;
            const safeName = escapeConvenienceHtml ? escapeConvenienceHtml(name) : String(name).replace(/</g, '&lt;');
            return new Promise((resolve) => {
                const d = document.createElement('div');
                d.className = 'fixed inset-0 z-[310] flex items-center justify-center bg-black/85 px-4';
                d.innerHTML = `
                    <div class="bg-gradient-to-b from-pink-950/95 to-slate-900 p-8 sm:p-10 rounded-3xl border-2 border-pink-400/50 max-w-xl w-full text-center space-y-5 shadow-2xl">
                        <div class="text-6xl sm:text-7xl">🎂🎉🍦</div>
                        <h3 class="text-3xl sm:text-4xl font-display text-pink-100" style="font-family:'Jua',sans-serif">${period.label} 수업 준비</h3>
                        <p class="text-lg sm:text-xl text-slate-100 whitespace-pre-wrap leading-relaxed" style="font-family:'Gaegu',cursive;font-weight:700">${period.label} (${period.start}~${period.end})
${subjectLine}

오늘은 <span class="text-amber-300 font-black">${safeName}</span> 생일!
아이스크림 케이크와 함께
생일 파티를 준비해요 🎈</p>
                        <button type="button" class="js-bday-class-start w-full bg-gradient-to-r from-pink-600 to-amber-500 hover:from-pink-500 hover:to-amber-400 text-white font-black py-4 px-6 rounded-full text-xl sm:text-2xl shadow-lg border border-amber-200/40" style="font-family:'Jua',sans-serif">
                            수업시작 🎂
                        </button>
                        <button type="button" class="js-bday-class-later w-full bg-slate-700 hover:bg-slate-600 text-slate-200 font-bold py-3 px-6 rounded-full text-base">
                            나중에
                        </button>
                    </div>`;
                document.body.appendChild(d);
                const startBtn = d.querySelector('.js-bday-class-start');
                const laterBtn = d.querySelector('.js-bday-class-later');
                if (startBtn) {
                    startBtn.onclick = () => {
                        d.remove();
                        window.startBirthdayParty(celebration);
                        resolve(true);
                    };
                }
                if (laterBtn) {
                    laterBtn.onclick = () => { d.remove(); resolve(false); };
                }
            });
        }

        let _birthdayPartyTimers = [];
        function clearBirthdayPartyTimers() {
            _birthdayPartyTimers.forEach((id) => clearTimeout(id));
            _birthdayPartyTimers = [];
        }

        window.startBirthdayParty = function(celebrationOrName) {
            let celebration = celebrationOrName;
            if (typeof celebrationOrName === 'string') {
                celebration = { name: celebrationOrName, nickname: celebrationOrName };
            }
            if (!celebration || !celebration.name) {
                celebration = { name: '생일', nickname: '생일' };
            }
            const name = String(celebration.name || '생일').trim() || '생일';
            const nick = String(celebration.nickname || name).trim() || name;
            const periodLabel = (() => {
                const pid = Number(celebration.periodId) || 6;
                const p = (typeof CLASS_TIMETABLE_PERIODS !== 'undefined')
                    ? CLASS_TIMETABLE_PERIODS.find((x) => x.id === pid)
                    : null;
                return p ? p.label : `${pid}교시`;
            })();

            ensureBirthdayPartyStyles();
            clearBirthdayPartyTimers();
            const existing = document.getElementById('birthdayPartyOverlay');
            if (existing) existing.remove();

            const overlay = document.createElement('div');
            overlay.id = 'birthdayPartyOverlay';
            overlay.className = 'seok-bday-overlay';
            overlay.innerHTML = `
                <div class="seok-bday-card">
                    <p class="seok-bday-eyebrow">SPECIAL BIRTHDAY CLASS</p>
                    <h2 class="seok-bday-title">${escapeConvenienceHtml(name)} 생일 축하합니다!</h2>
                    <div class="seok-bday-cake" aria-hidden="true">🍦🎂✨</div>
                    <p class="seok-bday-msg">
                        ${escapeConvenienceHtml(periodLabel)} 수업을 열며<br>
                        <span class="hi">${escapeConvenienceHtml(nick)}</span>의 특별한 하루를 함께 축하해요!<br>
                        아이스크림 케이크를 나눠 먹고<br>
                        신나는 생일 파티를 시작합시다 🎉
                    </p>
                    <div id="birthdayPartyLyric" class="seok-bday-lyric is-countdown">다함께 노래 불러요~</div>
                    <p class="seok-bday-hint">크게 손뼉 치며 준비하세요!</p>
                    <button type="button" class="js-bday-close seok-bday-close w-full bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-full border border-white/15">
                        파티 마무리 · 수업 시작!
                    </button>
                </div>`;
            document.body.appendChild(overlay);
            spawnBirthdayConfetti(overlay, 48);

            const close = () => {
                clearBirthdayPartyTimers();
                overlay.remove();
            };
            const closeBtn = overlay.querySelector('.js-bday-close');
            if (closeBtn) closeBtn.onclick = close;

            const lyricEl = document.getElementById('birthdayPartyLyric');
            const hintEl = overlay.querySelector('.seok-bday-hint');
            const { lyrics, durationSec } = getBirthdaySongTimeline(nick);

            function setLyricText(text, countdown = false) {
                if (!lyricEl) return;
                lyricEl.classList.toggle('is-countdown', !!countdown);
                lyricEl.style.animation = 'none';
                void lyricEl.offsetWidth;
                lyricEl.style.animation = '';
                lyricEl.textContent = text;
            }

            const cueSteps = [
                { atMs: 0, text: '다함께 노래 불러요~', countdown: true, beep: null },
                { atMs: 1800, text: '3', countdown: true, beep: 880 },
                { atMs: 2800, text: '2', countdown: true, beep: 880 },
                { atMs: 3800, text: '1', countdown: true, beep: 880 },
                { atMs: 4800, text: '시작~', countdown: true, beep: 'start' },
            ];
            const songStartMs = 5600;

            cueSteps.forEach((step) => {
                _birthdayPartyTimers.push(setTimeout(() => {
                    setLyricText(step.text, step.countdown);
                    if (step.beep === 'start') playCountdownStartChord();
                    else if (typeof step.beep === 'number') playCountdownBeep(step.beep);
                }, step.atMs));
            });

            _birthdayPartyTimers.push(setTimeout(() => {
                if (hintEl) hintEl.textContent = '다 같이 손뼉 치며 크게 노래해요!';
                playBirthdayFanfare();
            }, songStartMs));

            const melodyOffsetMs = songStartMs + 900;
            _birthdayPartyTimers.push(setTimeout(() => {
                if (lyricEl) lyricEl.classList.remove('is-countdown');
                playBirthdaySong(nick);
                lyrics.forEach((row) => {
                    _birthdayPartyTimers.push(setTimeout(() => {
                        setLyricText(row.text, false);
                    }, Math.round(row.at * 1000)));
                });
            }, melodyOffsetMs));

            _birthdayPartyTimers.push(setTimeout(() => {
                setLyricText(`🥳 ${nick}, 생일 정말 축하해!`, false);
                spawnBirthdayConfetti(overlay, 40);
            }, melodyOffsetMs + Math.round(durationSec * 1000)));
        };

        /** 하위 호환: 예전 버튼/호출명 */
        window.startSeokBirthdayParty = function() {
            const today = getBirthdayCelebrationsForToday()[0];
            const fallback = getBirthdayCelebrations()[0] || DEFAULT_SEED_BIRTHDAY_CELEBRATIONS[0];
            return window.startBirthdayParty(today || fallback);
        };

        window.previewSeokBirthdayParty = function() {
            return window.previewBirthdayParty();
        };

        /** 마스터용: 목록에서 고르거나 오늘 일정으로 바로 실행 */
        window.previewBirthdayParty = async function(celebrationId) {
            if (!window.playerState || !window.playerState.isAdmin) {
                return window.customAlert('마스터만 미리보기를 실행할 수 있습니다.');
            }
            const list = getBirthdayCelebrations();
            if (!list.length) {
                return window.customAlert('등록된 생일 축하가 없습니다.\n아래에서 이름과 날짜를 추가해 주세요.');
            }
            let target = null;
            if (celebrationId) {
                target = list.find((c) => c.id === celebrationId) || null;
            }
            if (!target) {
                const today = getBirthdayCelebrationsForToday();
                if (today.length === 1) target = today[0];
                else if (list.length === 1) target = list[0];
                else {
                    const lines = list.map((c, i) => `${i + 1}. ${c.name} (${c.month}/${c.day})`).join('\n');
                    const picked = await window.customPrompt(
                        `실행할 생일 번호를 입력하세요.\n\n${lines}`,
                        'text'
                    );
                    const n = Math.floor(Number(picked));
                    if (!n || n < 1 || n > list.length) return window.customAlert('취소되었거나 번호가 올바르지 않습니다.');
                    target = list[n - 1];
                }
            }
            return window.startBirthdayParty(target);
        };

        window.renderBirthdayCelebrationAdminPanel = function() {
            const box = document.getElementById('birthdayCelebrationAdminPanel');
            if (!box) return;
            if (!window.playerState || !window.playerState.isAdmin) {
                box.innerHTML = '';
                return;
            }
            const list = getBirthdayCelebrations();
            const rows = list.length
                ? list.map((c) => `
                    <div class="flex flex-wrap items-center gap-2 rounded-xl border border-pink-500/30 bg-slate-950/60 p-2.5" data-bday-id="${escapeHtmlAttr(c.id)}">
                        <div class="flex-1 min-w-[8rem]">
                            <div class="text-pink-100 font-black text-xs">${escapeConvenienceHtml(c.name)}
                                <span class="text-slate-500 font-bold">(${escapeConvenienceHtml(c.nickname)})</span>
                            </div>
                            <div class="text-[9px] text-slate-400 font-bold mt-0.5">${c.month}월 ${c.day}일 · ${c.periodId}교시 알림 ${c.enabled ? 'ON' : 'OFF'}</div>
                        </div>
                        <button type="button" onclick="void window.previewBirthdayParty('${escapeHtmlAttr(c.id)}')" class="min-h-[40px] bg-pink-700 hover:bg-pink-600 text-white text-[9px] font-bold px-2.5 py-1.5 rounded-lg">파티 시작</button>
                        <button type="button" onclick="void window.editBirthdayCelebration('${escapeHtmlAttr(c.id)}')" class="min-h-[40px] bg-slate-700 hover:bg-slate-600 text-white text-[9px] font-bold px-2.5 py-1.5 rounded-lg">수정</button>
                        <button type="button" onclick="void window.deleteBirthdayCelebration('${escapeHtmlAttr(c.id)}')" class="min-h-[40px] bg-red-950/70 hover:bg-red-900 text-red-200 text-[9px] font-bold px-2.5 py-1.5 rounded-lg border border-red-800/50">삭제</button>
                    </div>`).join('')
                : '<p class="text-[10px] text-slate-500 font-bold text-center py-3">아직 등록된 생일이 없습니다. 아래에서 추가하세요.</p>';

            box.innerHTML = `
                <div class="space-y-2 mb-3">${rows}</div>
                <div class="rounded-xl border border-pink-500/40 bg-slate-950/50 p-3 space-y-2">
                    <p class="text-[10px] text-pink-200 font-black">생일 추가 / 수정</p>
                    <input type="hidden" id="bdayEditId" value="">
                    <div class="grid grid-cols-2 gap-2">
                        <label class="text-[9px] text-slate-400 font-bold col-span-2">이름
                            <input id="bdayNameInput" type="text" maxlength="20" placeholder="예: 석서영" class="mt-1 w-full bg-slate-900 border border-slate-700 text-white px-2 py-2 rounded-lg text-xs font-bold min-h-[40px]">
                        </label>
                        <label class="text-[9px] text-slate-400 font-bold col-span-2">호칭(노래·멘트용, 비우면 이름 사용)
                            <input id="bdayNickInput" type="text" maxlength="20" placeholder="예: 서영" class="mt-1 w-full bg-slate-900 border border-slate-700 text-white px-2 py-2 rounded-lg text-xs font-bold min-h-[40px]">
                        </label>
                        <label class="text-[9px] text-slate-400 font-bold">월
                            <input id="bdayMonthInput" type="number" min="1" max="12" value="1" class="mt-1 w-full bg-slate-900 border border-slate-700 text-white px-2 py-2 rounded-lg text-xs font-bold min-h-[40px]">
                        </label>
                        <label class="text-[9px] text-slate-400 font-bold">일
                            <input id="bdayDayInput" type="number" min="1" max="31" value="1" class="mt-1 w-full bg-slate-900 border border-slate-700 text-white px-2 py-2 rounded-lg text-xs font-bold min-h-[40px]">
                        </label>
                        <label class="text-[9px] text-slate-400 font-bold col-span-2">알림 교시
                            <select id="bdayPeriodInput" class="mt-1 w-full bg-slate-900 border border-slate-700 text-white px-2 py-2 rounded-lg text-xs font-bold min-h-[40px]">
                                <option value="1">1교시</option><option value="2">2교시</option><option value="3">3교시</option>
                                <option value="4">4교시</option><option value="5">5교시</option><option value="6" selected>6교시</option>
                            </select>
                        </label>
                    </div>
                    <div class="flex flex-wrap gap-2">
                        <button type="button" onclick="void window.saveBirthdayCelebrationFromForm()" class="flex-1 min-h-[44px] bg-gradient-to-r from-pink-700 to-amber-600 hover:from-pink-600 hover:to-amber-500 text-white font-black text-[10px] px-3 py-2 rounded-xl border border-amber-300/40">저장(추가/수정)</button>
                        <button type="button" onclick="window.clearBirthdayCelebrationForm()" class="min-h-[44px] bg-slate-800 hover:bg-slate-700 text-slate-200 font-bold text-[10px] px-3 py-2 rounded-xl border border-slate-600">입력 비우기</button>
                    </div>
                    <p class="text-[8px] text-slate-500 leading-relaxed">해당 날짜·교시 시작 알림에서 「수업시작」을 누르면 파티가 열립니다. 「파티 시작」으로 지금 바로 연출할 수도 있습니다.</p>
                </div>`;
        };

        window.clearBirthdayCelebrationForm = function() {
            const idEl = document.getElementById('bdayEditId');
            const nameEl = document.getElementById('bdayNameInput');
            const nickEl = document.getElementById('bdayNickInput');
            const monthEl = document.getElementById('bdayMonthInput');
            const dayEl = document.getElementById('bdayDayInput');
            const periodEl = document.getElementById('bdayPeriodInput');
            if (idEl) idEl.value = '';
            if (nameEl) nameEl.value = '';
            if (nickEl) nickEl.value = '';
            if (monthEl) monthEl.value = '1';
            if (dayEl) dayEl.value = '1';
            if (periodEl) periodEl.value = '6';
        };

        window.editBirthdayCelebration = function(id) {
            const c = getBirthdayCelebrations().find((x) => x.id === id);
            if (!c) return;
            const idEl = document.getElementById('bdayEditId');
            const nameEl = document.getElementById('bdayNameInput');
            const nickEl = document.getElementById('bdayNickInput');
            const monthEl = document.getElementById('bdayMonthInput');
            const dayEl = document.getElementById('bdayDayInput');
            const periodEl = document.getElementById('bdayPeriodInput');
            if (idEl) idEl.value = c.id;
            if (nameEl) nameEl.value = c.name;
            if (nickEl) nickEl.value = c.nickname || '';
            if (monthEl) monthEl.value = String(c.month);
            if (dayEl) dayEl.value = String(c.day);
            if (periodEl) periodEl.value = String(c.periodId || 6);
            nameEl?.focus();
        };

        window.saveBirthdayCelebrationFromForm = async function() {
            if (!window.playerState?.isAdmin || !db) return;
            const editId = String(document.getElementById('bdayEditId')?.value || '').trim();
            const name = String(document.getElementById('bdayNameInput')?.value || '').trim();
            const nickname = String(document.getElementById('bdayNickInput')?.value || '').trim();
            const month = Math.floor(Number(document.getElementById('bdayMonthInput')?.value));
            const day = Math.floor(Number(document.getElementById('bdayDayInput')?.value));
            const periodId = Math.floor(Number(document.getElementById('bdayPeriodInput')?.value) || 6);
            if (!name) return window.customAlert('이름을 입력해 주세요.');
            if (!(month >= 1 && month <= 12) || !(day >= 1 && day <= 31)) {
                return window.customAlert('월(1~12)·일(1~31)을 확인해 주세요.');
            }
            const next = {
                id: editId || `bday_${Date.now()}`,
                name,
                nickname: nickname || name,
                month,
                day,
                periodId: Math.max(1, Math.min(6, periodId)),
                enabled: true,
            };
            let list = getBirthdayCelebrations().slice();
            const idx = list.findIndex((c) => c.id === next.id);
            if (idx >= 0) list[idx] = { ...list[idx], ...next };
            else list.push(next);
            list = sanitizeBirthdayCelebrations(list);
            try {
                window.showGlobalLoading('생일 일정 저장 중…');
                const authOk = await ensureAnonAuthReady();
                if (!authOk) throw new Error('인증 실패');
                await setDoc(doc(db, 'artifacts', appId, 'public', 'data', 'settings', 'global'), {
                    birthdayCelebrations: list,
                }, { merge: true });
                if (!window.globalSettings) window.globalSettings = {};
                window.globalSettings.birthdayCelebrations = list;
                window.hideGlobalLoading();
                window.clearBirthdayCelebrationForm();
                window.renderBirthdayCelebrationAdminPanel();
                window.showToast?.('생일 일정을 저장했습니다!');
            } catch (e) {
                window.hideGlobalLoading();
                await window.customAlert('저장 실패: ' + (e && e.message ? e.message : String(e)));
            } finally {
                window.hideGlobalLoading();
            }
        };

        window.deleteBirthdayCelebration = async function(id) {
            if (!window.playerState?.isAdmin || !db) return;
            const c = getBirthdayCelebrations().find((x) => x.id === id);
            if (!c) return;
            const ok = await window.customConfirm(`「${c.name}」 생일 일정을 삭제할까요?`);
            if (!ok) return;
            const list = sanitizeBirthdayCelebrations(getBirthdayCelebrations().filter((x) => x.id !== id));
            try {
                window.showGlobalLoading('삭제 중…');
                await setDoc(doc(db, 'artifacts', appId, 'public', 'data', 'settings', 'global'), {
                    birthdayCelebrations: list,
                }, { merge: true });
                if (!window.globalSettings) window.globalSettings = {};
                window.globalSettings.birthdayCelebrations = list;
                window.hideGlobalLoading();
                window.renderBirthdayCelebrationAdminPanel();
            } catch (e) {
                window.hideGlobalLoading();
                await window.customAlert('삭제 실패: ' + (e && e.message ? e.message : String(e)));
            } finally {
                window.hideGlobalLoading();
            }
        };

        /** 상점 기본가(SHOP_DATA) — 마스터가 저장한 shopPrices와 병합 시 기준 */
        function getDefaultShopPrice(shopId) {
            const s = getShopItemById(shopId);
            return s ? Number(s.price) || 0 : 0;
        }

        function getWeekendRaidRewardSettings() {
            const rawXp = window.globalSettings && window.globalSettings.weekendRaidRewardXp != null ? window.globalSettings.weekendRaidRewardXp : 40;
            const rawBong = window.globalSettings && window.globalSettings.weekendRaidRewardBong != null ? window.globalSettings.weekendRaidRewardBong : 20;
            const xp = Math.max(0, Math.floor(Number(rawXp) || 0));
            const bong = normalizeBongValue(Math.max(0, Number(rawBong) || 0));
            return { xp, bong };
        }

        const DEFAULT_CONSTITUTION_ITEMS = [
            { id: 'c1', type: 'chapter', text: '제1장 강령' },
            { id: 'c1_a1', type: 'clause', text: '제1조 ① 삼봉월드는 추억과 사랑이다.' },
            { id: 'c1_a2', type: 'clause', text: '제1조 ② 삼봉월드의 주권은 학생들에게 있고, 모든 권력은 학생들로부터 나온다.' },
            { id: 'c1_a3', type: 'clause', text: '제2조 삼봉월드는 학생의 행복과 성장을 최우선 가치로 하며, 현실과 메타버스의 조화로운 통리를 지향한다.' },
            { id: 'c2', type: 'chapter', text: '제2장 학생의 권리와 의무' },
            { id: 'c2_a1', type: 'clause', text: '제3조 (평등권) 모든 학생은 삼봉월드 내에서 평등하며, 성별·성적·캐릭터 레벨·등급에 의해 차별받지 아니한다.' },
            { id: 'c2_a2', type: 'clause', text: '제4조 (자유권) 모든 학생은 타인에게 해를 끼치지 않는 범위 내에서 자신의 의견을 자유롭게 표현할 권리를 가진다.' },
            { id: 'c2_a3', type: 'clause', text: '제5조 (성장권) 모든 학생은 퀘스트와 학습을 통해 경험치(XP)를 쌓고 성장할 권리를 가지며, 학교는 이를 위한 평등한 기회를 제공해야 한다.' },
            { id: 'c2_a4', type: 'clause', text: '제6조 (납세 및 노동의 의무)' },
            { id: 'c2_a5', type: 'clause', text: '① 모든 학생은 할당된 직업(1인 1역)을 성실히 수행할 노동의 의무를 진다.' },
            { id: 'c2_a6', type: 'clause', text: "② 모든 학생은 법률이 정하는 바에 따라 공동체 유지 비용인 '봉(Bong)'을 세금으로 납부할 의무를 진다." },
            { id: 'c2_a7', type: 'clause', text: '제7조 (환경 보전의 의무) 모든 학생은 현실의 교실과 메타버스 공간을 청결하게 유지하고 보전해야 할 의무를 가진다.' },
            { id: 'c3', type: 'chapter', text: '제3장 자치 기구와 경제' },
            { id: 'c3_a1', type: 'clause', text: '제8조 (학급 회의: 입법) 삼봉월드의 주요 법규 수정 및 예산(봉) 사용은 삼봉월드 국회의원 회의에서 결정한다.' },
            { id: 'c3_a2', type: 'clause', text: '제9조 (은행 및 부동산: 경제)' },
            { id: 'c3_a3', type: 'clause', text: '① 모든 학생의 재산권(봉, 부동산 등)은 보장된다. 다만, 공공의 이익을 위해 필요한 경우 회의를 통해 제한할 수 있다.' },
            { id: 'c3_a4', type: 'clause', text: '② 은행은 화폐 가치를 유지하며, 저축한 자에 대해 정당한 이자를 지급해야 한다.' },
            { id: 'c3_a5', type: 'clause', text: "제10조 (사회적 보장) 캐릭터 등급이 낮거나 적응에 어려움을 겪는 학생을 위해 '초보자 지원 퀘스트' 등의 복지 제도를 운영한다." },
            { id: 'c4', type: 'chapter', text: '제4장 분쟁 조정 및 보칙' },
            { id: 'c4_a1', type: 'clause', text: '제11조 (재판) 학생 간의 다툼이나 법규 위반이 발생할 경우, 사법부를 통해 공정하게 판결하며, 교사는 최종적인 조언자의 역할을 수행한다.' },
            { id: 'c4_a2', type: 'clause', text: '제11조 ② 법관은 헌법과 법률에 의하여 그 양심에 따라 독립하여 심판한다.' },
            { id: 'c4_a3', type: 'clause', text: '제12조 (개정) 본 헌법의 개정은 교사와 국회 인원 3분의 2 이상의 찬성이 있어야 한다.' }
        ];

        let constitutionEditDraft = null;

        function escapeConstitutionHtml(value) {
            return String(value == null ? '' : value)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#39;');
        }

        function getConstitutionItems() {
            const saved = window.globalSettings && Array.isArray(window.globalSettings.constitutionItems)
                ? window.globalSettings.constitutionItems
                : null;
            const source = saved && saved.length > 0 ? saved : DEFAULT_CONSTITUTION_ITEMS;
            return source
                .map((item, idx) => ({
                    id: String(item && item.id ? item.id : `constitution_${idx}_${Date.now().toString(36)}`),
                    type: item && item.type === 'chapter' ? 'chapter' : 'clause',
                    text: brandLocalizedText(String(item && item.text ? item.text : '').trim())
                }))
                .filter((item) => item.text);
        }

        function renderConstitutionView(items) {
            const container = document.getElementById('constitutionViewContent');
            if (!container) return;
            let openArticle = false;
            const html = items.map((item) => {
                const safeText = escapeConstitutionHtml(item.text);
                if (item.type === 'chapter') {
                    const close = openArticle ? '</div></article>' : '';
                    openArticle = true;
                    return `${close}<article><h3 class="text-xl font-black text-amber-900 border-b-2 border-amber-800/30 pb-2 mb-3">${safeText}</h3><div class="space-y-3 text-sm sm:text-base font-medium">`;
                }
                return `<p>${safeText}</p>`;
            }).join('') + (openArticle ? '</div></article>' : '');
            container.innerHTML = html || '<div class="text-center text-amber-900/60 font-bold text-sm py-8">등록된 헌법 조문이 없습니다.</div>';
        }

        function renderConstitutionEditList() {
            const list = document.getElementById('constitutionEditList');
            if (!list) return;
            const draft = constitutionEditDraft || getConstitutionItems();
            list.innerHTML = draft.map((item, idx) => `
                <div class="rounded-2xl border border-amber-800/20 bg-white/55 p-3">
                    <div class="flex flex-col sm:flex-row gap-2">
                        <select id="constitution_type_${idx}" class="bg-stone-100 border border-amber-800/25 text-stone-900 px-2 py-2 rounded-xl text-xs font-black sm:w-28">
                            <option value="chapter" ${item.type === 'chapter' ? 'selected' : ''}>장 제목</option>
                            <option value="clause" ${item.type !== 'chapter' ? 'selected' : ''}>문장</option>
                        </select>
                        <textarea id="constitution_text_${idx}" rows="2" class="flex-1 bg-stone-50 border border-amber-800/25 text-stone-900 px-3 py-2 rounded-xl text-xs sm:text-sm font-bold leading-relaxed">${escapeConstitutionHtml(item.text)}</textarea>
                        <div class="grid grid-cols-3 sm:grid-cols-1 gap-1 sm:w-16">
                            <button type="button" onclick="window.moveConstitutionItem(${idx}, -1)" ${idx === 0 ? 'disabled' : ''} class="bg-stone-700 hover:bg-stone-600 disabled:opacity-30 disabled:pointer-events-none text-white font-black py-2 px-2 rounded-lg text-[10px]">위</button>
                            <button type="button" onclick="window.moveConstitutionItem(${idx}, 1)" ${idx === draft.length - 1 ? 'disabled' : ''} class="bg-stone-700 hover:bg-stone-600 disabled:opacity-30 disabled:pointer-events-none text-white font-black py-2 px-2 rounded-lg text-[10px]">아래</button>
                            <button type="button" onclick="window.deleteConstitutionItem(${idx})" class="bg-red-800 hover:bg-red-700 text-white font-black py-2 px-2 rounded-lg text-[10px]">삭제</button>
                        </div>
                    </div>
                </div>
            `).join('');
        }

        function collectConstitutionDraftFromDom() {
            const draft = constitutionEditDraft || getConstitutionItems();
            return draft.map((item, idx) => {
                const typeEl = document.getElementById(`constitution_type_${idx}`);
                const textEl = document.getElementById(`constitution_text_${idx}`);
                return {
                    id: item.id || `constitution_${Date.now().toString(36)}_${idx}`,
                    type: typeEl && typeEl.value === 'chapter' ? 'chapter' : 'clause',
                    text: textEl ? textEl.value.trim() : ''
                };
            }).filter((item) => item.text);
        }

        function isConstitutionEditorOpen() {
            const panel = document.getElementById('constitutionEditPanel');
            return !!(panel && !panel.classList.contains('hidden'));
        }

        window.renderConstitutionContent = function() {
            const editBtn = document.getElementById('constitutionEditBtn');
            const view = document.getElementById('constitutionViewContent');
            const panel = document.getElementById('constitutionEditPanel');
            if (!view || !panel) return;
            if (editBtn) editBtn.classList.toggle('hidden', !(window.playerState && window.playerState.isAdmin));
            if (!isConstitutionEditorOpen()) {
                renderConstitutionView(getConstitutionItems());
            }
        };

        window.toggleConstitutionEditor = function() {
            if (!window.playerState || !window.playerState.isAdmin) return window.customAlert('헌법 수정은 마스터만 할 수 있습니다.');
            const view = document.getElementById('constitutionViewContent');
            const panel = document.getElementById('constitutionEditPanel');
            if (!view || !panel) return;
            const opening = panel.classList.contains('hidden');
            if (opening) {
                constitutionEditDraft = getConstitutionItems();
                renderConstitutionEditList();
                view.classList.add('hidden');
                panel.classList.remove('hidden');
            } else {
                window.cancelConstitutionEditor();
            }
        };

        window.cancelConstitutionEditor = function() {
            constitutionEditDraft = null;
            const view = document.getElementById('constitutionViewContent');
            const panel = document.getElementById('constitutionEditPanel');
            if (view) view.classList.remove('hidden');
            if (panel) panel.classList.add('hidden');
            renderConstitutionView(getConstitutionItems());
        };

        window.addConstitutionItem = function() {
            if (!window.playerState || !window.playerState.isAdmin) return;
            constitutionEditDraft = collectConstitutionDraftFromDom();
            constitutionEditDraft.push({ id: `constitution_${Date.now().toString(36)}`, type: 'clause', text: '새 헌법 문장을 입력하세요.' });
            renderConstitutionEditList();
        };

        window.moveConstitutionItem = function(index, direction) {
            if (!window.playerState || !window.playerState.isAdmin) return;
            constitutionEditDraft = collectConstitutionDraftFromDom();
            const targetIndex = index + direction;
            if (targetIndex < 0 || targetIndex >= constitutionEditDraft.length) return;
            const [item] = constitutionEditDraft.splice(index, 1);
            constitutionEditDraft.splice(targetIndex, 0, item);
            renderConstitutionEditList();
        };

        window.deleteConstitutionItem = async function(index) {
            if (!window.playerState || !window.playerState.isAdmin) return;
            const ok = await window.customConfirm('이 헌법 문장을 삭제할까요?');
            if (!ok) return;
            constitutionEditDraft = collectConstitutionDraftFromDom().filter((_, idx) => idx !== index);
            renderConstitutionEditList();
        };

        window.saveConstitutionItems = async function() {
            if (!window.playerState || !window.playerState.isAdmin) return window.customAlert('헌법 수정은 마스터만 할 수 있습니다.');
            const constitutionItems = collectConstitutionDraftFromDom();
            if (constitutionItems.length === 0) return window.customAlert('헌법 문장을 1개 이상 남겨 주세요.');
            try {
                const authOk = await ensureAnonAuthReady();
                if (!authOk) return await window.customAlert('인증에 실패했습니다. 새로고침 후 다시 시도해 주세요.');
                await setDoc(doc(db, 'artifacts', appId, 'public', 'data', 'settings', 'global'), { constitutionItems }, { merge: true });
                window.globalSettings.constitutionItems = constitutionItems;
                window.cancelConstitutionEditor();
                await window.customAlert('✅ 헌법이 저장되었습니다.');
            } catch (e) {
                console.error(e);
                await window.customAlert('저장 중 오류가 발생했습니다.');
            }
        };

        /** Firestore settings.global.shopPrices 우선, 없으면 SHOP_DATA 기본가 */
        function getEffectiveShopPrice(shopId) {
            const sp = window.globalSettings && window.globalSettings.shopPrices;
            if (sp && sp[shopId] != null && Number.isFinite(Number(sp[shopId])) && Number(sp[shopId]) >= 0) {
                return Math.round(Number(sp[shopId]) * 10) / 10;
            }
            return getDefaultShopPrice(shopId);
        }

        /** 플레이어 총 XP가 낮을수록 1에 가깝게 — 퀘스트 무기 드랍 보정 등에 사용 */
        function getLowXpBoostFactor(xp) {
            const x = Math.max(0, Number(xp) || 0);
            return Math.max(0, Math.min(1, 1 - x / 30000));
        }

        function getXpWeaponDropFactor(xp) {
            const x = Math.max(0, Number(xp) || 0);
            if (x < 10000) return 1.8;
            if (x < 20000) return 1.35;
            if (x < 30000) return 1.0;
            if (x < 50000) return 0.65;
            return 0.4;
        }

        /** 상점 카드에 표시되는 가격 라벨 갱신(마스터 가격 변경 반영) */
        function updateShopPriceLabels() {
            getAllShopItems().forEach((shop) => {
                const el = document.getElementById(`shop-price-${shop.id}`);
                if (el) el.textContent = `${formatBongAmount(getEffectiveShopPrice(shop.id))}`;
            });
        }

        /** XP 동기화 힌트(학생용, 알림 스팸 방지) */
        function showXpSyncHintFromServer(delta) {
            if (window.playerState && window.playerState.isAdmin) return;
            const el = document.getElementById('xpSyncHint');
            if (!el) return;
            el.textContent = `서버에서 XP가 +${delta} 반영됐어요. (수업 자동 지급·다른 기기·퀘스트 저장 등)`;
            el.classList.remove('hidden');
            clearTimeout(window._xpSyncHintTimer);
            window._xpSyncHintTimer = setTimeout(() => el.classList.add('hidden'), 10000);
        }

        function buildShopCardHtml(shop) {
            const safeName = String(shop.name).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
            const icon = shop.icon || (shop.isConsumable ? 'fa-bolt' : 'fa-ticket');
            const iconColor = shop.iconColor || (shop.isConsumable ? 'text-amber-300' : 'text-cyan-300');
            const groupBuyBtn =
                shop.id === 'item_mystery_dice' || shop.id === LOTTO_SHOP_ID
                    ? ''
                    : `<button type="button" class="flex-1 min-w-[4.5rem] bg-cyan-900/80 hover:bg-cyan-800 text-cyan-100 text-[10px] font-bold py-2 px-2 rounded-lg border border-cyan-600" onclick="event.stopPropagation();window.openShopGroupBuyModal('${shop.id}')">공동구매</button>`;
            return `
                <div id="shop-btn-${shop.id}" class="shop-btn bg-slate-800/80 p-3 rounded-xl border-2 flex flex-col gap-2 unaffordable">
                    <div class="flex items-center gap-3">
                        <div class="bg-slate-900 w-10 h-10 rounded-full flex items-center justify-center ${iconColor} shadow-inner shrink-0">
                            <i class="fa-solid ${icon}"></i>
                        </div>
                        <div class="flex-grow min-w-0">
                            <div class="font-bold text-sm">${shop.name}</div>
                            <div class="text-[10px] text-slate-400">${shop.desc}</div>
                        </div>
                        <div id="shop-price-${shop.id}" class="text-sb-gold bg-slate-900 px-3 py-1 rounded border border-slate-700 text-xs font-bold shrink-0">${formatBongAmount(shop.price)}</div>
                    </div>
                    <div class="flex flex-wrap gap-2">
                        <button type="button" class="flex-1 min-w-[4.5rem] bg-pink-900/70 hover:bg-pink-800 text-white text-[10px] font-bold py-2 px-2 rounded-lg border border-pink-600" onclick="event.stopPropagation();window.buyItem('${shop.id}','${safeName}',${shop.isConsumable || false})">구매</button>
                        ${groupBuyBtn}
                    </div>
                </div>`;
        }

        window.currentRaidState = { 
            status: 'waiting', participants: [], bossHP: BASE_BOSS_HP, maxBossHP: BASE_BOSS_HP, 
            currentTurn: 0, startTime: 0, combo: 0, logs: [], questions: [] 
        };
        
        window.raidTimerInterval = null; 
        let isWeekend = false; 
        window.dragonBallState = null;
        window.goldenbellState = null;
        window.masterQuizState = null;
        let selectedEmotion = null; 
        let selectedBody = null;

        function calculateExactLevel(xp) { return Math.min(100, Math.max(1, Math.floor(1 + Math.sqrt((xp || 0) / 4.04)))); }

        /** 봉(B) 값을 정수로 맞춤 — 소수 발생 시 버림(floor) */
        function normalizeBongValue(v) {
            const n = Number(v);
            if (!Number.isFinite(n)) return 0;
            return Math.floor(n);
        }

        /** 퀘스트 보상 삼봉 — 정수 체계에서 반올림(0.5B → 1B, 5.5B → 6B) */
        function normalizeQuestBongReward(v) {
            const n = Number(v);
            if (!Number.isFinite(n) || n <= 0) return 0;
            return Math.max(0, Math.round(n));
        }

        /** UI 표시용 삼봉 숫자 문자열 */
        function formatBongDisplay(v) {
            return String(normalizeBongValue(v));
        }

        /** UI 표시용 금액+화폐단위 (예: 10B, 10미소) */
        function formatBongAmount(v) {
            return `${formatBongDisplay(v)}${getCurrencyUnit()}`;
        }
        window.formatBongAmount = formatBongAmount;

        /** UI — 부족 화폐 안내 */
        function formatInsufficientBongAlert(shortfall) {
            const need = formatBongAmount(Math.max(0, Number(shortfall) || 0));
            return `❌ 돈이 부족해요. ${need}가 더 필요해요.`;
        }

        /** 착용 중인 구매 스킨 환불 비율 — 목록가의 50% */
        const EQUIPPED_ITEM_REFUND_RATE = 0.5;
        const BONG_CHANGE_LOG_LIMIT = 80;
        /** 삼봉 금융감독 — 하루 정상 획득 상한을 크게 넘으면 경고 */
        const BONG_ANOMALY_DAILY_GAIN_WARN = 200;
        /** 삼봉 금융감독 — 보유 삼봉이 이 값을 넘으면 경고 */
        const BONG_ANOMALY_TOTAL_HOLD_WARN = 500;
        /** 삼봉 금융감독 — 단일 기록에서 이 이상 증가하면 경고 */
        const BONG_ANOMALY_SINGLE_DELTA_WARN = 120;
        /** 삼봉 금융감독 — 아이템 환불 누적 의심 기준 */
        const BONG_SUPERVISION_REFUND_WARN = 8;
        /** 금융감독 집계에서 제외할 bongChangeLog source (정상 은행·적금 흐름) */
        const BONG_SUPERVISION_EXCLUDED_SOURCES = new Set(['bankTermMaturity', 'bankTermEarly']);

        function isBankTermDepositBongSupervisionExcluded(row) {
            if (!row || typeof row !== 'object') return false;
            if (row.source && BONG_SUPERVISION_EXCLUDED_SOURCES.has(String(row.source))) return true;
            const reason = String(row.reason || '');
            return /보물상자 적금 만기|적금 만기|보물상자 적금 중도 해지/.test(reason);
        }

        function formatSupervisionDateTime(ms) {
            const d = new Date(Number(ms));
            if (isNaN(d.getTime())) return '날짜 미상';
            return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
        }

        /** 학생 1명의 금융감독 이상 거래 목록 (날짜·행위 포함) */
        function buildStudentSupervisionIncidents(stu, today) {
            if (!stu) return [];
            const incidents = [];
            const totalBong = normalizeBongValue(Number(stu.bong) || 0);
            const logs = Array.isArray(stu.bongChangeLog) ? stu.bongChangeLog : [];
            const ledger = Array.isArray(stu.itemRefundLedger) ? stu.itemRefundLedger : [];

            if (totalBong >= BONG_ANOMALY_TOTAL_HOLD_WARN) {
                incidents.push({
                    id: `hold_${today}_${totalBong}`,
                    date: today,
                    dateLabel: today,
                    category: '과다 보유',
                    action: `보유 삼봉 ${formatBongAmount(totalBong)} (기준 ${formatBongAmount(BONG_ANOMALY_TOTAL_HOLD_WARN)} 초과)`,
                });
            }

            let todayGain = 0;
            const todayGainRows = [];
            logs.forEach((row) => {
                if (!row || !row.at) return;
                if (isBankTermDepositBongSupervisionExcluded(row)) return;
                const ds = getLocalDateStr(new Date(Number(row.at)));
                if (ds !== today) return;
                const delta = normalizeBongValue(Number(row.delta) || 0);
                if (delta > 0) {
                    todayGain = normalizeBongValue(todayGain + delta);
                    todayGainRows.push(row);
                }
            });
            if (todayGain >= BONG_ANOMALY_DAILY_GAIN_WARN) {
                incidents.push({
                    id: `daily_${today}_${todayGain}`,
                    date: today,
                    dateLabel: today,
                    category: '과다 일일 획득',
                    action: `당일 누적 +${formatBongAmount(todayGain)} (기준 ${formatBongAmount(BONG_ANOMALY_DAILY_GAIN_WARN)} 초과)`,
                    details: todayGainRows.slice(-8).map((row) => ({
                        dateLabel: formatSupervisionDateTime(row.at),
                        action: `${row.reason || '봉 변경'} (+${formatBongAmount(row.delta)})`,
                    })),
                });
            }

            logs.forEach((row, idx) => {
                if (isBankTermDepositBongSupervisionExcluded(row)) return;
                const delta = normalizeBongValue(Number(row && row.delta) || 0);
                if (delta < BONG_ANOMALY_SINGLE_DELTA_WARN) return;
                incidents.push({
                    id: `single_${row.at || idx}_${delta}`,
                    date: row.at ? getLocalDateStr(new Date(Number(row.at))) : today,
                    dateLabel: formatSupervisionDateTime(row.at),
                    category: '단일 대량 증가',
                    action: `${row.reason || '봉 변경'} — 단일 +${formatBongAmount(delta)} (기준 ${formatBongAmount(BONG_ANOMALY_SINGLE_DELTA_WARN)} 초과)`,
                });
            });

            if (ledger.length >= BONG_SUPERVISION_REFUND_WARN) {
                const recentRefunds = ledger.slice(-5);
                incidents.push({
                    id: `refund_${ledger.length}`,
                    date: today,
                    dateLabel: recentRefunds.length ? formatSupervisionDateTime(recentRefunds[recentRefunds.length - 1].at) : today,
                    category: '환불 누적',
                    action: `아이템 환불 ${ledger.length}회 누적 (기준 ${BONG_SUPERVISION_REFUND_WARN}회 이상)`,
                    details: recentRefunds.map((row) => ({
                        dateLabel: formatSupervisionDateTime(row.at),
                        action: `${row.label || row.kind || '환불'} +${formatBongAmount(row.refundB)}`,
                    })),
                });
            }

            return incidents;
        }

        function buildSupervisionIncidentSummaryLine(inc) {
            return `[${inc.dateLabel}] ${inc.category}: ${inc.action}`;
        }

        function buildSupervisionIncidentHtml(inc) {
            const detailHtml = Array.isArray(inc.details) && inc.details.length
                ? `<ul class="list-disc list-inside ml-2 mt-0.5 text-[8px] sm:text-[9px] text-slate-400 space-y-0.5">${inc.details.map((d) =>
                    `<li><span class="text-slate-500">${escapeConvenienceHtml(d.dateLabel)}</span> · ${escapeConvenienceHtml(d.action)}</li>`
                ).join('')}</ul>`
                : '';
            return `<li class="text-amber-100/90">
                <span class="text-amber-300/90 font-bold">${escapeConvenienceHtml(inc.dateLabel)}</span>
                <span class="text-amber-200"> ${escapeConvenienceHtml(inc.category)}</span> —
                ${escapeConvenienceHtml(inc.action)}
                ${detailHtml}
            </li>`;
        }

        function buildBongChangeLogEntry(reason, beforeBong, afterBong, extra = {}) {
            const before = normalizeBongValue(Number(beforeBong) || 0);
            const after = normalizeBongValue(Number(afterBong) || 0);
            return {
                at: Date.now(),
                reason: String(reason || '봉 변경'),
                before,
                after,
                delta: normalizeBongValue(after - before),
                ...extra,
            };
        }

        function getMaxSkinRefundBong() {
            let max = 0;
            SKIN_DATA.forEach((skin) => {
                max = Math.max(max, getEquippedSkinRefundBong(skin));
            });
            return normalizeBongValue(max);
        }

        /** 서버 문서 기준 스킨 환불 패치 (미보유·미장착이면 예외) */
        function buildSkinRefundServerPatch(data, skinId) {
            const skin = SKIN_DATA.find((s) => s.id === skinId);
            const ownedSkins = { ...(data.ownedSkins || {}) };
            const equippedSkins = { ...(data.equippedSkins || {}) };
            const ownedSkinInstances = { ...(data.ownedSkinInstances || {}) };
            if (!ownedSkins[skinId] || !equippedSkins[skinId]) throw new Error('not_equipped');
            const instanceId = ownedSkinInstances[skinId] || `legacy_${skinId}`;
            delete ownedSkins[skinId];
            delete equippedSkins[skinId];
            delete ownedSkinInstances[skinId];
            if (skin && (skin.type === 'aura' || skin.type === 'face')) {
                SKIN_DATA.forEach((s) => {
                    if (s.type === skin.type) delete equippedSkins[s.id];
                });
            }
            return { ownedSkins, equippedSkins, ownedSkinInstances, instanceId };
        }

        /**
         * 장착 스킨 환불 — Firestore 트랜잭션으로 1회만 처리 (로컬 선반영·중복 클릭 방지)
         */
        async function executeEquippedItemRefund({ kind, itemId, label, refundB }) {
            if (!db || !currentStudentDocRef) throw new Error('no_db');
            if (kind !== 'skin') throw new Error('bad_kind');
            const authOk = await ensureAnonAuthReady();
            if (!authOk) throw new Error('auth');
            const amount = normalizeBongValue(Number(refundB) || 0);
            const maxRefund = getMaxSkinRefundBong();
            if (amount <= 0 || amount > maxRefund + 0.001) throw new Error('invalid_refund_amount');

            const refundId = `rf_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
            let synced = null;

            await runTransaction(db, async (transaction) => {
                const snap = await transaction.get(currentStudentDocRef);
                if (!snap.exists()) throw new Error('not_found');
                const data = snap.data() || {};
                const ledger = Array.isArray(data.itemRefundLedger) ? data.itemRefundLedger.slice() : [];
                if (ledger.some((row) => row && row.refundId === refundId)) throw new Error('duplicate_refund');

                const refundGate = canRefundSkinThisSeason(data, getLocalDateStr());
                if (!refundGate.ok) throw new Error(refundGate.reason === 'season' ? 'season_refund_cap' : 'day_refund_cap');

                const built = buildSkinRefundServerPatch(data, itemId);
                const itemPatch = {
                    ownedSkins: built.ownedSkins,
                    equippedSkins: built.equippedSkins,
                    ownedSkinInstances: built.ownedSkinInstances,
                };

                const serverBong = normalizeBongValue(Number(data.bong) || 0);
                const nextBong = normalizeBongValue(serverBong + amount);
                const bongLogs = Array.isArray(data.bongChangeLog) ? data.bongChangeLog.slice(-BONG_CHANGE_LOG_LIMIT + 1) : [];
                bongLogs.push(buildBongChangeLogEntry(`${label} 환불`, serverBong, nextBong, { kind, itemId, refundId, source: 'itemRefund' }));

                ledger.push({
                    refundId,
                    kind,
                    itemId,
                    instanceId: built.instanceId || null,
                    refundB: amount,
                    at: Date.now(),
                    label: label || '',
                });

                const seasonCount = Math.max(0, Math.floor(Number(data.seasonSkinRefundCount) || 0)) + 1;
                transaction.set(currentStudentDocRef, {
                    ...itemPatch,
                    bong: increment(amount),
                    itemRefundLedger: ledger.slice(-60),
                    bongChangeLog: bongLogs,
                    seasonSkinRefundCount: seasonCount,
                    lastSkinRefundDate: getLocalDateStr(),
                }, { merge: true });

                synced = { nextBong, itemPatch, ledgerEntry: ledger[ledger.length - 1], bongLog: bongLogs[bongLogs.length - 1], seasonSkinRefundCount: seasonCount };
            });

            return synced;
        }

        function syncLocalStateAfterItemRefund({ kind, itemId, synced }) {
            if (!synced || !window.playerState) return;
            window.playerState.bong = synced.nextBong;
            if (kind === 'skin') {
                purgeRefundedSkinCompletely(itemId);
                if (synced.itemPatch.ownedSkinInstances) {
                    window.playerState.ownedSkinInstances = { ...(synced.itemPatch.ownedSkinInstances) };
                }
            }
            if (!Array.isArray(window.playerState.itemRefundLedger)) window.playerState.itemRefundLedger = [];
            window.playerState.itemRefundLedger.push(synced.ledgerEntry);
            window.playerState.itemRefundLedger = window.playerState.itemRefundLedger.slice(-60);
            if (!Array.isArray(window.playerState.bongChangeLog)) window.playerState.bongChangeLog = [];
            window.playerState.bongChangeLog.push(synced.bongLog);
            window.playerState.bongChangeLog = window.playerState.bongChangeLog.slice(-BONG_CHANGE_LOG_LIMIT);
            if (synced.seasonSkinRefundCount != null) {
                window.playerState.seasonSkinRefundCount = synced.seasonSkinRefundCount;
            }
        }

        function getStudentBongGainToday(bongChangeLog, gameDateStr) {
            const logs = Array.isArray(bongChangeLog) ? bongChangeLog : [];
            let gain = 0;
            logs.forEach((row) => {
                if (!row || !row.at) return;
                if (isBankTermDepositBongSupervisionExcluded(row)) return;
                const d = new Date(Number(row.at));
                if (isNaN(d.getTime())) return;
                const ds = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
                if (ds !== gameDateStr) return;
                const delta = normalizeBongValue(Number(row.delta) || 0);
                if (delta > 0) gain = normalizeBongValue(gain + delta);
            });
            return gain;
        }

        function buildBongAnomalyReport(studentsData) {
            const today = getLocalDateStr();
            const rows = Array.isArray(studentsData) ? studentsData : [];
            const alerts = [];
            rows.forEach((stu) => {
                const sid = String(stu && stu.id || '');
                if (!sid || sid === 'gm' || sid === 'gm_a' || sid === 'guest') return;
                const name = STUDENT_NAMES[sid] || stu.name || sid;
                const incidents = buildStudentSupervisionIncidents(stu, today);
                if (!incidents.length) return;
                const totalBong = normalizeBongValue(Number(stu.bong) || 0);
                const todayGain = getStudentBongGainToday(stu.bongChangeLog, today);
                const refundCount = Array.isArray(stu.itemRefundLedger) ? stu.itemRefundLedger.length : 0;
                alerts.push({
                    sid,
                    name,
                    totalBong,
                    todayGain,
                    refundCount,
                    incidents,
                    reasons: incidents.map(buildSupervisionIncidentSummaryLine),
                });
            });
            alerts.sort((a, b) => b.totalBong - a.totalBong);
            return { today, alerts, alertCount: alerts.length };
        }

        /** 삼봉 금융감독 — 마스터 J 패널 */
        function renderSamBongFinancialSupervisionPanel(studentsData) {
            const el = document.getElementById('bongAnomalyPanel');
            if (!el) return;
            if (!window.playerState || !window.playerState.isGM) {
                el.classList.add('hidden');
                return;
            }
            el.classList.remove('hidden');
            const report = buildBongAnomalyReport(studentsData);
            const criteriaText = `보유 ${formatBongAmount(BONG_ANOMALY_TOTAL_HOLD_WARN)}↑ · 당일 +${formatBongAmount(BONG_ANOMALY_DAILY_GAIN_WARN)}↑ · 단일 +${formatBongAmount(BONG_ANOMALY_SINGLE_DELTA_WARN)}↑ · 환불 ${BONG_SUPERVISION_REFUND_WARN}회↑`;
            if (!report.alertCount) {
                el.innerHTML = `
                    <div class="flex items-center gap-2 mb-1">
                        <h3 class="text-white font-bold text-sm"><i class="fa-solid fa-building-columns text-emerald-400"></i> 삼봉 금융감독 시스템</h3>
                        <span class="text-[9px] text-emerald-300 font-bold">이상 없음</span>
                    </div>
                    <p class="text-[9px] text-slate-500 leading-relaxed">학급 ${getCurrencyUnit()} 거래를 실시간 감시합니다. ${criteriaText} 시 경고·기록됩니다.</p>`;
                return;
            }
            const rowsHtml = report.alerts.map((a) => `
                <div class="rounded-lg border border-amber-600/40 bg-amber-950/20 px-2 py-1.5 text-[9px] sm:text-[10px]">
                    <div class="font-bold text-amber-100">${escapeConvenienceHtml(a.name)} <span class="text-slate-400">(${escapeConvenienceHtml(a.sid)}번)</span></div>
                    <div class="text-amber-200/90 mt-0.5">보유 ${formatBongAmount(a.totalBong)} · 오늘 +${formatBongAmount(a.todayGain)} · 환불 ${a.refundCount}회</div>
                    <ul class="list-none mt-1 space-y-1">${a.incidents.map(buildSupervisionIncidentHtml).join('')}</ul>
                </div>`).join('');
            el.innerHTML = `
                <div class="flex flex-wrap items-center gap-2 mb-2">
                    <h3 class="text-white font-bold text-sm"><i class="fa-solid fa-building-columns text-amber-400"></i> 삼봉 금융감독 시스템</h3>
                    <span class="text-[9px] bg-amber-900/60 text-amber-100 px-2 py-0.5 rounded-full font-bold">${report.alertCount}명 감독 대상</span>
                    <button type="button" onclick="window.renderSamBongFinancialSupervisionPanel(window.allStudentsData)" class="ml-auto text-[9px] bg-slate-800 hover:bg-slate-700 text-white px-2 py-1 rounded border border-slate-600">새로고침</button>
                </div>
                <p class="text-[9px] text-slate-500 mb-2 leading-relaxed">비정상 보유·과다 획득·대량 환불 등 의심 거래를 날짜·행위와 함께 표시합니다. 당사자에게도 경고 알림이 전달됩니다.</p>
                <div class="space-y-2 max-h-52 overflow-y-auto scrollbar-hide">${rowsHtml}</div>`;
        }

        window.renderSamBongFinancialSupervisionPanel = renderSamBongFinancialSupervisionPanel;
        window.renderBongAnomalyPanel = renderSamBongFinancialSupervisionPanel;

        function buildXpAnomalyReport(studentsData) {
            const today = getLocalDateStr();
            const pace = expectedXpPace(today);
            const rows = Array.isArray(studentsData) ? studentsData : [];
            const alerts = [];
            rows.forEach((stu) => {
                const sid = String((stu && stu.id) || '');
                if (!sid || sid === 'gm' || sid === 'gm_a' || sid === 'guest') return;
                const incidents = buildXpSupervisionIncidents(stu, today, pace);
                if (!incidents.length) return;
                alerts.push({
                    sid,
                    name: STUDENT_NAMES[sid] || stu.name || sid,
                    xp: Math.max(0, Math.floor(Number(stu.xp) || 0)),
                    incidents,
                });
            });
            alerts.sort((a, b) => b.xp - a.xp);
            return { today, pace, alerts, alertCount: alerts.length };
        }

        function renderXpSupervisionPanel(studentsData) {
            const el = document.getElementById('xpAnomalyPanel');
            if (!el) return;
            if (!window.playerState || !window.playerState.isGM) {
                el.classList.add('hidden');
                return;
            }
            el.classList.remove('hidden');
            const report = buildXpAnomalyReport(studentsData);
            const criteriaText = `당일 +${XP_ANOMALY_DAILY_GAIN_WARN} XP↑ · 단일 +${XP_ANOMALY_SINGLE_DELTA_WARN} XP↑ · 예상 페이스+${XP_ANOMALY_AHEAD_OF_PACE_WARN.toLocaleString()} XP↑`;
            if (!report.alertCount) {
                el.innerHTML = `
                    <div class="flex items-center gap-2 mb-1">
                        <h3 class="text-white font-bold text-sm"><i class="fa-solid fa-shield-halved text-sky-400"></i> 경험치 감시 시스템</h3>
                        <span class="text-[9px] text-emerald-300 font-bold">이상 없음</span>
                    </div>
                    <p class="text-[9px] text-slate-500 leading-relaxed">퀘스트·상점·로그 XP를 감시합니다. 오늘 예상 페이스 ${report.pace.toLocaleString()} XP. ${criteriaText} 시 경고됩니다.</p>`;
                return;
            }
            const rowsHtml = report.alerts.map((a) => `
                <div class="rounded-lg border border-sky-600/40 bg-sky-950/20 px-2 py-1.5 text-[9px] sm:text-[10px]">
                    <div class="font-bold text-sky-100">${escapeConvenienceHtml(a.name)} <span class="text-slate-400">(${escapeConvenienceHtml(a.sid)}번)</span> · ${a.xp.toLocaleString()} XP</div>
                    <ul class="list-none mt-1 space-y-1">${a.incidents.map(buildSupervisionIncidentHtml).join('')}</ul>
                </div>`).join('');
            el.innerHTML = `
                <div class="flex flex-wrap items-center gap-2 mb-2">
                    <h3 class="text-white font-bold text-sm"><i class="fa-solid fa-shield-halved text-sky-300"></i> 경험치 감시 시스템</h3>
                    <span class="text-[9px] bg-sky-900/60 text-sky-100 px-2 py-0.5 rounded-full font-bold">${report.alertCount}명 감독 대상</span>
                    <button type="button" onclick="window.renderXpSupervisionPanel(window.allStudentsData)" class="ml-auto text-[9px] bg-slate-800 hover:bg-slate-700 text-white px-2 py-1 rounded border border-slate-600">새로고침</button>
                </div>
                <p class="text-[9px] text-slate-500 mb-2 leading-relaxed">비정상 급등·과다 일일 획득을 날짜·행위와 함께 표시합니다. 당사자에게도 경고가 갑니다.</p>
                <div class="space-y-2 max-h-52 overflow-y-auto scrollbar-hide">${rowsHtml}</div>`;
        }
        window.renderXpSupervisionPanel = renderXpSupervisionPanel;

        let _xpSupervisionStudentAlertRunning = false;
        async function maybeAlertStudentXpSupervision() {
            if (_xpSupervisionStudentAlertRunning) return;
            if (!window.playerState || window.playerState.isGuest || window.playerState.isAdmin) return;
            const sid = String(localStorage.getItem('sambong_student_id') || '');
            if (!sid) return;
            const today = getLocalDateStr();
            const incidents = buildXpSupervisionIncidents(window.playerState, today, expectedXpPace(today));
            if (!incidents.length) return;
            const storageKey = `sambong_xp_supervision_seen_${sid}`;
            let seen = {};
            try { seen = JSON.parse(localStorage.getItem(storageKey) || '{}'); } catch (e) { seen = {}; }
            const newOnes = incidents.filter((inc) => !seen[inc.id]);
            if (!newOnes.length) return;
            _xpSupervisionStudentAlertRunning = true;
            try {
                const lines = newOnes.map((inc) => `· ${buildSupervisionIncidentSummaryLine(inc)}`).join('\n');
                await window.customAlert(
                    '⚠️ 경험치 감시 경고\n\n' +
                    '허용되지 않은 방법으로 경험치가 급증한 것으로 보입니다.\n' +
                    `${getMasterDisplayName()}가 확인할 수 있습니다.\n\n` +
                    '[감지 내역]\n' + lines
                );
                newOnes.forEach((inc) => { seen[inc.id] = Date.now(); });
                localStorage.setItem(storageKey, JSON.stringify(seen));
            } finally {
                _xpSupervisionStudentAlertRunning = false;
            }
        }
        window.maybeAlertStudentXpSupervision = maybeAlertStudentXpSupervision;

        let _supervisionStudentAlertRunning = false;

        /** 삼봉 금융감독 — 이상 감지 시 당사자에게 1회 경고 알림 */
        async function maybeAlertStudentBongSupervision() {
            if (_supervisionStudentAlertRunning) return;
            if (!window.playerState || window.playerState.isGuest || window.playerState.isAdmin) return;
            const sid = String(localStorage.getItem('sambong_student_id') || '');
            if (!sid) return;
            const today = getLocalDateStr();
            const incidents = buildStudentSupervisionIncidents(window.playerState, today);
            if (!incidents.length) return;

            const storageKey = `sambong_supervision_seen_${sid}`;
            let seen = {};
            try {
                seen = JSON.parse(localStorage.getItem(storageKey) || '{}');
            } catch (e) {
                seen = {};
            }
            const newOnes = incidents.filter((inc) => !seen[inc.id]);
            if (!newOnes.length) return;

            _supervisionStudentAlertRunning = true;
            try {
                const lines = newOnes.map((inc) => {
                    let block = `· ${buildSupervisionIncidentSummaryLine(inc)}`;
                    if (inc.details && inc.details.length) {
                        block += '\n' + inc.details.slice(0, 4).map((d) => `   ↳ ${d.dateLabel} ${d.action}`).join('\n');
                    }
                    return block;
                }).join('\n\n');
                await window.customAlert(
                    '⚠️ 삼봉 금융감독 경고\n\n' +
                    '비정상으로 의심되는 ${getCurrencyUnit()} 거래가 감지되었습니다.\n' +
                    `허용되지 않은 방법으로 획득·환불한 경우 ${getMasterDisplayName()}가 확인할 수 있습니다.\n\n` +
                    '[감지 내역]\n' +
                    lines +
                    `\n\n정상 활동이라면 ${getMasterDisplayName()}에게 문의하세요.`
                );
                newOnes.forEach((inc) => { seen[inc.id] = Date.now(); });
                localStorage.setItem(storageKey, JSON.stringify(seen));
            } finally {
                _supervisionStudentAlertRunning = false;
            }
        }
        window.maybeAlertStudentBongSupervision = maybeAlertStudentBongSupervision;

        function getEquippedSkinRefundBong(skin) {
            const price = Math.max(0, Number(skin && skin.price) || 0);
            return normalizeBongValue(price * EQUIPPED_ITEM_REFUND_RATE);
        }

        /** 스킨 환불 시 보유·장착(얼굴/오버레이/테두리 오라) 데이터를 완전히 제거 */
        function purgeRefundedSkinCompletely(skinId) {
            const skin = SKIN_DATA.find((s) => s.id === skinId);
            if (!window.playerState.ownedSkins) window.playerState.ownedSkins = {};
            if (!window.playerState.equippedSkins) window.playerState.equippedSkins = {};

            delete window.playerState.ownedSkins[skinId];
            delete window.playerState.equippedSkins[skinId];

            if (skin && (skin.type === 'aura' || skin.type === 'face')) {
                SKIN_DATA.forEach((s) => {
                    if (s.type === skin.type) delete window.playerState.equippedSkins[s.id];
                });
            }

            [window.playerState.equippedSkins, window.playerState.ownedSkins].forEach((map) => {
                Object.keys(map).forEach((key) => {
                    if (!map[key]) delete map[key];
                });
            });
        }

        /** 퀘스트 기록이 남아 있다면 XP 숫자 필드는 최소한 기록 합계보다 낮아지면 안 됩니다. */
        function getQuestHistoryXpFloor(state) {
            const history = Array.isArray(state && state.questHistory) ? state.questHistory : [];
            return history.reduce((sum, q) => {
                const xp = Number(q && q.xp);
                return sum + (Number.isFinite(xp) && xp > 0 ? Math.floor(xp) : 0);
            }, 0);
        }

        /** 학생 자가 저장·Firestore 규칙과 맞춘 1회 XP 상승 상한(퀘스트·일일보너스·무기버프 여유) */
        const STUDENT_MAX_XP_INCREASE_PER_SAVE = 650;
        const XP_CHANGE_LOG_LIMIT = 40;

        function buildXpChangeLogEntry(reason, beforeXp, afterXp, extra = {}) {
            const before = Math.max(0, Math.floor(Number(beforeXp) || 0));
            const after = Math.max(0, Math.floor(Number(afterXp) || 0));
            return {
                at: Date.now(),
                reason: String(reason || 'XP 변경'),
                before,
                after,
                delta: after - before,
                ...extra,
            };
        }

        /** 마스터가 학생 XP/B를 직접 설정한 뒤 광장·관리자 표를 즉시 맞춤 */
        async function adminSetStudentStat(stuId, type, val) {
            const sid = String(stuId);
            const ref = doc(db, 'artifacts', appId, 'public', 'data', 'students', 'student_' + sid);
            let stu = null;
            try {
                const snap = await readStudentDocPreferServer(ref);
                if (snap.exists()) stu = snap.data() || {};
            } catch (e) {
                console.warn('adminSetStudentStat read', e);
            }
            if (!stu && window.allStudentsData && window.allStudentsData.length) {
                const row = window.allStudentsData.find((s) => String(s.id) === sid);
                if (row) stu = { ...row };
            }
            const payload = type === 'bong'
                ? { bong: normalizeBongValue(val) }
                : { xp: Math.max(0, Math.floor(Number(val) || 0)) };
            if (type === 'xp') {
                const beforeXp = Math.max(0, Math.floor(Number(stu && stu.xp) || 0));
                payload.xpChangeLog = arrayUnion(buildXpChangeLogEntry('마스터 직접 XP 수정', beforeXp, payload.xp, { actor: window.playerState?.isGM ? 'gm' : 'admin' }));
            }
            await setDoc(ref, payload, { merge: true });
            mergeStudentDocIntoPlazaCache(sid, { ...(stu || {}), ...payload });
            if (typeof redrawPlazaGrantsUi === 'function') redrawPlazaGrantsUi();
            if (window.allStudentsData && window.allStudentsData.length) {
                const row = window.allStudentsData.find((s) => String(s.id) === sid);
                if (row) {
                    if (type === 'bong') row.bong = payload.bong;
                    else row.xp = payload.xp;
                }
            }
            if (window.renderAdminTable && window.allStudentsData) window.renderAdminTable(window.allStudentsData);
        }

        /** 골든벨·스피드 퀴즈 공통: 앞뒤 공백 제거, 연속 공백 축소, 영문 소문자 통일 */
        function normalizeQuizAnswer(s) {
            if (s == null || s === undefined) return '';
            return String(s).trim().replace(/\s+/g, ' ').toLowerCase();
        }

        async function sha256Hex(text) {
            const normalized = String(text == null ? '' : text);
            if (window.crypto && window.crypto.subtle && window.TextEncoder) {
                const buf = await window.crypto.subtle.digest('SHA-256', new TextEncoder().encode(normalized));
                return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
            }
            let h = 2166136261;
            for (let i = 0; i < normalized.length; i++) {
                h ^= normalized.charCodeAt(i);
                h = Math.imul(h, 16777619);
            }
            return `fallback-${(h >>> 0).toString(16)}`;
        }

        async function hashGoldenBellAnswer(answer, salt) {
            return sha256Hex(`${salt || ''}::${normalizeQuizAnswer(answer)}`);
        }

        /** 로컬 기준 오늘 날짜 YYYY-MM-DD */
        function getLocalDateStr(d = new Date()) {
            return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
        }

        /** 랜덤 박스·미스테리 박스 1인 1일 구매 상한(각각) */
        const SHOP_DAILY_PURCHASE_LIMIT = 3;
        const CUSTOM_XP_DAILY_KEY = 'custom_xp';
        const SHOP_DAILY_ITEM_LIMITS = {
            item_random: SHOP_DAILY_PURCHASE_LIMIT,
            item_mystery_dice: SHOP_DAILY_PURCHASE_LIMIT,
            item_xp_pack: XP_PACK_DAILY_LIMIT,
            [CUSTOM_XP_DAILY_KEY]: CUSTOM_SHOP_XP_DAILY_LIMIT,
        };
        const SHOP_DAILY_LIMIT_ITEM_IDS = Object.keys(SHOP_DAILY_ITEM_LIMITS);

        /** 날짜가 바뀌면 상점 일일 구매 횟수 초기화 */
        function ensureShopDailyPurchaseCounts(state) {
            if (!state) return false;
            const today = getLocalDateStr();
            const cur = state.shopDailyPurchase;
            if (!cur || cur.date !== today) {
                state.shopDailyPurchase = { date: today, item_random: 0, item_mystery_dice: 0, item_xp_pack: 0, custom_xp: 0 };
                return true;
            }
            return false;
        }

        function getShopDailyPurchaseUsed(state, itemId) {
            if (!state || state.isAdmin) return 0;
            ensureShopDailyPurchaseCounts(state);
            const n = state.shopDailyPurchase && state.shopDailyPurchase[itemId];
            return Math.max(0, Math.floor(Number(n) || 0));
        }

        function getShopItemDailyLimit(itemId) {
            return Math.max(0, Math.floor(Number(SHOP_DAILY_ITEM_LIMITS[itemId]) || 0));
        }

        function getShopDailyPurchaseRemaining(state, itemId) {
            const cap = getShopItemDailyLimit(itemId) || SHOP_DAILY_PURCHASE_LIMIT;
            if (!state || state.isAdmin) return cap;
            return Math.max(0, cap - getShopDailyPurchaseUsed(state, itemId));
        }

        function canShopItemBePurchasedToday(state, itemId) {
            if (!SHOP_DAILY_LIMIT_ITEM_IDS.includes(itemId)) return true;
            if (!state || state.isAdmin || state.isGuest) return true;
            return getShopDailyPurchaseRemaining(state, itemId) > 0;
        }

        function incrementShopDailyPurchase(state, itemId) {
            if (!state || state.isAdmin || !SHOP_DAILY_LIMIT_ITEM_IDS.includes(itemId)) return;
            ensureShopDailyPurchaseCounts(state);
            const cur = state.shopDailyPurchase[itemId] || 0;
            state.shopDailyPurchase[itemId] = cur + 1;
        }

        const LOTTO_SHOP_ID = 'item_lotto';
        const LOTTO_PICK_MIN = 1;
        const LOTTO_PICK_MAX = 30;
        const LOTTO_PICK_COUNT = 3;
        const LOTTO_TAX_RATE = 0.4;

        /** 월요일 날짜를 회차 키로 사용합니다. */
        function getLottoRoundKey(d = new Date()) {
            const x = new Date(d.getFullYear(), d.getMonth(), d.getDate());
            const day = x.getDay();
            const diff = day === 0 ? -6 : 1 - day;
            x.setDate(x.getDate() + diff);
            return getLocalDateStr(x);
        }

        /** 월~목 전체, 금요일은 점심 전까지만 구매 가능 */
        function isLottoPurchaseOpen(d = new Date()) {
            const day = d.getDay();
            if (day < 1 || day > 5) return false;
            return !(day === 5 && d.getHours() >= 12);
        }

        function getLottoPurchaseWindowText(d = new Date()) {
            const day = d.getDay();
            if (day === 5 && d.getHours() >= 12) return '이번 주 구매 마감(금요일 점심 이후)';
            if (day < 1 || day > 5) return '주말 구매 불가';
            return '구매 가능(금요일 점심 전까지)';
        }

        function normalizeLottoNumbers(raw) {
            const nums = String(raw || '')
                .split(/[^0-9]+/)
                .filter(Boolean)
                .map((n) => parseInt(n, 10))
                .filter((n) => Number.isInteger(n));
            const uniq = Array.from(new Set(nums)).sort((a, b) => a - b);
            if (
                uniq.length !== LOTTO_PICK_COUNT ||
                uniq.some((n) => n < LOTTO_PICK_MIN || n > LOTTO_PICK_MAX)
            ) {
                return null;
            }
            return uniq;
        }

        function formatLottoNumbers(nums) {
            return (Array.isArray(nums) ? nums : []).map((n) => String(n).padStart(2, '0')).join(' · ');
        }

        function lottoNumbersKey(nums) {
            return (Array.isArray(nums) ? nums : []).slice().sort((a, b) => a - b).join(',');
        }

        function drawRandomLottoNumbers() {
            return shuffleInPlace(Array.from({ length: LOTTO_PICK_MAX }, (_, i) => i + 1))
                .slice(0, LOTTO_PICK_COUNT)
                .sort((a, b) => a - b);
        }

        function isLottoAutoDrawTime(d = new Date()) {
            return d.getDay() === 5 && (d.getHours() > 13 || (d.getHours() === 13 && d.getMinutes() >= 5));
        }

        function getLottoDrawSeenKey(lastDraw) {
            if (!lastDraw || !lastDraw.drawnAt) return '';
            return `sambong_seen_lotto_draw_${String(lastDraw.roundKey || '')}_${String(lastDraw.drawnAt)}`;
        }

        function buildLottoResultMessage(lastDraw) {
            if (!lastDraw) return '';
            const winners = Array.isArray(lastDraw.winners) ? lastDraw.winners : [];
            const poolB = normalizeBongValue(Number(lastDraw.poolB) || 0);
            const taxB = normalizeBongValue(Number(lastDraw.taxB) || 0);
            const winnerText = winners.length
                ? winners.map((w) => `${w.name || w.studentId}: +${formatBongAmount(w.payoutB || 0)}`).join('\n')
                : `당첨자 없음\n${formatBongAmount(poolB)}는 다음 회차로 이월됩니다.`;
            return `🎟️ 삼봉 로또 추첨 결과\n번호: ${formatLottoNumbers(lastDraw.numbers)}\n` +
                `누적: ${formatBongAmount(poolB)} / 세금(40%): ${formatBongAmount(taxB)}\n\n${winnerText}`;
        }

        function maybeShowLottoResultPopup() {
            if (!window.playerState || window.playerState.isGuest) return;
            const state = getCurrentLottoDisplayState();
            const lastDraw = state.lastDraw;
            const seenKey = getLottoDrawSeenKey(lastDraw);
            if (!seenKey) return;
            if (localStorage.getItem(seenKey) === '1') return;
            localStorage.setItem(seenKey, '1');
            setTimeout(() => {
                void window.customAlert(buildLottoResultMessage(lastDraw));
            }, 250);
        }

        function getSanitizedLottoState(raw) {
            const src = raw && typeof raw === 'object' ? raw : {};
            const tickets = Array.isArray(src.tickets) ? src.tickets : [];
            return {
                roundKey: src.roundKey ? String(src.roundKey) : getLottoRoundKey(),
                poolB: normalizeBongValue(Math.max(0, Number(src.poolB) || 0)),
                carryoverB: normalizeBongValue(Math.max(0, Number(src.carryoverB) || 0)),
                tickets: tickets.filter((t) => t && t.ticketId && Array.isArray(t.numbers)).slice(-300),
                drawnAt: src.drawnAt || null,
                lastDraw: src.lastDraw || null,
                lastAutoDrawKey: src.lastAutoDrawKey || '',
                updatedAt: src.updatedAt || 0,
            };
        }

        function getCurrentLottoDisplayState() {
            return getSanitizedLottoState(window.globalSettings && window.globalSettings.lotto);
        }

        function buildLottoStateForPurchase(raw, now = new Date()) {
            const state = getSanitizedLottoState(raw);
            const roundKey = getLottoRoundKey(now);
            if (state.roundKey !== roundKey) {
                return {
                    roundKey,
                    poolB: state.carryoverB,
                    carryoverB: 0,
                    tickets: [],
                    drawnAt: null,
                    lastDraw: state.lastDraw || null,
                    lastAutoDrawKey: state.lastAutoDrawKey || '',
                    updatedAt: Date.now(),
                };
            }
            return state;
        }

        function renderLottoPanel() {
            const el = document.getElementById('lottoPanel');
            if (!el) return;
            if (!window.playerState || window.playerState.isGuest) {
                el.innerHTML = '';
                el.classList.add('hidden');
                return;
            }
            const state = getCurrentLottoDisplayState();
            const currentRoundKey = getLottoRoundKey();
            const sameRound = state.roundKey === currentRoundKey;
            const activePool = sameRound && !state.drawnAt ? state.poolB : state.carryoverB;
            const ticketCount = sameRound && !state.drawnAt ? state.tickets.length : 0;
            const price = getEffectiveShopPrice(LOTTO_SHOP_ID);
            const mine = Array.isArray(window.playerState.lottoTickets) ? window.playerState.lottoTickets : [];
            const myRows = mine.slice(-6).reverse().map((t) => {
                const d = t.at ? new Date(t.at) : null;
                const ds = d && !isNaN(d.getTime()) ? `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}` : '';
                return `<div class="flex justify-between gap-2 border-b border-slate-800/70 pb-1">
                    <span class="text-lime-200 font-bold">${formatLottoNumbers(t.numbers)}</span>
                    <span class="text-slate-500 shrink-0">${ds} · ${formatBongAmount(t.price || price)}</span>
                </div>`;
            }).join('');
            const last = state.lastDraw;
            const lastHtml = last
                ? `<div class="mt-2 rounded-lg bg-slate-950/60 border border-slate-700 px-2 py-1.5">
                    <div class="text-[10px] text-slate-400 font-bold">최근 추첨: <span class="text-lime-200">${formatLottoNumbers(last.numbers)}</span></div>
                    <div class="text-[9px] text-slate-500">총 ${formatBongAmount(last.poolB || 0)} · 세금 ${formatBongAmount(last.taxB || 0)} · 지급 ${formatBongAmount(last.payoutPoolB || 0)}</div>
                    <div class="text-[9px] text-slate-400">${last.winners && last.winners.length ? `당첨: ${last.winners.map((w) => escapeConstitutionHtml(w.name || w.studentId)).join(', ')}` : '당첨자 없음 · 당첨금 이월'}</div>
                </div>`
                : '';
            const adminBtn = window.playerState.isGM
                ? `<button type="button" onclick="window.drawLottoAdmin()" class="mt-2 w-full sm:w-auto bg-lime-700 hover:bg-lime-600 text-white font-bold py-2 px-4 rounded-xl text-[10px]"><i class="fa-solid fa-wand-magic-sparkles"></i> 로또 추첨</button>`
                : '';
            el.innerHTML = `
                <div class="flex flex-col sm:flex-row sm:items-start justify-between gap-2">
                    <div>
                        <h4 class="text-lime-300 font-black text-xs"><i class="fa-solid fa-ticket"></i> 삼봉 로또</h4>
                        <p class="text-[9px] text-slate-400 leading-relaxed">1~30 중 3개를 고릅니다. ${getLottoPurchaseWindowText()} · 가격 ${formatBongAmount(price)} · 당첨 시 세금 40% 제외 후 지급</p>
                    </div>
                    <div class="text-right text-[10px] text-slate-300 shrink-0">
                        <div>누적: <span class="text-sb-gold font-black">${formatBongAmount(activePool || 0)}</span></div>
                        <div>이번 회차 티켓: ${ticketCount}장</div>
                    </div>
                </div>
                ${adminBtn}
                ${lastHtml}
                <div class="mt-3 pt-2 border-t border-slate-700/70">
                    <div class="text-[10px] text-slate-500 font-bold mb-1">내 최근 구매 이력</div>
                    <div class="space-y-1">${myRows || '<div class="text-[9px] text-slate-600">아직 구매한 복권이 없습니다.</div>'}</div>
                </div>`;
            el.classList.remove('hidden');
        }

        // ==========================================
        // ★ 월드컵 승부예측 (대한민국 32강 진출) ★
        // ==========================================
        const WORLD_CUP_MATCH = {
            id: 'kr_r32_2026',
            title: '대한민국 32강 진출 예측',
        };

        /** 분석 확률 (표시용) · 배당은 북메이커 마진 적용 */
        const WORLD_CUP_HOUSE_MARGIN = 0.15;

        /** 확률 기반 배당에 마진을 더해, 단일·전체 베팅 모두 기대값이 손해가 되게 조정 */
        function computeWorldCupOdds(prob) {
            const adjusted = Math.min(0.95, Number(prob) * (1 + WORLD_CUP_HOUSE_MARGIN));
            return Math.max(1.05, Math.round((1 / adjusted) * 100) / 100);
        }

        const WORLD_CUP_ODDS = {
            r32: {
                advance: { label: '32강 진출', prob: 0.38, odds: computeWorldCupOdds(0.38) },
                eliminate: { label: '탈락', prob: 0.62, odds: computeWorldCupOdds(0.62) },
            },
        };

        const WORLD_CUP_MARKET_LABELS = {
            r32: '32강 진출',
        };

        const WORLD_CUP_MARKET_ORDER = ['r32'];

        /** 1회 베팅 최대 금액 */
        const WORLD_CUP_MAX_STAKE = 300;

        /** 베팅 자동 마감: 2026-06-28(일) 오전 10:00 (로컬 시간) */
        const WORLD_CUP_BETTING_CLOSE_AT_MS = new Date(2026, 5, 28, 10, 0, 0, 0).getTime();

        function isWorldCupBettingPastDeadline(now = new Date()) {
            return now.getTime() >= WORLD_CUP_BETTING_CLOSE_AT_MS;
        }

        function formatWorldCupBettingDeadlineLabel() {
            const d = new Date(WORLD_CUP_BETTING_CLOSE_AT_MS);
            const dow = ['일', '월', '화', '수', '목', '금', '토'][d.getDay()];
            return `${d.getMonth() + 1}/${d.getDate()}(${dow}) ${String(d.getHours()).padStart(2, '0')}:00`;
        }

        function formatWorldCupBetTime(ms) {
            if (!ms) return '';
            const d = new Date(Number(ms));
            if (isNaN(d.getTime())) return '';
            return `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
        }

        function formatWorldCupBetStatusHtml(bet) {
            if (!bet) return '';
            if (bet.status === 'won') {
                return `<span class="text-emerald-300">적중 +${formatBongAmount(bet.payout || 0)}</span>`;
            }
            if (bet.status === 'lost') return '<span class="text-slate-500">미적중</span>';
            if (bet.status === 'cancelled') return '<span class="text-slate-400">취소·환불</span>';
            return '<span class="text-amber-300">대기</span>';
        }

        /** 승무패 · 언오버 · 선제골 항목별로 베팅 내역 HTML 생성 */
        function buildWorldCupBetHistoryGroupedHtml(bets, { showStudent = false, emptyText = '베팅 내역이 없습니다.' } = {}) {
            const list = Array.isArray(bets) ? bets : [];
            if (!list.length) {
                return `<div class="text-[9px] text-slate-600 py-2 text-center border border-dashed border-slate-700 rounded-lg">${emptyText}</div>`;
            }
            const grouped = { r32: [] };
            list.forEach((bet) => {
                if (bet && grouped[bet.market]) grouped[bet.market].push(bet);
            });
            WORLD_CUP_MARKET_ORDER.forEach((market) => {
                grouped[market].sort((a, b) => (Number(b.at) || 0) - (Number(a.at) || 0));
            });
            const sections = WORLD_CUP_MARKET_ORDER.map((market) => {
                const rows = grouped[market];
                if (!rows.length) return '';
                const summary = getWorldCupBetHistorySummary(rows);
                const rowHtml = rows.map((b) => buildWorldCupBetRowHtml(b, { showStudent })).join('');
                return `<div class="rounded-lg border border-slate-700/80 bg-slate-950/40 p-2 mb-2">
                    <div class="text-[10px] font-bold text-red-200 mb-1.5 flex flex-wrap items-center justify-between gap-1">
                        <span>${WORLD_CUP_MARKET_LABELS[market]}</span>
                        <span class="text-[9px] text-slate-500 font-normal">${rows.length}건 · 대기 ${summary.pending} · ${formatBongAmount(summary.totalStake)}</span>
                    </div>
                    <div class="space-y-1">${rowHtml}</div>
                </div>`;
            }).filter(Boolean);
            return sections.join('') || `<div class="text-[9px] text-slate-600 py-2 text-center border border-dashed border-slate-700 rounded-lg">${emptyText}</div>`;
        }

        function buildWorldCupBetRowHtml(bet, { showStudent = false } = {}) {
            if (!bet) return '';
            const studentPart = showStudent
                ? `<span class="text-sky-200 font-bold shrink-0">${escapeConvenienceHtml(bet.studentName || bet.studentId || '?')} <span class="text-slate-500 font-normal">(${escapeConvenienceHtml(bet.studentId)}번)</span></span>`
                : '';
            return `<div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1 border-b border-slate-800/70 pb-1">
                <div class="min-w-0 flex flex-wrap items-center gap-x-2 gap-y-0.5 text-[9px] sm:text-[10px]">
                    ${studentPart}
                    <span class="text-slate-500 shrink-0">${formatWorldCupBetTime(bet.at)}</span>
                    <span class="text-red-100">${WORLD_CUP_MARKET_LABELS[bet.market] || bet.market} · ${escapeConvenienceHtml(getWorldCupPickLabel(bet.market, bet.pick))} · ${formatBongAmount(bet.stake || 0)} × ${Number(bet.odds || 0).toFixed(2)}</span>
                </div>
                <span class="shrink-0 text-[9px] sm:text-[10px]">${formatWorldCupBetStatusHtml(bet)}</span>
            </div>`;
        }

        /** 학급 전체 학생의 이번 경기 베팅 내역 (최신순) */
        function getAllClassWorldCupBets() {
            const rows = Array.isArray(window.allStudentsData) ? window.allStudentsData : [];
            const all = [];
            rows.forEach((stu) => {
                const sid = String(stu && stu.id || '');
                if (!sid || sid === 'gm' || sid === 'gm_a') return;
                const name = STUDENT_NAMES[sid] || stu.name || sid;
                const bets = Array.isArray(stu.worldCupBets) ? stu.worldCupBets : [];
                bets.forEach((bet) => {
                    if (!bet || String(bet.matchId) !== WORLD_CUP_MATCH.id) return;
                    all.push({
                        ...bet,
                        studentId: sid,
                        studentName: bet.studentName || name,
                    });
                });
            });
            return all.sort((a, b) => (Number(b.at) || 0) - (Number(a.at) || 0));
        }

        function getWorldCupBetHistorySummary(bets) {
            const list = Array.isArray(bets) ? bets : [];
            const pending = list.filter((b) => b && b.status === 'pending').length;
            const won = list.filter((b) => b && b.status === 'won').length;
            const totalStake = normalizeBongValue(list.reduce((sum, b) => sum + (Number(b && b.stake) || 0), 0));
            return { count: list.length, pending, won, totalStake };
        }

        function getSanitizedWorldCupBetState(raw) {
            const base = {
                matchId: WORLD_CUP_MATCH.id,
                bettingOpen: !isWorldCupBettingPastDeadline(),
                settled: false,
                result: null,
                settledAt: null,
                bettingDeadlineMs: WORLD_CUP_BETTING_CLOSE_AT_MS,
            };
            if (!raw || typeof raw !== 'object') return base;
            if (raw.matchId && String(raw.matchId) !== WORLD_CUP_MATCH.id) return base;
            const result = raw.result && typeof raw.result === 'object' ? raw.result : null;
            const adminOpen = raw.bettingOpen !== false;
            const timeOpen = !isWorldCupBettingPastDeadline();
            return {
                matchId: WORLD_CUP_MATCH.id,
                bettingOpen: raw.settled ? false : (adminOpen && timeOpen),
                settled: !!raw.settled,
                result: result ? {
                    r32: result.r32 ? String(result.r32) : null,
                } : null,
                settledAt: raw.settledAt || null,
                bettingDeadlineMs: WORLD_CUP_BETTING_CLOSE_AT_MS,
            };
        }

        function getWorldCupBetState() {
            return getSanitizedWorldCupBetState(window.globalSettings && window.globalSettings.worldCupBet);
        }

        function getWorldCupOddsEntry(market, pick) {
            const table = WORLD_CUP_ODDS[market];
            if (!table || !table[pick]) return null;
            return table[pick];
        }

        function getWorldCupPickLabel(market, pick) {
            const entry = getWorldCupOddsEntry(market, pick);
            return entry ? entry.label : String(pick || '');
        }

        let _worldCupAdminResultDraft = { r32: '' };

        function sanitizeWorldCupResultValue(market, value) {
            const table = WORLD_CUP_ODDS[market];
            const key = String(value || '');
            return table && table[key] ? key : '';
        }

        function getWorldCupAdminResultValue(market, state) {
            return sanitizeWorldCupResultValue(market, _worldCupAdminResultDraft[market])
                || sanitizeWorldCupResultValue(market, state && state.result && state.result[market]);
        }

        function buildWorldCupAdminResultOptionsHtml(market, state) {
            const table = WORLD_CUP_ODDS[market] || {};
            const selected = getWorldCupAdminResultValue(market, state);
            const placeholder = `<option value="" ${selected ? '' : 'selected'} disabled>결과 선택</option>`;
            return placeholder + Object.keys(table).map((pick) => {
                const entry = table[pick];
                return `<option value="${escapeHtmlAttr(pick)}" ${selected === pick ? 'selected' : ''}>${escapeConvenienceHtml(entry.label)}</option>`;
            }).join('');
        }

        function readWorldCupAdminResultFromForm() {
            const r32 = sanitizeWorldCupResultValue('r32', document.getElementById('wcAdminR32')?.value)
                || sanitizeWorldCupResultValue('r32', _worldCupAdminResultDraft.r32);
            if (!r32) return null;
            return { r32 };
        }

        window.updateWorldCupAdminResultDraft = function(market, value) {
            if (!Object.prototype.hasOwnProperty.call(_worldCupAdminResultDraft, market)) return;
            _worldCupAdminResultDraft[market] = sanitizeWorldCupResultValue(market, value);
        };

        function getMyWorldCupBets() {
            const list = window.playerState && Array.isArray(window.playerState.worldCupBets)
                ? window.playerState.worldCupBets
                : [];
            return list.filter((b) => b && String(b.matchId) === WORLD_CUP_MATCH.id);
        }

        function buildWorldCupBetButton(market, pick, disabled) {
            const entry = getWorldCupOddsEntry(market, pick);
            if (!entry) return '';
            const probPct = Math.round(entry.prob * 100);
            return `
                <button type="button" ${disabled ? 'disabled' : ''} onclick="window.placeWorldCupBet('${market}', '${pick}')"
                    class="text-left rounded-lg border border-red-500/30 bg-slate-950/70 px-2 py-1.5 hover:bg-red-950/40 transition ${disabled ? 'opacity-50 cursor-not-allowed' : ''}">
                    <div class="text-[10px] text-white font-bold">${entry.label}</div>
                    <div class="text-[9px] text-red-200/80">분석 ${probPct}% · 배당 ${entry.odds.toFixed(2)}x</div>
                </button>`;
        }

        function renderWorldCupBetPanel() {
            const el = document.getElementById('worldCupBetPanel');
            if (!el) return;
            if (!window.playerState || window.playerState.isGuest) {
                el.innerHTML = '';
                el.classList.add('hidden');
                return;
            }
            const state = getWorldCupBetState();
            const canBet = state.bettingOpen && !state.settled;
            const statusText = state.settled
                ? '정산 완료'
                : (state.bettingOpen ? '베팅 접수 중' : '베팅 마감');
            const statusClass = state.settled ? 'text-emerald-300' : (state.bettingOpen ? 'text-red-300' : 'text-amber-300');
            const myBets = getMyWorldCupBets().slice().reverse();
            const myBetRows = buildWorldCupBetHistoryGroupedHtml(myBets, { emptyText: '아직 베팅한 내역이 없습니다.' });
            const classBets = getAllClassWorldCupBets();
            const classSummary = getWorldCupBetHistorySummary(classBets);
            const classBetPreview = buildWorldCupBetHistoryGroupedHtml(classBets.slice(0, 30), { showStudent: true, emptyText: '아직 학급 베팅 내역이 없습니다.' });
            const classHistoryHtml = `
                <div class="mt-3 pt-2 border-t border-slate-700/70">
                    <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 mb-1">
                        <div>
                            <div class="text-[10px] text-slate-300 font-bold">학급 베팅 내역</div>
                            <div class="text-[9px] text-slate-500">총 ${classSummary.count}건 · 대기 ${classSummary.pending} · 적중 ${classSummary.won} · 누적 ${formatBongAmount(classSummary.totalStake)}</div>
                        </div>
                        <button type="button" onclick="window.openWorldCupBetHistoryPanel()" class="shrink-0 bg-slate-800 hover:bg-slate-700 text-white border border-slate-600 font-bold py-1.5 px-3 rounded-lg text-[9px]">전체 보기</button>
                    </div>
                    <div class="max-h-52 overflow-y-auto scrollbar-hide pr-1">
                        ${classBetPreview}
                    </div>
                </div>`;
            const resultHtml = state.settled && state.result
                ? `<div class="mt-2 rounded-lg bg-emerald-950/40 border border-emerald-500/30 px-2 py-1.5 text-[10px] text-emerald-100">
                    <div class="font-bold mb-1">경기 결과</div>
                    <div>32강 진출: ${getWorldCupPickLabel('r32', state.result.r32)}</div>
                </div>`
                : '';
            const adminR32Options = buildWorldCupAdminResultOptionsHtml('r32', state);
            const adminHtml = window.playerState.isGM ? `
                <div class="mt-3 pt-3 border-t border-red-500/30 rounded-xl bg-red-950/20 p-2">
                    <div class="text-[10px] text-red-200 font-bold mb-2"><i class="fa-solid fa-flag-checkered"></i> 마스터 · 승부예측 관리</div>
                    <div class="mb-2">
                        <label class="text-[9px] text-slate-400">32강 진출 결과
                            <select id="wcAdminR32" onchange="window.updateWorldCupAdminResultDraft('r32', this.value)" class="mt-1 w-full bg-slate-900 border border-slate-600 text-white px-2 py-1 rounded text-xs font-bold">
                                ${adminR32Options}
                            </select>
                        </label>
                    </div>
                    <div class="flex flex-col sm:flex-row gap-2 flex-wrap">
                        <button type="button" onclick="window.toggleWorldCupBettingAdmin(false)" class="flex-1 min-w-[7rem] bg-amber-800 hover:bg-amber-700 text-white font-bold py-2 px-3 rounded-xl text-[10px]">베팅 마감</button>
                        <button type="button" onclick="window.toggleWorldCupBettingAdmin(true)" class="flex-1 min-w-[7rem] bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-3 rounded-xl text-[10px]">베팅 재개</button>
                        <button type="button" onclick="window.cancelAllWorldCupBetsAdmin()" class="flex-1 min-w-[7rem] bg-rose-900 hover:bg-rose-800 text-white font-bold py-2 px-3 rounded-xl text-[10px]">전체 취소·환불</button>
                        <button type="button" onclick="window.settleWorldCupBetAdmin()" class="flex-1 min-w-[7rem] bg-emerald-700 hover:bg-emerald-600 text-white font-bold py-2 px-3 rounded-xl text-[10px]">결과 확정·배당 지급</button>
                    </div>
                </div>` : '';
            el.innerHTML = `
                <div class="flex flex-col sm:flex-row sm:items-start justify-between gap-2">
                    <div>
                        <h4 class="text-red-300 font-black text-xs"><i class="fa-solid fa-futbol"></i> 월드컵 승부예측 · ${WORLD_CUP_MATCH.title}</h4>
                        <p class="text-[9px] text-slate-400 leading-relaxed mt-1">${getCurrencyUnit()}으로 32강 진출·탈락 중 1건만 베팅 (최대 ${formatBongAmount(WORLD_CUP_MAX_STAKE)}). <span class="text-amber-300/90">베팅 마감: ${formatWorldCupBettingDeadlineLabel()} (자동)</span>. 배당은 북메이커 마진이 적용되어 <span class="text-amber-300/90">장기적으로는 무조건 손해</span>입니다 — 실제 불법 도박도 이렇게 돈을 뺏깁니다. <span class="text-sb-gold">재미로만!</span></p>
                    </div>
                    <div class="text-right text-[10px] shrink-0 ${statusClass} font-bold">${statusText}</div>
                </div>
                ${resultHtml}
                <div class="mt-3">
                    <div class="text-[10px] text-red-200 font-bold mb-1">32강 진출 예측 <span class="text-slate-500 font-normal">(진출 38% · 탈락 62%)</span></div>
                    <div class="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
                        ${buildWorldCupBetButton('r32', 'advance', !canBet || hasPendingWorldCupBetOnMarket('r32'))}
                        ${buildWorldCupBetButton('r32', 'eliminate', !canBet || hasPendingWorldCupBetOnMarket('r32'))}
                    </div>
                </div>
                ${adminHtml}
                <div class="mt-3 pt-2 border-t border-slate-700/70">
                    <div class="text-[10px] text-slate-500 font-bold mb-1">내 베팅 내역</div>
                    <div class="max-h-44 overflow-y-auto scrollbar-hide pr-1">${myBetRows}</div>
                </div>
                ${classHistoryHtml}`;
            el.classList.remove('hidden');
        }

        function ensureWorldCupBetHistoryModal() {
            let modal = document.getElementById('worldCupBetHistoryModal');
            if (modal) return modal;
            modal = document.createElement('div');
            modal.id = 'worldCupBetHistoryModal';
            modal.className = 'hidden fixed inset-0 z-[270] bg-black/80 backdrop-blur-sm flex items-center justify-center px-3 py-6';
            modal.innerHTML = `
                <div class="w-full max-w-lg bg-slate-900 border border-red-500/50 rounded-2xl shadow-2xl p-4 max-h-[85vh] flex flex-col">
                    <div class="flex items-center justify-between gap-3 mb-3 border-b border-slate-700 pb-3 shrink-0">
                        <h3 class="text-lg font-display text-red-100"><i class="fa-solid fa-list text-red-300"></i> 학급 승부예측 내역</h3>
                        <button type="button" onclick="window.closeWorldCupBetHistoryPanel()" class="text-slate-400 hover:text-white text-xs font-bold">닫기</button>
                    </div>
                    <div id="worldCupBetHistoryModalBody" class="overflow-y-auto scrollbar-hide pr-1 flex-1"></div>
                </div>`;
            document.body.appendChild(modal);
            return modal;
        }

        function renderWorldCupBetHistoryModalBody() {
            const body = document.getElementById('worldCupBetHistoryModalBody');
            if (!body) return;
            const classBets = getAllClassWorldCupBets();
            const summary = getWorldCupBetHistorySummary(classBets);
            body.innerHTML = `
                <div class="text-[10px] text-slate-400 mb-3 rounded-lg bg-slate-950/70 border border-slate-700 px-2 py-1.5">
                    ${WORLD_CUP_MATCH.title} · 총 ${summary.count}건 · 대기 ${summary.pending} · 적중 ${summary.won} · 베팅 합계 ${formatBongAmount(summary.totalStake)}
                </div>
                ${buildWorldCupBetHistoryGroupedHtml(classBets, { showStudent: true })}`;
        }

        window.openWorldCupBetHistoryPanel = function() {
            if (!window.playerState || window.playerState.isGuest) {
                return window.customAlert('👀 게스트는 이용할 수 없어요.');
            }
            const modal = ensureWorldCupBetHistoryModal();
            renderWorldCupBetHistoryModalBody();
            modal.classList.remove('hidden');
        };

        window.closeWorldCupBetHistoryPanel = function() {
            const modal = document.getElementById('worldCupBetHistoryModal');
            if (modal) modal.classList.add('hidden');
        };

        window.placeWorldCupBet = async function(market, pick) {
            if (window.playerState.isGuest) return await window.customAlert('👀 게스트는 이용할 수 없어요.');
            if (!db || !currentStudentDocRef) return await window.customAlert('서버 연결 후 다시 시도해 주세요.');
            const entry = getWorldCupOddsEntry(market, pick);
            if (!entry) return await window.customAlert('선택한 베팅 항목을 찾을 수 없습니다.');
            const wcState = getWorldCupBetState();
            if (!wcState.bettingOpen || wcState.settled) {
                if (isWorldCupBettingPastDeadline() && !wcState.settled) {
                    return await window.customAlert(`베팅 접수가 ${formatWorldCupBettingDeadlineLabel()}에 자동 마감되었습니다.`);
                }
                return await window.customAlert('지금은 승부예측 베팅 접수 시간이 아닙니다.');
            }
            const hasPendingOnMarket = getMyWorldCupBets().some((b) => b && b.market === market && b.status === 'pending');
            if (hasPendingOnMarket) {
                return await window.customAlert(
                    `이미 [${WORLD_CUP_MARKET_LABELS[market]}] 항목에 베팅한 내역이 있습니다.\n\n` +
                    '같은 항목에 두 군데 이상 걸어 손실을 막는 보험베팅은 할 수 없어요.\n' +
                    '(실제 도박 사이트도 이런 식으로 수익을 보장할 수 없습니다.)'
                );
            }
            const balance = normalizeBongValue(Number(window.playerState.bong) || 0);
            const maxStake = Math.min(WORLD_CUP_MAX_STAKE, balance);
            const rawStake = await window.customPrompt(
                `[${WORLD_CUP_MARKET_LABELS[market]}] ${entry.label}\n배당 ${entry.odds.toFixed(2)}x · 분석 ${Math.round(entry.prob * 100)}%\n\n베팅할 ${getCurrencyUnit()} 금액을 입력하세요.\n(최소 1${getCurrencyUnit()} · 최대 ${formatBongAmount(maxStake)})`,
                'number'
            );
            if (rawStake === null) return;
            const stake = normalizeBongValue(Number(rawStake));
            if (!Number.isFinite(stake) || stake < 1) return await window.customAlert('1${getCurrencyUnit()} 이상 숫자로 입력해 주세요.');
            if (stake > WORLD_CUP_MAX_STAKE) return await window.customAlert(`1회 최대 ${formatBongAmount(WORLD_CUP_MAX_STAKE)}까지 베팅할 수 있습니다.`);
            if (!window.playerState.isAdmin && balance + 0.0001 < stake) {
                return await window.customAlert(formatInsufficientBongAlert(stake - balance));
            }
            const potential = normalizeBongValue(stake * entry.odds);
            const ok = await window.customConfirm(
                `승부예측 베팅을 확정할까요?\n` +
                `- 경기: ${WORLD_CUP_MATCH.title}\n` +
                `- 항목: ${WORLD_CUP_MARKET_LABELS[market]} · ${entry.label}\n` +
                `- 베팅: ${formatBongAmount(stake)} × ${entry.odds.toFixed(2)}배\n` +
                `- 적중 시 예상 수령: ${formatBongAmount(potential)}`
            );
            if (!ok) return;
            const authOk = await ensureAnonAuthReady();
            if (!authOk) return await window.customAlert('인증에 실패했습니다. 새로고침 후 다시 시도해 주세요.');
            const studentId = String(localStorage.getItem('sambong_student_id') || '');
            const studentName = window.playerState.isAdmin
                ? (window.playerState.isGM ? getMasterDisplayName() : getCoMasterDisplayName())
                : (STUDENT_NAMES[studentId] || studentId);
            const betId = `wc_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
            let nextBong = balance;
            try {
                await runTransaction(db, async (transaction) => {
                    const settingsRef = getGlobalSettingsDocRef();
                    const settingsSnap = await transaction.get(settingsRef);
                    const latestWc = getSanitizedWorldCupBetState(settingsSnap.exists() ? settingsSnap.data().worldCupBet : null);
                    if (!latestWc.bettingOpen || latestWc.settled || isWorldCupBettingPastDeadline()) throw new Error('closed');
                    const stuSnap = await transaction.get(currentStudentDocRef);
                    if (!stuSnap.exists()) throw new Error('student_not_found');
                    const serverData = stuSnap.data() || {};
                    const serverBong = normalizeBongValue(Number(serverData.bong) || 0);
                    if (!window.playerState.isAdmin && serverBong + 0.0001 < stake) throw new Error('insufficient');
                    nextBong = window.playerState.isAdmin ? serverBong : normalizeBongValue(serverBong - stake);
                    const bets = Array.isArray(serverData.worldCupBets) ? serverData.worldCupBets.slice() : [];
                    const hasDuplicate = bets.some((b) => b && String(b.matchId) === WORLD_CUP_MATCH.id && b.market === market && b.status === 'pending');
                    if (hasDuplicate) throw new Error('duplicate_market');
                    bets.push({
                        id: betId,
                        matchId: WORLD_CUP_MATCH.id,
                        market,
                        pick,
                        label: entry.label,
                        stake,
                        odds: entry.odds,
                        studentId,
                        studentName,
                        at: Date.now(),
                        status: 'pending',
                        payout: 0,
                    });
                    transaction.set(currentStudentDocRef, {
                        bong: nextBong,
                        worldCupBets: bets.slice(-40),
                    }, { merge: true });
                });
                window.playerState.bong = nextBong;
                if (!Array.isArray(window.playerState.worldCupBets)) window.playerState.worldCupBets = [];
                window.playerState.worldCupBets.push({
                    id: betId,
                    matchId: WORLD_CUP_MATCH.id,
                    market,
                    pick,
                    label: entry.label,
                    stake,
                    odds: entry.odds,
                    at: Date.now(),
                    status: 'pending',
                    payout: 0,
                });
                window.playerState.worldCupBets = window.playerState.worldCupBets.slice(-40);
                playSfx('bong', true);
                updateUI();
                renderWorldCupBetPanel();
                await window.customAlert(`✅ 베팅 접수 완료!\n${entry.label} · ${formatBongAmount(stake)} × ${entry.odds.toFixed(2)}배`);
            } catch (e) {
                if (e && e.message === 'insufficient') {
                    return await window.customAlert('서버 최신 잔액 기준으로 삼봉이 부족합니다. 새로고침 후 다시 확인해 주세요.');
                }
                if (e && e.message === 'closed') {
                    return await window.customAlert('베팅 접수가 마감되었습니다.');
                }
                if (e && e.message === 'duplicate_market') {
                    return await window.customAlert(
                        `이미 [${WORLD_CUP_MARKET_LABELS[market]}] 항목에 베팅한 내역이 있습니다.\n같은 항목 보험베팅은 할 수 없어요.`
                    );
                }
                console.error('placeWorldCupBet', e);
                await window.customAlert('베팅 실패: ' + (e && e.message ? e.message : String(e)));
            }
        };

        window.toggleWorldCupBettingAdmin = async function(open) {
            if (!window.playerState || !window.playerState.isGM) return await window.customAlert(`${getMasterDisplayName()}만 변경할 수 있습니다.`);
            if (!db) return await window.customAlert('데이터베이스에 연결되지 않았습니다.');
            const wc = getWorldCupBetState();
            if (wc.settled) return await window.customAlert('이미 정산이 끝난 경기입니다.');
            if (open && isWorldCupBettingPastDeadline()) {
                return await window.customAlert(`베팅 마감 시한(${formatWorldCupBettingDeadlineLabel()})이 지나 재개할 수 없습니다.`);
            }
            try {
                const authOk = await ensureAnonAuthReady();
                if (!authOk) return await window.customAlert('인증에 실패했습니다.');
                const next = {
                    ...wc,
                    bettingOpen: !!open,
                };
                await setDoc(getGlobalSettingsDocRef(), { worldCupBet: next }, { merge: true });
                window.globalSettings.worldCupBet = next;
                renderWorldCupBetPanel();
                await window.customAlert(open ? '✅ 승부예측 베팅 접수를 재개했습니다.' : '⏸️ 승부예측 베팅 접수를 마감했습니다.');
            } catch (e) {
                console.error('toggleWorldCupBettingAdmin', e);
                await window.customAlert('설정 저장 실패: ' + (e && e.message ? e.message : String(e)));
            }
        };

        window.settleWorldCupBetAdmin = async function() {
            if (!window.playerState || !window.playerState.isGM) return await window.customAlert(`${getMasterDisplayName()}만 정산할 수 있습니다.`);
            if (!db) return await window.customAlert('데이터베이스에 연결되지 않았습니다.');
            const wc = getWorldCupBetState();
            if (wc.settled) return await window.customAlert('이미 정산된 경기입니다.');
            const result = readWorldCupAdminResultFromForm();
            if (!result) return await window.customAlert('32강 진출 결과를 선택한 뒤 정산해 주세요.');
            const { r32 } = result;
            const ok = await window.customConfirm(
                `승부예측 결과를 확정하고 배당을 지급할까요?\n\n` +
                `- 32강 진출: ${getWorldCupPickLabel('r32', r32)}\n\n` +
                '적중한 베팅에 배당금이 자동 지급됩니다.'
            );
            if (!ok) return;
            try {
                const authOk = await ensureAnonAuthReady();
                if (!authOk) return await window.customAlert('인증에 실패했습니다.');
                const settledAt = Date.now();
                const nextWc = {
                    matchId: WORLD_CUP_MATCH.id,
                    bettingOpen: false,
                    settled: true,
                    result,
                    settledAt,
                };
                let winnerCount = 0;
                let totalPayout = 0;
                const batch = writeBatch(db);
                const rows = (window.allStudentsData || []).filter((s) => s && s.id !== 'gm' && s.id !== 'gm_a');
                rows.forEach((stu) => {
                    const sid = String(stu.id);
                    const bets = Array.isArray(stu.worldCupBets) ? stu.worldCupBets.slice() : [];
                    let payoutSum = 0;
                    let changed = false;
                    const nextBets = bets.map((bet) => {
                        if (!bet || String(bet.matchId) !== WORLD_CUP_MATCH.id || bet.status !== 'pending') return bet;
                        changed = true;
                        const won = String(bet.pick) === String(result[bet.market]);
                        const payout = won ? normalizeBongValue(Number(bet.stake || 0) * Number(bet.odds || 0)) : 0;
                        if (won) {
                            payoutSum = normalizeBongValue(payoutSum + payout);
                            winnerCount += 1;
                        }
                        return { ...bet, status: won ? 'won' : 'lost', payout, settledAt };
                    });
                    if (!changed) return;
                    const ref = doc(db, 'artifacts', appId, 'public', 'data', 'students', 'student_' + sid);
                    const payload = { worldCupBets: nextBets.slice(-40) };
                    if (payoutSum > 0) payload.bong = increment(payoutSum);
                    batch.set(ref, payload, { merge: true });
                    totalPayout = normalizeBongValue(totalPayout + payoutSum);
                    if (sid === String(localStorage.getItem('sambong_student_id') || '')) {
                        window.playerState.worldCupBets = nextBets.slice(-40);
                        if (payoutSum > 0) {
                            window.playerState.bong = normalizeBongValue((Number(window.playerState.bong) || 0) + payoutSum);
                        }
                    }
                });
                batch.set(getGlobalSettingsDocRef(), { worldCupBet: nextWc }, { merge: true });
                await batch.commit();
                window.globalSettings.worldCupBet = nextWc;
                await refreshStudentsCacheFromServer();
                updateUI();
                renderWorldCupBetPanel();
                await window.customAlert(
                    `✅ 승부예측 정산 완료!\n적중 ${winnerCount}건 · 총 지급 ${formatBongAmount(totalPayout)}`
                );
            } catch (e) {
                console.error('settleWorldCupBetAdmin', e);
                await window.customAlert('정산 실패: ' + (e && e.message ? e.message : String(e)));
            }
        };

        /** 해당 항목에 대기 중인 내 베팅이 있는지 */
        function hasPendingWorldCupBetOnMarket(market) {
            return getMyWorldCupBets().some((b) => b && b.market === market && b.status === 'pending');
        }

        /** 지정 matchId 대기 베팅 취소 및 베팅금 환불 */
        async function cancelPendingWorldCupBetsForMatchIds(matchIds) {
            if (!db) return { cancelled: 0, refunded: 0, students: 0 };
            const idSet = new Set((matchIds || []).map(String));
            if (idSet.size === 0) return { cancelled: 0, refunded: 0, students: 0 };
            const studentsRef = collection(db, 'artifacts', appId, 'public', 'data', 'students');
            let snap;
            try {
                snap = await getDocsFromServer(studentsRef);
            } catch (e) {
                snap = await getDocs(studentsRef);
            }
            const batch = writeBatch(db);
            let cancelled = 0;
            let refunded = 0;
            let students = 0;
            const mySid = String(localStorage.getItem('sambong_student_id') || '');
            const cancelledAt = Date.now();
            snap.forEach((studentDoc) => {
                if (studentDoc.id === 'student_gm' || studentDoc.id === 'student_gm_a') return;
                const data = studentDoc.data() || {};
                const bets = Array.isArray(data.worldCupBets) ? data.worldCupBets.slice() : [];
                let refundSum = 0;
                let changed = false;
                const nextBets = bets.map((bet) => {
                    if (!bet || !idSet.has(String(bet.matchId)) || bet.status !== 'pending') return bet;
                    changed = true;
                    cancelled += 1;
                    const stake = normalizeBongValue(Number(bet.stake) || 0);
                    refundSum = normalizeBongValue(refundSum + stake);
                    return { ...bet, status: 'cancelled', payout: 0, cancelledAt, refund: stake };
                });
                if (!changed) return;
                students += 1;
                refunded = normalizeBongValue(refunded + refundSum);
                const payload = { worldCupBets: nextBets.slice(-40) };
                if (refundSum > 0) payload.bong = increment(refundSum);
                batch.set(studentDoc.ref, payload, { merge: true });
                const sid = studentDoc.id.replace(/^student_/, '');
                if (sid === mySid && window.playerState) {
                    window.playerState.worldCupBets = nextBets.slice(-40);
                    if (refundSum > 0) {
                        window.playerState.bong = normalizeBongValue((Number(window.playerState.bong) || 0) + refundSum);
                    }
                }
            });
            if (cancelled > 0) await batch.commit();
            return { cancelled, refunded, students };
        }

        /** 학급 전체 대기 베팅 취소 및 베팅금 환불 (현재 경기) */
        async function cancelPendingWorldCupBetsForAllStudents() {
            return cancelPendingWorldCupBetsForMatchIds([WORLD_CUP_MATCH.id]);
        }

        let _worldCupAutoCloseRunning = false;

        /** 마감 시각 이후 누군가 앱을 켜면 Firestore에 베팅 마감 상태를 1회 반영 */
        async function maybeAutoCloseWorldCupBetting(now = new Date()) {
            if (!db || _worldCupAutoCloseRunning || !isWorldCupBettingPastDeadline(now)) return;
            const raw = window.globalSettings && window.globalSettings.worldCupBet;
            if (!raw || typeof raw !== 'object') return;
            if (raw.settled) return;
            if (raw.matchId && String(raw.matchId) !== WORLD_CUP_MATCH.id) return;
            if (raw.bettingOpen === false) return;
            _worldCupAutoCloseRunning = true;
            try {
                const authOk = await ensureAnonAuthReady();
                if (!authOk) return;
                const settingsRef = getGlobalSettingsDocRef();
                const closedAt = now.getTime();
                const nextWc = {
                    ...raw,
                    matchId: WORLD_CUP_MATCH.id,
                    bettingOpen: false,
                    bettingClosedAt: closedAt,
                    autoClosedReason: 'deadline_20260628_1000',
                };
                await setDoc(settingsRef, { worldCupBet: nextWc }, { merge: true });
                if (window.globalSettings) window.globalSettings.worldCupBet = nextWc;
                if (window.playerState && !window.playerState.isGuest) {
                    renderWorldCupBetPanel();
                }
            } catch (e) {
                console.warn('maybeAutoCloseWorldCupBetting', e);
            } finally {
                _worldCupAutoCloseRunning = false;
            }
        }

        /** 배포 직후 1회 — 32강 진출 시장 전환: 이전 경기 대기 베팅 환불·설정 초기화 */
        async function applyWorldCupBetR32Migration() {
            if (!db) return;
            const markerId = 'worldcup_r32_advance_20260627_v1';
            const markerRef = doc(db, 'artifacts', appId, 'public', 'data', 'maintenance', markerId);
            try {
                const markerSnap = await getDoc(markerRef);
                if (markerSnap.exists() && markerSnap.data() && markerSnap.data().done) return;
                const authOk = await ensureAnonAuthReady();
                if (!authOk) return;
                const legacyMatchIds = ['kr_rsa_2026', 'kr_mex_2026'];
                const result = await cancelPendingWorldCupBetsForMatchIds(legacyMatchIds);
                const settingsRef = getGlobalSettingsDocRef();
                const settingsSnap = await getDoc(settingsRef);
                const wc = settingsSnap.exists() ? settingsSnap.data().worldCupBet : null;
                let resetSettings = false;
                if (wc && wc.matchId && String(wc.matchId) !== WORLD_CUP_MATCH.id) {
                    resetSettings = true;
                    await setDoc(settingsRef, {
                        worldCupBet: getSanitizedWorldCupBetState(null),
                    }, { merge: true });
                    if (window.globalSettings) {
                        window.globalSettings.worldCupBet = getSanitizedWorldCupBetState(null);
                    }
                }
                await setDoc(markerRef, {
                    done: true,
                    cancelled: result.cancelled,
                    refunded: result.refunded,
                    students: result.students,
                    resetSettings,
                    note: '32강 진출 시장 전환 — 이전 경기 대기 베팅 환불',
                    sanitizedAt: new Date().toISOString(),
                }, { merge: true });
                if (result.cancelled > 0 || resetSettings) {
                    await refreshStudentsCacheFromServer();
                    if (window.playerState && !window.playerState.isGuest) {
                        updateUI();
                        renderWorldCupBetPanel();
                    }
                }
            } catch (e) {
                console.warn('applyWorldCupBetR32Migration', e);
            }
        }

        /** 배포 직후 1회 — 배당 조정 전 대기 베팅 전량 취소·환불 */
