                            if (raidRewardXpEl && d.rewardMaxXp != null) raidRewardXpEl.value = String(d.rewardMaxXp);
                            if (raidRewardBongEl && d.rewardMaxBong != null) raidRewardBongEl.value = String(d.rewardMaxBong);
